INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '00951077-2f6d-4180-93ce-17b01ae7772f',
    'saint-joseph-fransizca-ogretmeni-00951077',
    'Fransızca Öğretmeni',
    'Saint-Joseph Fransız Lisesi',
    'Saint-Joseph Fransız Lisesi eğitim kadromuzda [şehir] yerleşkemizde Frankofon eğitim geleneğimiz doğrultusunda öğrencilerimize ileri düzeyde Fransızca dil ve edebiyat yetkinliği kazandıracak Fransızca Öğretmeni arıyoruz.

Görev Tanımı ve Sorumluluklar:
- Fransız Milli Eğitim Bakanlığı ve MEB ortak lise programı doğrultusunda Fransızca dil bilgisi, kompozisyon ve edebiyat derslerini yürütmek.
- Diller İçin Avrupa Ortak Başvuru Metni (CEFR) kriterlerine göre öğrencileri DELF B1 / B2 ve DALF C1 sınavlarına hazırlamak.
- Frankofon edebiyatı, felsefi metin çözümlemeleri ve tiyatro çalışmalarıyla öğrencilerin telaffuz ve sözlü ifade akıcılığını artırmak.
- Frankofoni haftası, münazara festivalleri ve Fransızca kültür-sanat etkinliklerini organize etmek.
- Zümre toplantılarına katılmak, dijital eğitim araçlarıyla (interaktif tahta, eğitim yazılımları) zenginleştirilmiş ders materyalleri hazırlamak.

Aranan Nitelikler:
- Üniversitelerin Fransız Dili ve Edebiyatı veya Fransızca Öğretmenliği bölümlerinden mezun.
- Pedagojik formasyon belgesine sahip (ana dili Fransızca olan yabancı uyruklu adaylar için ilgili bakanlık çalışma izin şartlarını taşıyan).
- Fransız ekolü okullarda veya nitelikli kolejlerde en az 3 yıl öğretmenlik tecrübesi.
- DELF/DALF sınav formatlarına ve sınav değerlendirici (examinateur-correcteur) kriterlerine hakim.
- Güçlü iletişim becerisine ve çağdaş pedagojik yaklaşıma sahip.',
    'FullTime',
    'OnSite',
    'SPECIALIST',
    '{"title": "Fransızca Öğretmeni", "jobType": "FullTime", "category": "EDUCATION", "language": "TR", "location": {"city": "Kocaeli"}, "positionLevel": "SPECIALIST", "modeOfOperation": "OnSite", "companyShortName": "Saint-Joseph Fransız Lisesi"}'::jsonb,
    'EDUCATION'
);

INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '00acb094-0c75-4307-90fe-0d569f4a2486',
    'ajet-hava-ta-imacili-i-bilet-sat-ve-rezervasyon-g-revlisi-1001299',
    'Bilet Satış ve Rezervasyon Görevlisi',
    'AJET HAVA TAŞIMACILIĞI',
    'Aşağıdaki niteliklere sahip ve belirtilen süreçleri yönetecek adayların başvurularını bekliyoruz: ''Bilet Satış ve Rezervasyon Görevlisi'' bünyemize kazandırılacaktır. İşin Tanımı: Yolculara iç ve dış hat uçak bileti satışı, bilet değişikliği ve iptal/iade işlemlerini Amadeus/Troya sisteminden yapacak. Beklenen Nitelikler: - Takım çalışmasına yatkın, üniforma ve kılık-kıyafet kurallarına özen gösteren - Havacılık sektöründe gerekli SHGM lisansı (B1/B2, Dispatcher vb.) veya lise/önlisans diploması olan - Havalimanı giriş kartı (apron kartı) almaya engel adli sicil kaydı bulunmayan - Gerektiğinde esnek çalışma saatlerine ve yoğun tempoya uyum sağlayabilecek Çalışma Şartları & Ücret: Aylık 35.000 TL Maaş + Yol + Yemek',
    'FullTime',
    'OnSite',
    'SPECIALIST',
