INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019ef3bf-1e86-7327-839c-7fcd3edc079e',
    'isin-olacak-technical-support-specialist-tier-1-1000135',
    'Technical Support Specialist (Tier 1)',
    'İŞİN OLACAK',
    'Şirketimizin SaaS platformu kapsamında büyüyen müşteri destek operasyonumuz için Tier 1 Technical Support Specialist (Seviye 1 Teknik Destek Uzmanı) pozisyonunda personel temini konusunda desteğinize ihtiyacımız bulunmaktadır. Görev tanımı: - Çağrı merkezi ve dijital kanallar üzerinden gelen müşteri taleplerinin karşılanması - Hesap açma, kullanıcı yönetimi ve temel konfigürasyon işlemlerinin yürütülmesi - Gelen teknik soruların ilk seviyede analiz edilerek çözüme kavuşturulması - Çözülemeyen vakaların uygun dokümantasyon ile Tier 2 / teknik ekibe eskale edilmesi - Ticket takibi, müşteri bilgilendirmesi ve SLA süreçlerinin yönetimi Aranan nitelikler: - Üniversitelerin Bilgisayar Mühendisliği bölümünden mezun - SaaS, çağrı merkezi veya teknik destek alanında tercihen 1-2 yıl deneyim - Yazılım geliştirme, API kullanımı ve web teknolojileri konusunda temel düzeyde bilgi - Veritabanı ve log inceleme konusunda bilgi sahibi olmak tercih sebebidir - Etkili iletişim, problem çözme ve analitik düşünme becerileri - Ticketing sistemleri (Zendesk, Freshdesk, Jira vb.) konusunda tecrübe artı olarak değerlendirilecektir.',
    'FullTime',
    'OnSite',
    'ASSISTANT_SPECIALIST',
