INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019ef94e-a888-7f64-ba86-f89644e8a09a',
    'aytasayhanlar-eksavator-operatoru-1000137',
    'EKSAVATÖR OPERATÖRÜ',
    'AYTAŞ',
    'Pozisyon kapsamında üstlenilecek temel sorumluluklar ve aranan yetkinlikler: Ekskavatör Operatörü istihdam edilecektir. Görev Tanımı [şehir] taş ocağı sahasında ekskavatör kullanımını iş güvenliği kurallarına uygun şekilde gerçekleştirmek, Kazı, yükleme, saha düzenleme ve üretim süreçlerine destek vermek, Makinenin günlük kontrollerini yapmak ve olası arıza/aksaklıkları ilgili birime bildirmek, Saha içi çalışma düzenine, vardiya planına ve operasyonel talimatlara uyum sağlamak, İş sağlığı ve güvenliği kurallarına eksiksiz riayet etmek. Aranan Nitelikler Ekskavatör operatörlüğünde deneyimli, G sınıfı ehliyet / operatörlük belgesine sahip, Taş ocağı, maden, şantiye veya benzer ağır iş sahalarında çalışmış, Makine kullanımında dikkatli, sorumluluk sahibi ve disiplinli, Vardiyalı çalışma düzenine uyum sağlayabilecek, İş güvenliği bilinci yüksek adaylar değerlendirilecektir. Çalışma Koşulları Lokasyon: [şehir] Taş Ocakları Pozisyon: Ekskavatör Operatörü Konaklama imkânı mevcuttur.',
