INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019ef95d-186c-7abd-a6a1-44c198d51bce',
    'aytasayhanlar-rok-yagcisi-1000139',
    'ROK YAĞCISI',
    'AYTAŞ',
    'Departmanımızda görev alarak operasyonel ve stratejik hedeflerimize katkı sağlayacak: Rok Yağcısı kadromuza katılacaktır. Görev Tanımı [şehir] taş ocağı sahasında kullanılan rok makinesi ve ilgili ekipmanların yağlama süreçlerine destek vermek, Makine yağ seviyelerini, yağlama noktalarını ve ekipman durumunu günlük olarak kontrol etmek, Sondaj ve üretim süreçlerinin güvenli, düzenli ve kesintisiz şekilde ilerlemesine katkı sağlamak, Makinede oluşabilecek arıza, sızıntı, aşınma veya bakım ihtiyaçlarını ilgili birime bildirmek, Saha içi çalışma düzenine, vardiya planına ve operasyonel talimatlara uyum sağlamak, İş sağlığı ve güvenliği kurallarına eksiksiz riayet etmek. Aranan Nitelikler Rok makinesi, iş makinesi veya ağır ekipman yağlama süreçlerinde deneyimli, Tercihen taş ocağı, maden, şantiye veya benzer ağır iş sahalarında çalışmış, Makine yağlama ve temel bakım kontrolleri konusunda bilgi sahibi, Saha çalışma disiplinine uyumlu, dikkatli ve sorumluluk sahibi, Vardiyalı çalışma düzenine uyum sağlayabilecek, İş güvenliği bilinci yüksek adaylar değerlendirilecektir. Çalışma Koşulları Lokasyon: [şehir] Taş Ocakları Pozisyon: Rok Yağcısı Konaklama imkânı mevcuttur.',
