INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f12d2-e556-78f0-815a-d815ff53e7a4',
    'ayhanlartunasaltay-temizlik-gorevlisi-1000144',
    'TEMİZLİK GÖREVLİSİ',
    'AYHANLARTUNASALTAY',
    'Genel Nitelikler En az ilkokul mezunu, Tercihen daha önce AVM, otel, hastane veya iş merkezi gibi büyük projelerde temizlik personeli olarak görev yapmış, Temizlik malzemeleri, ekipmanları ve hijyen kuralları konusunda bilgi sahibi (Zemin yıkama makinesi kullanabilmek tercih sebebidir), Vardiyalı çalışma sistemine ve esnek çalışma saatlerine uyum sağlayabilecek, Fiziksel olarak dinamik bir çalışma temposuna ayak uydurabilecek, İletişimi güçlü, güler yüzlü ve takım çalışmasına yatkın, Kişisel bakımına ve dış görünüşüne özen gösteren. İş Tanımı AVM genel alanlarının (koridorlar, ortak alanlar, yürüyen merdivenler, tuvaletler vb.) hijyen standartlarına uygun olarak temizlenmesi, Çöp kovalarının düzenli olarak boşaltılması ve atık yönetiminin sağlanması, Gün içinde belirlenen periyotlarla zeminlerin paspaslanması ve yüzeylerin dezenfekte edilmesi, Temizlik sırasında kullanılan makine, araç ve gereçlerin temiz ve düzenli tutulması, AVM ziyaretçilerinden gelebilecek anlık temizlik taleplerine hızlı ve profesyonel şekilde müdahale edilmesi.',
