INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f12d4-e5f6-70b8-9958-cc245d7b659b',
    'ayhanlartunasaltay-guvenlik-gorevlisi-1000145',
    'GÜVENLİK GÖREVLİSİ',
    'AYHANLARTUNASALTAY',
    'Genel Nitelikler 5188 Sayılı Özel Güvenlik Hizmetlerine Dair Kanun uyarınca, geçerli Silahlı veya Silahsız Özel Güvenlik Kimlik Kartı sahibi, En az lise mezunu, Tercihen AVM, otel, iş merkezi veya benzeri yoğun ziyaretçi alan projelerde güvenlik deneyimi olan, Vardiyalı çalışma sistemine ve esnek çalışma saatlerine (gece vardiyası dahil) uyum sağlayabilecek, Etkin iletişim becerilerine sahip, kriz anlarında sakin ve çözüm odaklı kalabilen, Diksiyonu düzgün, güler yüzlü, dış görünümüne ve kişisel bakımına özen gösteren, Takım çalışmasına yatkın ve sorumluluk bilinci yüksek, Erkek adaylar için askerlik hizmetini tamamlamış veya muaf. İş Tanımı AVM giriş kapılarında (X-Ray cihazı ve metal dedektör kontrol noktalarında) ziyaretçilerin ve eşyaların güvenli geçişini sağlamak, AVM genel alanlarında, otoparkta ve mağaza önlerinde düzenli devriye atarak huzur ve güvenliği korumak, AVM kurallarına, yasa ve yönetmeliklere aykırı durumları (şüpheli paket, hırsızlık, kavga vb.) anında tespit etmek ve merkeze raporlayarak gerekli müdahaleyi yapmak, Acil durumlarda (yangın, tahliye, ilkyardım vb.) önceden belirlenmiş eylem planlarına uygun olarak yönlendirmeleri yapmak, CCTV (Kamera odası) görevlendirmelerinde kameraları titizlikle takip etmek ve şüpheli durumları sahaya bildirmek.',
    'FullTime',
    'OnSite',
    'ENTRY_LEVEL',
    '{"slug": "ayhanlartunasaltay-guvenlik-gorevlisi-1000145", "title": "GÜVENLİK GÖREVLİSİ", "_docId": "019f12d4-e5fb-7dda-9daf-f40c201d8e20", "branchId": "019dddfd-3f4f-7747-9f9e-f6f968ebbf31", "industry": "SECURITY_EMERGENCY", "location": {"latitude": 39.6484, "longitude": 27.8864, "__typename": "Location", "city": "Diyarbakır"}, "accountId": "019dddfd-3f3e-7d37-bf7f-ca580a2fa915", "companyId": "019dddfd-3f47-7b9a-941d-1f8d6d6eb417", "createdAt": "2026-06-29T10:02:50.236Z", "locations": [{"latitude": 39.6484, "longitude": 27.8864, "__typename": "Location"}], "updatedAt": "2026-06-29T10:02:50.236Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<h3><strong>Genel Nitelikler</strong></h3><ul><li><p><strong>5188 Sayılı Özel Güvenlik Hizmetlerine Dair Kanun</strong> uyarınca, geçerli <strong>Silahlı veya Silahsız Özel Güvenlik Kimlik Kartı</strong> sahibi,</p></li><li><p>En az lise mezunu,</p></li><li><p>Tercihen AVM, otel, iş merkezi veya benzeri yoğun ziyaretçi alan projelerde güvenlik deneyimi olan,</p></li><li><p>Vardiyalı çalışma sistemine ve esnek çalışma saatlerine (gece vardiyası dahil) uyum sağlayabilecek,</p></li><li><p>Etkin iletişim becerilerine sahip, kriz anlarında sakin ve çözüm odaklı kalabilen,</p></li><li><p>Diksiyonu düzgün, güler yüzlü, dış görünümüne ve kişisel bakımına özen gösteren,</p></li><li><p>Takım çalışmasına yatkın ve sorumluluk bilinci yüksek,</p></li><li><p>Erkek adaylar için askerlik hizmetini tamamlamış veya muaf.</p></li></ul><h3><strong>İş Tanımı</strong></h3><ul><li><p>AVM giriş kapılarında (X-Ray cihazı ve metal dedektör kontrol noktalarında) ziyaretçilerin ve eşyaların güvenli geçişini sağlamak,</p></li><li><p>AVM genel alanlarında, otoparkta ve mağaza önlerinde düzenli devriye atarak huzur ve güvenliği korumak,</p></li><li><p>AVM kurallarına, yasa ve yönetmeliklere aykırı durumları (şüpheli paket, hır