INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f1324-fe76-7dbd-8295-ec149ebbe6be',
    'holding-satin-alma-uzmani-1000147',
    'SATIN ALMA UZMANI',
    'HOLDING',
    'Aşağıdaki niteliklere sahip ve belirtilen süreçleri yönetecek adayların başvurularını bekliyoruz: ; satın alma süreçlerini etkin şekilde yürütebilecek, tedarikçi yönetimi ve fiyat analizi konularında güçlü Satın Alma Uzmanı ekibimize katılacak çalışma arkadaşı aranmaktadır. Görev Tanımı Şirket ihtiyaçları doğrultusunda satın alma süreçlerini yürütmek, Tedarikçi araştırması yapmak, teklif toplamak ve fiyat karşılaştırma süreçlerini yönetmek, Satın alma taleplerinin uygun maliyet, kalite ve termin kriterlerine göre değerlendirilmesini sağlamak, Mevcut tedarikçilerle ilişkileri yürütmek ve alternatif tedarikçi ağı oluşturmak, Sipariş, teslimat ve fatura süreçlerini ilgili birimlerle koordineli şekilde takip etmek, Satın alma sözleşmeleri, teklif formları ve ilgili dokümantasyon süreçlerine destek vermek, Piyasa araştırması yaparak maliyet avantajı sağlayacak aksiyonlar geliştirmek, Satın alma raporlarını hazırlamak ve yönetime düzenli bilgi akışı sağlamak. Aranan Nitelikler Üniversitelerin ilgili bölümlerinden mezun, Satın alma alanında tercihen en az 2 yıl deneyimli, Tedarikçi yönetimi, teklif toplama ve pazarlık süreçlerinde yetkin, MS Office programlarını etkin kullanabilen, Analitik düşünebilen, maliyet bilinci yüksek ve sonuç odaklı, İletişimi güçlü, takip ve raporlama yönü kuvvetli, Yoğun iş temposuna uyum sağlayabilecek, Takım çalışmasına yatkın ve sorumluluk bilinci yüksek, [şehir] lokasyonuna ulaşım problemi bulunmayan.',
    'FullTime',
    'OnSite',
    'ASSISTANT_SPECIALIST',
    '{"slug": "holding-satin-alma-uzmani-1000147", "title": "SATIN ALMA UZMANI", "_docId": "019f1324-fe7b-75ef-be9e-f4c91623e52e", "branchId": "019f1322-6d58-76f4-9461-129729ed40c2", "industry": "SUPPLY_CHAIN_LOGISTICS", "location": {"latitude": 40.800010322078, "longitude": 29.42565897725509, "__typename": "Location", "city": "Kocaeli"}, "accountId": "019dde01-d0e3-7709-be35-7ea69bdd2f38", "companyId": "019ef9f9-17f4-71dc-9204-4ef0beac817d", "createdAt": "2026-06-29T11:30:19.383Z", "locations": [{"latitude": 40.800010322078, "longitude": 29.42565897725509, "__typename": "Location"}], "minSalary": 28075, "updatedAt": "2026-06-29T11:30:19.383Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<p>Ayhanlar Holding bünyesinde, <strong>[şehir] lokasyonunda</strong> görevlendirilmek üzere; satın alma süreçlerini etkin şekilde yürütebilecek, tedarikçi yönetimi ve fiyat analizi konularında güçlü <strong>Satın Alma Uzmanı</strong> bünyemizde görev alacak yetkin adaylar değerlendirilecektir.</p><h3>Görev Tanımı</h3><p>Şirket ihtiyaçları doğrultusunda satın alma süreçlerini yürütmek,<br>Tedarikçi araştırması yapmak, teklif toplamak ve fiyat karşılaştırma süreçlerini yönetmek,<br>Satın alma taleplerinin uygun maliyet, kalite ve termin kriterlerine göre değerlendirilmesini sağlamak,<br>Mevcut tedarikçilerle ilişkileri yürütmek ve alternatif tedarikçi ağı oluşturmak,<br>Sipariş, teslimat ve fatura süreçlerini ilgili birimlerle koordineli şekilde takip etmek,<br>Satın alma sözleşmeleri, teklif formları ve ilgili dokümantasyon süreçlerine destek vermek,<br>Piyasa araştırması yaparak maliyet avantajı sağlayacak aksiyonlar geliştirmek,<br>Satın alma raporlarını hazırlamak ve yönetime düzenli bilgi akışı sağlamak.</p><h3>Aranan Nitelikler</h3><p>Üniversitelerin ilgili bölümlerinden mezun,<br>Satın alma alanında tercihen en az 2 yıl deneyimli,<br>Tedarikçi yönetimi, teklif toplama ve pazarlık süreçlerinde yetkin,<br>MS Office programlarını etkin kullanabilen,<br>Analitik düşünebilen, maliyet bilinci yüksek ve sonuç odaklı,<br>İletişimi güçlü, takip ve raporlama yönü kuvvetli,<br>Yoğun iş temposuna uyum sağlayabilecek,<br>Takım çalışmasına yatkın ve sorumluluk bilinci yüksek,<br>[şehir] lokasyonuna ulaşım problemi bulunmayan.</p>", "publishedAt": "2026-06-29T11:49:26.798Z", "currencyCode": "TRY", "positionLevel": "ASSISTANT_SPECIALIST", "isConfidential": false, "advertisementId": "019f1324-fe76-7dbd-8295-ec149ebbe6be", "isMostPreferred": false, "statusUpdatedAt": "2026-06-29T11:49:26.798Z", "companyShortName": "HOLDING", "locationSourceType": "Branch", "advertisementNumber": "1000147", "advertisementStatus": "Approved", "advertisementJobType": "FullTime", "advertisementModeOfOperation": "OnSite", "advertisementRecruitmentProcess": {"id": "019ef966-f4e6-77e7-a5aa-58432026fd84", "data": {"nodes": [{"id": "node-placeholder-1782300733362", "data": {"label": "STANDART", "_isPlaceholder": true}, "type": "processStep", "position": {"x": 0, "y": 0}}]}, "name": "STANDART", "version": 1, "isActive": true, "isSystem": false, "accountId": "019dde01-d0e3-7709-be35-7ea69bdd2f38", "createdAt": "2026-06-24T11:32:14.691Z", "isDefault": false, "updatedAt": "2026-06-24T11:32:14.691Z", "__typename": "AdvertisementRecruitmentProcess"}, "advertisementRecruitmentProcessId": "019ef966-f4e6-77e7-a5aa-58432026fd84", "advertisementRecruitmentProcessVersionId": "019ef966-f4e8-785f-800b-e40a880dddbe", "AdvertisementRecruitmentProcessVersionNodeTranslation": [{"id": "019ef966-f4ea-771d-95ca-f1cfb3dd7431", "label": "STANDART", "nodeId": "node-placeholder-1782300733362", "createdAt": "2026-06-24T11:32:14.696Z", "updatedAt": "2026-06-24T11:32:14.696Z", "__typename": "GetAdvertisementRecruitmentProcessVersionNodeTranslationResponseDto", "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "advertisementRecruitmentProcessVersionId": "019ef966-f4e8-785f-80