INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f1326-8767-726d-9fe3-f8b805ec1297',
    'holding-idari-isler-elemani-1000148',
    'İDARİ İŞLER ELEMANI',
    'HOLDING',
    'Ekibimizi güçlendirmek amacıyla aramıza katılacak çalışma arkadaşları arıyoruz: ; idari işler süreçlerinde operasyonel destek sağlayacak, saha ve ofis koordinasyonunu güçlü şekilde yürütebilecek İdari İşler Elemanı ekibimize katılacak çalışma arkadaşı aranmaktadır. Görev Tanımı Şirketin günlük idari işler operasyonlarına destek vermek, Ofis, yemekhane, temizlik, servis, güvenlik ve genel alan süreçlerinin takibini sağlamak, İdari işlere bağlı malzeme, ekipman ve ihtiyaçların kontrolünü yapmak, Tedarik, teslimat ve stok süreçlerinde ilgili birimlerle koordineli çalışmak, Şirket içi bakım, onarım ve düzen süreçlerinin takibini gerçekleştirmek, Personel taleplerini ilgili prosedürler kapsamında değerlendirmek ve yönlendirmek, İdari işler kapsamında raporlama ve evrak takibi yapmak, İş sağlığı, güvenliği ve hijyen kurallarına uygun çalışma düzenini desteklemek. Aranan Nitelikler Tercihen idari işler veya operasyonel destek alanında deneyimli, MS Office programlarını temel düzeyde kullanabilen, Takip, koordinasyon ve iletişim yönü güçlü, Sorumluluk bilinci yüksek, düzenli ve çözüm odaklı, Yoğun iş temposuna uyum sağlayabilecek, Ekip çalışmasına yatkın, [şehir] lokasyonuna ulaşım problemi bulunmayan.',
    'FullTime',
    'OnSite',
    'ASSISTANT_SPECIALIST',
