INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f132a-b26d-70b9-bbbb-2c2583f8f4fb',
    'ayfalt-otomotiv-bakimci-1000150',
    'OTOMOTİV BAKIMCI',
    'AYFALT',
    'Takımımıza dahil olacak profesyonelde aradığımız temel özellikler ve iş kapsamı: ; araç bakım, onarım ve teknik destek süreçlerinde görev alacak Otomotiv Bakımcı kadromuza katılacaktır. Görev Tanımı Şirket araçlarının periyodik bakım ve kontrollerini gerçekleştirmek, Araçlarda oluşan mekanik arıza ve aksaklıkları tespit ederek gerekli müdahaleleri yapmak, Motor, fren, süspansiyon, şanzıman, yağ değişimi ve genel bakım süreçlerinde görev almak, Bakım-onarım işlemlerinin iş güvenliği kurallarına uygun şekilde yürütülmesini sağlamak, Arıza tespit edilen araçları ilgili amire zamanında bildirmek, Kullanılan ekipman, el aletleri ve bakım alanının düzenini sağlamak, Yedek parça ihtiyaçlarını takip ederek ilgili birimlere bilgi vermek, Bakım kayıtlarının düzenli şekilde tutulmasına destek olmak. Aranan Nitelikler Tercihen meslek lisesi veya meslek yüksekokullarının Motor, Otomotiv, Makine vb. bölümlerinden mezun, Otomotiv bakım-onarım alanında deneyimli, Araç mekanik sistemleri hakkında bilgi sahibi, El aletleri ve bakım ekipmanlarını etkin kullanabilen, İş sağlığı ve güvenliği kurallarına uygun çalışabilecek, Takip yönü güçlü, dikkatli ve sorumluluk sahibi, Ekip çalışmasına yatkın, Yoğun çalışma temposuna uyum sağlayabilecek, [şehir] lokasyonuna ulaşım problemi bulunmayan.',
    'FullTime',
    'OnSite',
    'ASSISTANT_SPECIALIST',
    '{"slug": "ayfalt-otomotiv-bakimci-1000150", "title": "OTOMOTİV BAKIMCI", "_docId": "019f132a-b271-70bf-b28e-6668e47407b0", "branchId": "019f1328-4d8b-7c8a-912e-db1035153202", "category": "INDUSTRIAL_MANUFACTURING", "industry": "INDUSTRIAL_MANUFACTURING", "location": {"latitude": 40.81149418336688, "longitude": 29.46772999853095, "__typename": "Location", "city": "Kocaeli"}, "accountId": "019dde01-d0e3-7709-be35-7ea69bdd2f38", "companyId": "019ef9f9-e1f9-7454-9be3-b6fa86b1f0f8", "createdAt": "2026-06-29T11:36:33.133Z", "locations": [{"latitude": 40.81149418336688, "longitude": 29.46772999853095, "__typename": "Location"}], "minSalary": 28075, "updatedAt": "2026-06-29T11:36:33.133Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<p>Ayhanlar Holding bünyesinde, <strong>[şehir] lokasyonunda</strong> görevlendirilmek üzere; araç bakım, onarım ve teknik destek süreçlerinde görev alacak <strong>Otomotiv Bakımcı</strong> pozisyonu için başvurular değerlendirilecektir.</p><h3>Görev Tanımı</h3><p>Şirket araçlarının periyodik bakım ve kontrollerini gerçekleştirmek,<br>Araçlarda oluşan mekanik arıza ve aksaklıkları tespit ederek gerekli müdahaleleri yapmak,<br>Motor, fren, süspansiyon, şanzıman, yağ değişimi ve genel bakım süreçlerinde görev almak,<br>Bakım-onarım işlemlerinin iş güvenliği kurallarına uygun şekilde yürütülmesini sağlamak,<br>Arıza tespit edilen araçları ilgili amire zamanında bildirmek,<br>Kullanılan ekipman, el aletleri ve bakım alanının düzenini sağlamak,<br>Yedek parça ihtiyaçlarını takip ederek ilgili birimlere bilgi vermek,<br>Bakım kayıtlarının düzenli şekilde tutulmasına destek olmak.</p><h3>Aranan Nitelikler</h3><p>Tercihen meslek lisesi veya meslek yüksekokullarının Motor, Otomotiv, Makine vb. bölümlerinden mezun,<br>Otomotiv bakım-onarım alanında deneyimli,<br>Araç mekanik sistemleri hakkında bilgi sahibi,<br>El aletleri ve bakım ekipmanlarını etkin kullanabilen,<br>İş sağlığı ve güvenliği kurallarına uygun çalışabilecek,<br>Takip yönü güçlü, dikkatli ve sorumluluk sahibi,<br>Ekip çalışmasına yatkın,<br>Yoğun çalışma temposuna uyum sağlayabilecek,<br>[şehir] lokasyonuna ulaşım problemi bulunmayan.</p>", "publishedAt": "2026-06-29T11:49:11.485Z", "currencyCode": "TRY", "positionLevel": "ASSISTANT_SPECIALIST", "isConfidential": false, "advertisementId": "019f132a-b26d-70b9-bbbb-2c2583f8f4fb", "isMostPreferred": false, "statusUpdatedAt": "2026-06-29T11:49:11.485Z", "companyShortName": "AYFALT", "locationSourceType": "Branch", "advertisementNumber": "1000150", "advertisementStatus": "Approved", "advertisementJobType": "FullTime", "advertisementModeOfOperation": "OnSite", "advertisementRecruitmentProcess": {"id": "019ef966-f4e6-77e7-a5aa-58432026fd84", "data": {"nodes": [{"id": "node-placeholder-1782300733362", "data": {"label": "STANDART", "_isPlaceholder": true}, "type": "processStep", "position": {"x": 0, "y": 0}}]}, "name": "STANDART", "version": 1, "isActive": true, "isSystem": false, "accountId": "019dde01-d0e3-7709-be35-7ea69bdd2f38", "createdAt": "2026-06-24T11:32:14.691Z", "isDefault": false, "updatedAt": "2026-06-24T11:32:14.691Z", "__typename": "AdvertisementRecruitmentProcess"}, "advertisementRecruitmentProcessId": "019ef966-f4e6-77e7-a5aa-58432026fd84", "advertisementRecruitmentProcessVersionId": "019ef966-f4e8-785f-800b-e40a880dddbe", "AdvertisementRecruitmentProcessVersionNodeTranslation": [{"id": "019ef966-f4ea-771d-95ca-f1cfb3dd7431", "label": "STANDART", "nodeId": "node-placeholder-1782300733362", "createdAt": "2026-06-24T11:32:14.696Z", "updatedAt": "2026-06-24T11:32:14.696Z", "__typename": "GetAdvertisementRecruitmentProcessVersionNodeTranslationResponseDto", "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "advertisementRecruitmentProcessVersionId": "019ef966-f4e8-785f-800b-e40a880dddbe"}, {"id": "019ef966-f4ea-78cf-b756-ba62e151c28b", "label": "Standart", "nodeId": "node-placeholder-1782300733362", "createdAt": "2026-06-24T11:32:14.696Z", "updatedAt": "2026-06-24T11:32:14.696Z", "__typename": "GetAdvertisementRecruitmentProcessVersionNodeTranslationResponseDto", "languageId": "019d61b4-cffe-7552-b5ac-ee38dcf97438", "advertisementRecruitmentProcessVersionId": "019ef966-f4e8-785f-800b-e40a880dddbe"}], "jobType": "FullTime", "modeOfOperation": "OnSite"}'::jsonb,
