INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f132e-d42b-7845-a065-ca5e2b8f9dba',
    'hazirbeton-beton-pompa-operatoru-1000152',
    'BETON POMPA OPERATÖRÜ',
    'HAZIRBETON',
    'Departmanımızda görev alarak operasyonel ve stratejik hedeflerimize katkı sağlayacak: ; hazır beton saha operasyonlarında görev alacak Beton Pompa Operatörü rolünde çalışacak profesyoneller aranmaktadır. Görev Tanımı Beton pompa aracını iş sağlığı ve güvenliği kurallarına uygun şekilde kullanmak, Hazır betonun şantiye sahasında güvenli, doğru ve zamanında pompalanmasını sağlamak, Pompa kurulumu, hortum bağlantıları, bom açma/kapama ve beton basım süreçlerini operasyon talimatlarına uygun yürütmek, Araç ve ekipmanın günlük bakım, temizlik ve kontrollerini gerçekleştirmek, Pompa basımı sırasında saha ekibi ve mikser operatörleri ile koordineli çalışmak, Araçta veya ekipmanda oluşabilecek arıza ve aksaklıkları ilgili amire zamanında bildirmek, Sevkiyat ve saha süreçlerine ilişkin gerekli evrak takibini yapmak, Şantiye kurallarına, trafik kurallarına ve şirket prosedürlerine eksiksiz uyum sağlamak. Aranan Nitelikler Tercihen hazır beton sektöründe beton pompa operatörü olarak deneyimli, Gerekli sürücü belgesi, SRC ve psikoteknik belgelerine sahip, Beton pompa aracı ve ekipman kullanımı konusunda bilgi sahibi, Saha çalışma koşullarına ve yoğun iş temposuna uyum sağlayabilecek, İş sağlığı ve güvenliği kurallarına uygun çalışabilecek, Dikkatli, disiplinli ve sorumluluk bilinci yüksek, Ekip çalışmasına yatkın, iletişimi güçlü, [şehir] lokasyonuna ulaşım problemi bulunmayan.',
    'FullTime',
    'OnSite',
    'ASSISTANT_SPECIALIST',
    '{"slug": "hazirbeton-beton-pompa-operatoru-1000152", "title": "BETON POMPA OPERATÖRÜ", "_docId": "019f132e-d42e-79de-ab0c-13c9a13435eb", "branchId": "019f132b-f2c9-7a61-b30a-35b51b5d8eea", "industry": "CONSTRUCTION", "location": {"latitude": 40.83754457894427, "longitude": 29.4615769755234, "__typename": "Location", "city": "Kocaeli"}, "accountId": "019dde01-d0e3-7709-be35-7ea69bdd2f38", "companyId": "019ef9f7-6de1-760e-812f-a18a53307b22", "createdAt": "2026-06-29T11:41:03.915Z", "locations": [{"latitude": 40.83754457894427, "longitude": 29.4615769755234, "__typename": "Location"}], "minSalary": 28075, "updatedAt": "2026-06-29T11:41:03.915Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<p>Ayhanlar Holding bünyesinde, <strong>[şehir] lokasyonunda</strong> görevlendirilmek üzere; hazır beton saha operasyonlarında görev alacak <strong>Beton Pompa Operatörü</strong> pozisyonu için başvurular değerlendirilecektir.</p><h3>Görev Tanımı</h3><p>Beton pompa aracını iş sağlığı ve güvenliği kurallarına uygun şekilde kullanmak,<br>Hazır betonun şantiye sahasında güvenli, doğru ve zamanında pompalanmasını sağlamak,<br>Pompa kurulumu, hortum bağlantıları, bom açma/kapama ve beton basım süreçlerini operasyon talimatlarına uygun yürütmek,<br>Araç ve ekipmanın günlük bakım, temizlik ve kontrollerini gerçekleştirmek,<br>Pompa basımı sırasında saha ekibi ve mikser operatörleri ile koordineli çalışmak,<br>Araçta veya ekipmanda oluşabilecek arıza ve aksaklıkları ilgili amire zamanında bildirmek,<br>Sevkiyat ve saha süreçlerine ilişkin gerekli evrak takibini yapmak,<br>Şantiye kurallarına, trafik kurallarına ve şirket prosedürlerine eksiksiz uyum sağlamak.</p><h3>Aranan Nitelikler</h3><p>Tercihen hazır beton sektöründe <strong>beton pompa operatörü</strong> olarak deneyimli,<br>Gerekli sürücü belgesi, SRC ve psikoteknik belgelerine sahip,<br>Beton pompa aracı ve ekipman kullanımı konusunda bilgi sahibi,<br>Saha çalışma koşullarına ve yoğun iş temposuna uyum sağlayabilecek,<br>İş sağlığı ve güvenliği kurallarına uygun çalışabilecek,<br>Dikkatli, disiplinli ve sorumluluk bilinci yüksek,<br>Ekip çalışmasına yatkın, iletişimi güçlü,<br>[şehir] lokasyonuna ulaşım problemi bulunmayan.</p>", "publishedAt": "2026-06-29T11:48:59.503Z", "currencyCode": "TRY", "positionLevel": "ASSISTANT_SPECIALIST", "isConfidential": false, "advertisementId": "019f132e-d42b-7845-a065-ca5e2b8f9dba", "isMostPreferred": false, "statusUpdatedAt": "2026-06-29T11:48:59.503Z", "companyShortName": "HAZIRBETON", "locationSourceType": "Branch", "advertisementNumber": "1000152", "advertisementStatus": "Approved", "advertisementJobType": "FullTime", "advertisementModeOfOperation": "OnSite", "advertisementRecruitmentProcess": {"id": "019ef966-f4e6-77e7-a5aa-58432026fd84", "data": {"nodes": [{"id": "node-placeholder-1782300733362", "data": {"label": "STANDART", "_isPlaceholder": true}, "type": "processStep", "position": {"x": 0, "y": 0}}]}, "name": "STANDART", "version": 1, "isActive": true, "isSystem": false, "accountId": "019dde01-d0e3-7709-be35-7ea69bdd2f38", "createdAt": "2026-06-24T11:32:14.691Z", "isDefault": false, "updatedAt": "2026-06-24T11:32:14.691Z", "__typename": "AdvertisementRecruitmentProcess"}, "advertisementRecruitmentProcessId": "019ef966-f4e6-77e7-a5aa-58432026fd84", "advertisementRecruitmentProcessVersionId": "019ef966-f4e8-785f-800b-e40a880dddbe", "AdvertisementRecruitmentProcessVersionNodeTranslation": [{"id": "019ef966-f4ea-771d-95ca-f1cfb3dd7431", "label": "STANDART", "nodeId": "node-placeholder-1782300733362", "createdAt": "2026-06-24T11:32:14.696Z", "updatedAt": "2026-06-24T11:32:14.696Z", "__typename": "GetAdvertisementRecruitmentProcessVersionNodeTranslationResponseDto", "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "advertisementRecruitmentProcessVersionId": "019ef966-f4e8-785f-800b-e40a880dddbe"}, {"id": "019ef966-f4