INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f3751-e44b-7826-a458-88b7f153f2f6',
    'qubeautyuskudarsi-estetisyen-1000161',
    'ESTETİSYEN',
    'QU BEAUTY USKUDAR',
    'QU Güzellik Merkezi olarak, büyüyen ekibimize katılacak, mesleğini severek yapan ve danışan memnuniyetini ön planda tutan deneyimli bir Estetisyen arıyoruz. * Lazer Epilasyon, Cilt Bakımı ve Bölgesel İncelme uygulamalarında deneyimli, * Danışan iletişimi güçlü, güler yüzlü ve çözüm odaklı, * İş disiplinine sahip, sorumluluk bilinci yüksek, * Ekip çalışmasına uyumlu, * Dış görünümüne özen gösteren, prezentabl, * Mesleki gelişime ve yeniliklere açık, * Hijyen kurallarına önem veren ve titizlikle uygulayan, * Tercihen satış ve danışan yönlendirme konusunda deneyimli. Kaliteli hizmet anlayışımızı birlikte büyütecek, enerjisi yüksek ve profesyonel çalışma arkadaşlarımızı ekibimize bekliyoruz. Başvuru için özgeçmişinizi bizimle paylaşabilirsiniz. QU Güzellik Merkezi',
