INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f40bc-2b86-75fd-abc2-8f37df760ee8',
    'starvisioncasting-dizi-sinema-reklam-ve-klip-projelerimizde-yer-alacak-kadin-erkek-deneyimli-ya-da-deneyimsiz-yardimci-oyuncu-ve-figuran-calisma-arkadaslari-ariyoruz-1000164',
    'Dizi, sinema, reklam ve klip projelerimizde yer alacak; kadın-erkek, deneyimli ya da deneyimsiz Yardımcı Oyuncu ve Figüran çalışma arkadaşları arıyoruz! 🎭',
    'STAR_VISION_CASTING',
