INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f4838-df9c-7038-9e66-db571848db4b',
    'yektateknoloji-satis-ve-pazarlama-sorumlusu-temsilcisi-1000165',
    'Kurumsal B2B Satış Danışmanı ve Portföy Satış Temsilcisi (Yazılım)',
    'YEKTA_TEKNOLOJI',
    '​İş Tanımı: Yekta Teknoloji bünyesinde, geliştirdiğimiz yenilikçi yazılım çözümleri, SaaS platformları ve sektörel dijital sistemlerin (B2B) kurumsal satış ve pazarlama süreçlerini yönetecek, dinamik ve hedef odaklı Satış ve Pazarlama Sorumlusu arıyoruz. ​Ekibimize katılacak çalışma arkadaşımız; potansiyel müşteri portföyünü genişletmekten, aktif saha/online sunumlar gerçekleştirmekten ve satış kapama süreçlerinden sorumlu olacaktır. ​Genel Nitelikler: ​Tercihen yazılım, teknoloji, SaaS veya kurumsal hizmet (B2B) satışı konusunda deneyimli veya bu alanlara yoğun ilgisi olan, ​Teknolojik trendleri, dijital platformları ve sektörel yenilikleri hızlı kavrayabilen, ​İletişim becerileri, ikna kabiliyeti ve sunum yeteneği yüksek, ​"Hayır" cevabını bir engel değil, sürecin bir parçası olarak gören (Reddedilme direnci yüksek), ​Müşteri portföyü oluşturma, takip (follow-up) ve CRM yönetimi disiplinine sahip, ​(Varsa araç gereksinimi: Aktif araç kullanabilen ve seyahat engeli olmayan). ​Sorumluluklar: ​Potansiyel kurumsal müşterileri (acente, firma, fabrika vb.) tespit edip soğuk arama (cold call) ve ziyaretler yoluyla ilk teması kurmak, ​Geliştirdiğimiz çözümlerin ve platformların değer önerisini müşteriye net ve profesyonel bir dille aktarmak, sunumlar yapmak, ​Teklif süreçlerini yönetmek, satış hedeflerine ulaşmak için aktif stratejiler geliştirmek, ​Mevcut müşterilerle ilişkileri sürdürüp memnuniyet takibi yapmak. ​Ne Sunuyoruz? ​Sabit Maaş + Performansa Dayalı Tatminkar Prim Sistemi ​Yenilikçi, dinamik ve gelişime açık bir çalışma ortamı ​Yol + Yemek + Gerekli Teknik Donanım Kurumsal B2B satış, doğrudan saha satışı, müşteri satışı ve portföy satışı gerçekleştirilecektir.',
    'FullTime',
    'OnSite',
    'ENTRY_LEVEL',
    '{"slug": "yektateknoloji-satis-ve-pazarlama-sorumlusu-temsilcisi-1000165", "title": "Kurumsal B2B Satış Danışmanı ve Portföy Satış Temsilcisi (Yazılım)", "_docId": "019f4838-dfa1-74d9-8618-ba5cb664c412", "branchId": "019f482b-801b-7f6e-bc64-b2e3f3b4ecda", "industry": "SALES", "location": {"latitude": 41.08420223832859, "longitude": 28.66673218169495, "__typename": "Location", "city": "Balıkesir"}, "accountId": "ff7a0b6c-40b2-4a6f-bd5d-942b7ebaa0e5", "companyId": "06333b09-8d51-43fa-8de6-e8ccda39fba9", "createdAt": "2026-07-09T18:51:54.658Z", "locations": [{"latitude": 41.08420223832859, "longitude": 28.66673218169495, "__typename": "Location"}], "maxSalary": 30000, "minSalary": 20000, "updatedAt": "2026-07-09T18:51:54.658Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<p>​İş Tanımı:<br>Yekta Teknoloji bünyesinde, geliştirdiğimiz yenilikçi yazılım çözümleri, SaaS platformları ve sektörel dijital sistemlerin (B2B) kurumsal satış ve pazarlama süreçlerini yönetecek, dinamik ve hedef odaklı Satış ve Pazarlama Sorumlusu arıyoruz.<br>​Ekibimize katılacak çalışma arkadaşımız; potansiyel müşteri portföyünü genişletmekten, aktif saha/online sunumlar gerçekleştirmekten ve satış kapama süreçlerinden sorumlu olacaktır.<br>​Genel Nitelikler:<br>​Tercihen yazılım, teknoloji, SaaS veya kurumsal hizmet (B2B) satışı konusunda deneyimli veya bu alanlara yoğun ilgisi olan,<br>​Teknolojik trendleri, dijital platformları ve sektörel yenilikleri hızlı kavrayabilen,<br>​İletişim becerileri, ikna kabiliyeti ve sunum yeteneği yüksek,<br>​\"Hayır\" cevabını bir engel değil, sürecin bir parçası olarak gören (Reddedilme direnci yüksek),<br>​Müşteri portföyü oluşturma, takip (follow-up) ve CRM yönetimi disiplinine sahip,<br>​(Varsa araç gereksinimi: Aktif araç kullanabilen ve seyahat engeli olmayan).<br>​Sorumluluklar:<br>​Potansiyel kurumsal müşterileri (acente, firma, fabrika vb.) tespit edip soğuk arama (cold call) ve ziyaretler yoluyla ilk teması kurmak,<br>​Geliştirdiğimiz çözümlerin ve platformların değer önerisini müşteriye net ve profesyonel bir dille aktarmak, sunumlar yapmak,<br>​Teklif süreçlerini yönetmek, satış hedeflerine ulaşmak için aktif stratejiler geliştirmek,<br>​Mevcut müşterilerle ilişkileri sürdürüp memnuniyet takibi yapmak.<br>​Ne Sunuyoruz?<br>​Sabit Maaş + Performansa Dayalı Tatminkar Prim Sistemi<br>​Yenilikçi, dinamik ve gelişime açık bir çalışma ortamı<br>​Yol + Yemek + Gerekli Teknik Donanım</p>", "publishedAt": "2026-07-10T14:14:38.848Z", "currencyCode": "TRY", "positionLevel": "ENTRY_LEVEL", "isConfidential": false, "advertisementId": "019f4838-df9c-7038-9e66-db571848db4b", "isMostPreferred": false, "statusUpdatedAt": "2026-07-10T14:14:38.848Z", "companyShortName": "YEKTA_TEKNOLOJI", "locationSourceType": "Branch", "advertisementNumber": "1000165", "advertisementStatus": "Approved", "advertisementJobType": "FullTime", "advertisementModeOfOperation": "OnSite", "advertisementRecruitmentProcess": {"id": "019f4834-d586-71e6-ae53-a30b0b52a56b", "data": {"nodes": [{"id": "node-placeholder-1783622848695", "data": {"label": "Satış elemanı", "description": "İkna kabiliyeti yüksek\nDiksiyonu düzgün", "_isPlaceholder": true}, "type": "processStep", "position": {"x": 0, "y": 0}}]}, "name": "Satış elemanı", "version": 1, "isActive": true, "isSystem": false, "accountId": "ff7a0b6c-40b2-4a6f-bd5d-942b7ebaa0e5", "createdAt": "2026-07-09T18:47:29.920Z", "isDefault": false, "updatedAt": "2026-07-09T18:47:29.920Z", "__typename": "AdvertisementRecruitmentProcess", "description": "İkna kabiliyeti yüksek\nDiksiyonu düzgün"}, "advertisementRecruitmentProcessId": "019f4834-d586-71e6-ae53-a30b0b52a56b", "advertisementRecruitmentProcessVersionId": "019f4834-d588-7489-b752-7a7171e1e34f", "AdvertisementRecruitmentProcessVersionNodeTranslation": [{"id": "019f4834-d58a-7422-aceb-665a1d58b40c", "label": "Satış elemanı", "nodeId": "node-placeholder-1783622848695", "createdAt": "2026-07-09T18:47:29.925Z", "updatedAt": "2026-07-09T18:47:29.925Z", "__typename": "GetAdvertisementRecruitmentProcessVersionNodeTranslationResponseDto", "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "description": "İkna kabiliyeti yüksek\nDiksiyonu düzgün", "advertisementRecruitmentProcessVersionId": "019f4834-d588-7489-b752-7a7171e1e34f"}, {"id": "019f4834-d58a-76a9-9a46-053a42d8a050", "label": "sales staff", "nodeId": "node-placeholder-1783622848695", "createdAt": "2026-07-09T18:47:29.925Z", "updatedAt": "2026-07-09T18:47:29.925Z", "__typename": "GetAdvertisementRecruitmentProcessVersionNodeTranslationResponseDto", "languageId": "019d61b4-cffe-7552-b5ac-ee38dcf97438", "description": "persuasion ability\nhis diction is smooth", "advertisementRecruitmentProcessVersionId": "019f4834-d588-7489-b752-7a7171e1e34f"}], "category": "SALES", "jobType": "FullTime", "modeOfOperation": "OnSite"}'::jsonb,
