INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f4bcb-d9d4-7651-a563-bc072e00e80a',
    'tbemmakinaveotomo-plastik-enjeksiyon-operatoru-1000166',
    'Plastik Enjeksiyon ve İmalat Elemanı',
    'TBEM_MAKINA',
    'Tecrübeli veya tecrübesiz (Mesleki yeterlilik veya ustalık şartı aranmamaktadır, işi öğrenmeye istekli olması yeterlidir), Gece ve gündüz dönüşümlü vardiya sistemine uyum sağlayabilecek, Fiziksel olarak vardiyalı çalışma temposuna ayak uydurabilecek çalışma arkadaşları arıyoruz. Çalışma Saatleri ve Düzeni: Normal Çalışma Düzeni: Hafta içi 5 gün, 08:00 - 18:00 saatleri arası. Vardiyalı Çalışma Düzeni: 08:00 - 20:00 (Gündüz) ve 20:00 - 08:00 (Gece) şeklinde dönüşümlü. Vardiyalı sistemde günlük mesai 12 saattir. Bu 12 saatlik dilimin 2 saati fazla mesai olarak kabul edilmektedir. Ücretlendirme ve Haklar: Başlangıç maaşı Asgari Ücret olarak belirlenmiştir. 12 saatlik vardiyalarda çalışılan +2 saatlik süreler maaşa mesai ücreti olarak ilave edilecektir.',
    'FullTime',
    'OnSite',
    'UNSPECIFIED',
    '{"slug": "tbemmakinaveotomo-plastik-enjeksiyon-operatoru-1000166", "title": "Plastik Enjeksiyon ve İmalat Elemanı", "_docId": "019f4bcb-d9d9-7537-9d65-9ca24f1ccea6", "branchId": "b46e1ae9-deea-49db-ae2a-148f09929620", "category": "INDUSTRIAL_MANUFACTURING", "industry": "INDUSTRIAL_MANUFACTURING", "location": {"latitude": 0, "longitude": 0, "__typename": "Location", "city": "Ankara"}, "accountId": "67ff91dd-a0fc-4cb2-a9e9-53789cbf06ca", "companyId": "3d106b30-95ca-46d4-bbb2-d9c54e141a25", "createdAt": "2026-07-10T11:31:18.613Z", "locations": [{"latitude": 0, "longitude": 0, "__typename": "Location"}], "maxSalary": 30000, "minSalary": 28000, "updatedAt": "2026-07-10T11:31:18.613Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<p><strong>Genel Nitelikler:</strong></p><ul><li><p>Plastik enjeksiyon üretim hattımızda görevlendirilmek üzere,</p></li><li><p>Tecrübeli veya tecrübesiz (Mesleki yeterlilik veya ustalık şartı aranmamaktadır, işi öğrenmeye istekli olması yeterlidir),</p></li><li><p>Gece ve gündüz dönüşümlü vardiya sistemine uyum sağlayabilecek,</p></li><li><p>Fiziksel olarak vardiyalı çalışma temposuna ayak uydurabilecek çalışma arkadaşları arıyoruz.</p></li></ul><p><strong>Çalışma Saatleri ve Düzeni:</strong></p><ul><li><p>Normal Çalışma Düzeni: Hafta içi 5 gün, 08:00 - 18:00 saatleri arası.</p></li><li><p>Vardiyalı Çalışma Düzeni: 08:00 - 20:00 (Gündüz) ve 20:00 - 08:00 (Gece) şeklinde dönüşümlü.</p></li><li><p>Vardiyalı sistemde günlük mesai 12 saattir. Bu 12 saatlik dilimin 2 saati fazla mesai olarak kabul edilmektedir.</p></li></ul><p><strong>Ücretlendirme ve Haklar:</strong></p><ul><li><p>Başlangıç maaşı Asgari Ücret olarak belirlenmiştir.</p></li><li><p>12 saatlik vardiyalarda çalışılan +2 saatlik süreler maaşa mesai ücreti olarak ilave edilecektir.</p></li></ul><p></p>", "publishedAt": "2026-07-10T13:55:18.916Z", "currencyCode": "TRY", "positionLevel": "UNSPECIFIED", "isConfidential": false, "advertisementId": "019f4bcb-d9d4-7651-a563-bc072e00e80a", "isMostPreferred": false, "statusUpdatedAt": "2026-07-10T13:55:18.916Z", "companyShortName": "TBEM_MAKINA", "locationSourceType": "Branch", "advertisementNumber": "1000166", "advertisementStatus": "Approved", "advertisementJobType": "FullTime", "advertisementModeOfOperation": "OnSite", "advertisementRecruitmentProcess": {"id": "019f4bc8-7bfb-7500-9a37-b558289af3e3", "data": {"nodes": [{"id": "node-placeholder-1783682857999", "data": {"label": "Plastik Enjeksiyon Üretim Elemanı", "_isPlaceholder": true}, "type": "processStep", "position": {"x": 0, "y": 0}}]}, "name": "Plastik Enjeksiyon Üretim Elemanı", "version": 1, "isActive": true, "isSystem": false, "accountId": "67ff91dd-a0fc-4cb2-a9e9-53789cbf06ca", "createdAt": "2026-07-10T11:27:37.975Z", "isDefault": false, "updatedAt": "2026-07-10T11:27:37.975Z", "__typename": "AdvertisementRecruitmentProcess"}, "advertisementRecruitmentProcessId": "019f4bc8-7bfb-7500-9a37-b558289af3e3", "advertisementRecruitmentProcessVersionId": "019f4bc8-7bfd-7754-934c-2ed554f22480", "AdvertisementRecruitmentProcessVersionNodeTranslation": [{"id": "019f4bc8-7bff-7c1f-b325-d6a2c35bb272", "label": "Plastik Enjeksiyon Üretim Elemanı", "nodeId": "node-placeholder-1783682857999", "createdAt": "2026-07-10T11:27:37.980Z", "updatedAt": "2026-07-10T11:27:37.980Z", "__typename": "GetAdvertisementRecruitmentProcessVersionNodeTranslationResponseDto", "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "advertisementRecruitmentProcessVersionId": "019f4bc8-7bfd-7754-934c-2ed554f22480"}, {"id": "019f4bc8-7bff-7ea4-a585-7c2422baf552", "label": "Plastik Enjeksiyon Operatörü", "nodeId": "node-placeholder-1783682857999", "createdAt": "2026-07-10T11:27:37.980Z", "updatedAt": "2026-07-10T11:27:37.980Z", "__typename": "GetAdvertisementRecruitmentProcessVersionNodeTranslationResponseDto", "languageId": "019d61b4-cffe-7552-b5ac-ee3