INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f6b52-da51-7b76-aff5-69ca8e0e5ea8',
    'joyglobalgayrimenk-joy-global-gayrimenkul-danismanlik-ekibini-buyutuyor-1000174',
    'JOY GLOBAL GAYRİMENKUL DANIŞMANLIK EKİBİNİ BÜYÜTÜYOR!',
    'JOY_GLOBAL_GAYRIMENK',
    'JOY GLOBAL GAYRİMENKUL DANIŞMANLIK EKİBİNİ BÜYÜTÜYOR! [şehir] / Meydankavağı''nda bulunan ofisimize gayrimenkul danışmanları arıyoruz. Tecrübeli veya tecrübesiz olmanız fark etmez. Gayrimenkul sektöründe kariyer yapmak isteyen, gelişime açık ve kazancını kendi belirlemek isteyen adayları ekibimize bekliyoruz. Size Neler Sunuyoruz? ✅ Başlangıçta %75 yüksek komisyon oranı ✅ Çalışma modeline uygun adaylar için özel %100 komisyon sistemi ✅ Prim esaslı yüksek kazanç modeli ✅ Eğitim ve saha desteği ✅ Profesyonel ve kurumsal çalışma ortamı ✅ Kendi işinizin patronu gibi çalışma imkânı Referans Kazanç Programı Ekibimizi birlikte büyütüyoruz! Ofisimize kazandırdığınız her yeni gayrimenkul danışmanı için ek kazanç elde edebilirsiniz. Referansınızla ekibimize katılan her danışman için belirlenen şartlar doğrultusunda size ek prim veya referans ödülü verilmektedir. Böylece yalnızca kendi satışlarınızdan değil, ekibimizin büyümesine sağladığınız katkıdan da ek gelir elde edebilirsiniz. Kimleri Arıyoruz? İletişimi güçlü, Dürüst ve güvenilir, Hedef odaklı, Öğrenmeye istekli, Tercihen B sınıfı ehliyeti olan ve aktif araç kullanabilen (tercih sebebidir). Gelirinizi sınırlandıran maaş sistemi yerine, emeğinizin karşılığını alabileceğiniz profesyonel bir kariyer fırsatı arıyorsanız sizi JOY GLOBAL GAYRİMENKUL DANIŞMANLIK ailesine bekliyoruz. Kazancınızı siz belirleyin, geleceğinizi birlikte inşa edelim!',
    'FullTime',
    'Hybrid',
    'UNSPECIFIED',
    '{"slug": "joyglobalgayrimenk-joy-global-gayrimenkul-danismanlik-ekibini-buyutuyor-1000174", "title": "JOY GLOBAL GAYRİMENKUL DANIŞMANLIK EKİBİNİ BÜYÜTÜYOR!", "_docId": "019f6b52-da56-7527-a588-04b1fcbf2b57", "branchId": "29f64426-d01b-4a36-8055-1e1330787d79", "industry": "SALES", "location": {"latitude": 0, "longitude": 0, "__typename": "Location", "city": "Antalya"}, "accountId": "2eb1ca7b-131f-4f11-988a-b7a5fd2d04c1", "companyId": "c69e2937-f0c7-41e3-9749-a0cf6fd14d7d", "createdAt": "2026-07-16T14:26:59.796Z", "locations": [{"latitude": 0, "longitude": 0, "__typename": "Location"}], "maxSalary": 111111, "minSalary": 1, "updatedAt": "2026-07-16T14:26:59.796Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Commission", "sortWeight": 0, "description": "<p>JOY GLOBAL GAYRİMENKUL DANIŞMANLIK EKİBİNİ BÜYÜTÜYOR!</p><p>[şehir] / Meydankavağı''nda bulunan ofisimize gayrimenkul danışmanları arıyoruz.</p><p>Tecrübeli veya tecrübesiz olmanız fark etmez. Gayrimenkul sektöründe kariyer yapmak isteyen, gelişime açık ve kazancını kendi belirlemek isteyen adayları ekibimize bekliyoruz.</p><p>Size Neler Sunuyoruz?</p><p>✅ Başlangıçta %75 yüksek komisyon oranı</p><p>✅ Çalışma modeline uygun adaylar için özel %100 komisyon sistemi</p><p>✅ Prim esaslı yüksek kazanç modeli</p><p>✅ Eğitim ve saha desteği</p><p>✅ Profesyonel ve kurumsal çalışma ortamı</p><p>✅ Kendi işinizin patronu gibi çalışma imkânı</p><p>Referans Kazanç Programı</p><p>Ekibimizi birlikte büyütüyoruz!</p><p>Ofisimize kazandırdığınız her yeni gayrimenkul danışmanı için ek kazanç elde edebilirsiniz. Referansınızla ekibimize katılan her danışman için belirlenen şartlar doğrultusunda size ek prim veya referans ödülü verilmektedir. Böylece yalnızca kendi satışlarınızdan değil, ekibimizin büyümesine sağladığınız katkıdan da ek gelir elde edebilirsiniz.</p><p>Kimleri Arıyoruz?</p><p>İletişimi güçlü,</p><p>Dürüst ve güvenilir,</p><p>Hedef odaklı,</p><p>Öğrenmeye istekli,</p><p>Tercihen B sınıfı ehliyeti olan ve aktif araç kullanabilen (tercih sebebidir).</p><p>Gelirinizi sınırlandıran maaş sistemi yerine, emeğinizin karşılığını alabileceğiniz profesyonel bir kariyer fırsatı arıyorsanız sizi JOY GLOBAL GAYRİMENKUL DANIŞMANLIK ailesine bekliyoruz.</p><p>Kazancınızı siz belirleyin, geleceğinizi birlikte inşa edelim!</p><p></p><p></p>", "publishedAt": "2026-07-17T12:11:39.205Z", "currencyCode": "TRY", "positionLevel": "UNSPECIFIED", "isConfidential": false, "advertisementId": "019f6b52-da51-7b76-aff5-69ca8e0e5ea8", "isMostPreferred": false, "statusUpdatedAt": "2026-07-17T12:11:39.205Z", "companyShortName": "JOY_GLOBAL_GAYRIMENK", "locationSourceType": "Branch", "advertisementNumber": "1000174", "advertisementStatus": "Approved", "advertisementJobType": "FullTime", "advertisementModeOfOperation": "Hybrid", "advertisementRecruitmentProcess": {"id": "019f6b51-5ca5-7eec-81bc-7f5c882e6b42", "data": {"nodes": [{"id": "node-placeholder-1784211883343", "data": {"label": "Gayrimenkul Danışmanı", "description": "Kimleri Arıyoruz?\nİletişimi güçlü,\nDürüst ve güvenilir,\nHedef odaklı,\nÖğrenmeye istekli,\nTercihen B sınıfı ehliyeti olan ve aktif araç kullanabilen (tercih sebebidir).\nGelirinizi sınırlandıran maaş sistemi yerine, emeğinizin karşılığını alabileceğiniz profesyonel bir kariyer fırsatı arıyorsanız sizi JOY GLOBAL GAYRİMENKUL DANIŞMANLIK ailesine bekliyoruz.", "_isPlaceholder": true}, "type": "processStep", "position": {"x": 0, "y": 0}}]}, "name": "Gayrimenkul Danışmanı", "version": 1, "isActive": true, "isSystem": false, "accountId": "2eb1ca7b-131f-4f11-988a-b7a5fd2d04c1", "createdAt": "2026-07-16T14:25:22.082Z", "isDefault": false, "updatedAt": "2026-07-16T14:25:22.082Z", "__typename": "AdvertisementRecruitmentProcess", "description": "Kimleri Arıyoruz?\nİletişimi güçlü,\nDürüst ve güvenilir,\nHedef odaklı,\nÖğrenmeye istekli,\nTercihen B sınıfı ehliyeti olan ve aktif araç kullanabilen (tercih sebebidir).\nGelirinizi sınırlandıran maaş sistemi yerine, emeğinizin karşılığını alabileceğiniz profesyonel bir kariyer fırsatı arıyorsanız sizi JOY GLOBAL GAYRİMENKUL DANIŞMANLIK ailesine bekliyoruz."}, "advertisementRecruitmentProcessId": "019f6b51-5ca5-7eec-81bc-7f5c882e6b42", "advertisementRecruitmentProcessVersionId": "019f6b51-5ca8-7158-b2bb-2b119352c63a", "AdvertisementRecruitmentProcessVersionNodeTranslation": [{"id": "019f6b51-5caa-720c-a88f-c270c07f35b4", "label": "Gayrimenkul Danışmanı", "nodeId": "node-placeholder-1784211883343", "createdAt": "2026-07-16T14:25:22.087Z", "updatedAt": "2026-07-16T14:25:22.087Z", "__typename": "GetAdvertisementRecruitmentProcessVersionNodeTranslationResponseDto", "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "description": "Kimleri Arıyoruz?\nİletişimi güçlü,\nDürüst ve güvenilir,\nHedef odaklı,\nÖğrenmeye istekli,\nTercihen B sınıfı ehliyeti olan ve aktif araç kullanabilen (tercih sebebidir).\nGelirinizi sınırlandıran maaş sistemi yerine, emeğinizin karşılığını alabileceğiniz profesyonel bir kariyer fırsatı arıyorsanız sizi JOY GLOBAL GAYRİMENKUL DANIŞMANLIK ailesine bekliyoruz.", "advertisementRecruitmentProcessVersionId": "019f6b51-5ca8-7158-b2bb-2b119352c63a"}, {"id": "019f6b51-5caa-74e5-8437-860ae5a12bc6", "label": "Gayrimenkul Danışmanı", "nodeId": "node-placeholder-1784211883343", "createdAt": "2026-07-16T14:25:22.087Z", "updatedAt": "2026-07-16T14:25:22.087Z", "__typename": "GetAdvertisementRecruitmentProcessVersionNodeTranslationResponseDto", "languageId": "019d61b4-cffe-7552-b5ac-ee38dcf97438", "description": "Kimleri Arıyoruz?\nİletişimi güçlü,\nDürüst ve güvenilir,\nHedef odaklı,\nÖğrenmeye istekli,\nTercihen B sınıfı ehliyeti olan ve aktif araç kullanabilen (tercih sebebidir).\nGelirinizi sınırlandıran maaş sistemi yerine, emeğinizin karşılığını alabileceğiniz profesyonel bir kariyer fırsatı arıyorsanız sizi JOY GLOBAL GAYRİMENKUL DANIŞMANLIK ailesine bekliyoruz.", "advertisementRecruitmentProcessVersionId":