INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f7487-43a7-7860-ae86-2896fc0edede',
    'eguzellik-prestijli-salonda-tam-donanimli-uygulama-odasi-kullanim-hakki-1000177',
    'Prestijli Salonda Tam Donanımlı Uygulama Odası / Kullanım Hakkı',
    'EGUZELLIK',
    'Kendi Portföyü Olan Uzmanlar İçin Hazır Kurulu Düzen Fırsatı! Yüksek yatırım maliyetlerine girmeden, [şehir] en lüks lokasyonunda, tüm teknik altyapısı hazır bir salonda hizmet vermek ister misiniz? Luxury Beauty Center bünyesinde, sadece randevularınıza odaklanacağınız profesyonel bir çalışma ortamı sizi bekliyor. Sistem Avantajları: Hazır Cihaz Parkuru: Lazer epilasyondan cilt bakım ünitelerine, bölgesel incelme cihazlarından medikal estetik ekipmanlarına kadar her şey kullanımınıza hazır. Sıfır Sabit Gider: Kira, depozito,cihaz maaliyetleri, dekorasyon, sarf malzeme, stopaj, elektrik, su, internet veya aidat gibi işletme giderleri ile uğraşmazsınız. Lüks Resepsiyon Hizmeti: Müşterileriniz profesyonel bir ekiple karşılanır ve ağırlanır. Esnek Çalışma Modeli: Sabit bir işletme kurma riski almadan, mevcut portföyünüzü lüks bir atmosferde ağırlama imkanı. Hizmet Bedeli ve Detaylar: İşletmemizde sunulan oda ve cihaz kullanım hizmetleri, verilen hizmet üzerinden hakediş usulü ile faturalandırılmaktadır. Tüm operasyonel süreçler (ikram, temizlik, sterilizasyon) tarafımızca yönetilmektedir. Aranan Nitelikler: ✅ Kendi müşteri portföyüne sahip, ✅ Hijyen ve kalite standartlarına önem veren, ✅ Profesyonel etik kurallara sahip uzmanlar. Milyonluk yatırım yapmanıza gerek yok; anahtar teslim lüks salonunuz burada hazır! Yer: 19 Mayıs Mahallesi, Atatürk Caddesi, Yamaç Sokak, Şeref Yazgan İş Merkezi, No: 1, Kat: 2, Daire: 8, [şehir] (Şok Market Yanı/ Eski Ptt Üstü) "Sadece belirli sayıda Güzellik Uzmanı ile kontenjanımız sınırlıdır."',
    'Freelance',
    'OnSite',
    'SPECIALIST',
    '{"slug": "eguzellik-prestijli-salonda-tam-donanimli-uygulama-odasi-kullanim-hakki-1000177", "title": "Prestijli Salonda Tam Donanımlı Uygulama Odası / Kullanım Hakkı", "_docId": "019f7487-43ac-7138-a792-56b471a36739", "branchId": "4e9ca5e7-1f48-4e60-9cfb-9a10dce62a48", "category": "BEAUTY_CARE", "industry": "BEAUTY_CARE", "location": {"latitude": 0, "longitude": 0, "__typename": "Location", "city": "İstanbul"}, "accountId": "15521bd8-ad1d-4811-8c05-7730909e5ce2", "companyId": "1c7dd636-f67c-4edf-b838-39f7a46da633", "createdAt": "2026-07-18T09:20:49.580Z", "locations": [{"latitude": 0, "longitude": 0, "__typename": "Location"}], "maxSalary": 50000, "minSalary": 30000, "updatedAt": "2026-07-18T09:20:49.580Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Daily", "sortWeight": 0, "description": "<h2><strong>Kendi Portföyü Olan Uzmanlar İçin Hazır Kurulu Düzen Fırsatı!</strong></h2><p>Yüksek yatırım maliyetlerine girmeden, [şehir] en lüks lokasyonunda, tüm teknik altyapısı hazır bir salonda hizmet vermek ister misiniz?&nbsp;</p><p><strong>Luxury Beauty Center</strong> bünyesinde, sadece randevularınıza odaklanacağınız profesyonel bir çalışma ortamı sizi bekliyor.</p><p><strong>Sistem Avantajları:</strong></p><ul><li><p><strong>Hazır Cihaz Parkuru:</strong> Lazer epilasyondan cilt bakım ünitelerine, bölgesel incelme cihazlarından medikal estetik ekipmanlarına kadar her şey kullanımınıza hazır.</p></li><li><p><strong>Sıfır Sabit Gider:</strong> Kira, depozito,cihaz maaliyetleri, dekorasyon, sarf malzeme, stopaj, elektrik, su, internet veya aidat gibi işletme giderleri ile uğraşmazsınız.</p></li><li><p><strong>Lüks Resepsiyon Hizmeti:</strong> Müşterileriniz profesyonel bir ekiple karşılanır ve ağırlanır.</p></li><li><p><strong>Esnek Çalışma Modeli:</strong> Sabit bir işletme kurma riski almadan, mevcut portföyünüzü lüks bir atmosferde ağırlama imkanı.</p></li></ul><p><strong>Hizmet Bedeli ve Detaylar:</strong><br>İşletmemizde sunulan oda ve cihaz kullanım hizmetleri, <strong>verilen hizmet üzerinden hakediş usulü</strong> ile faturalandırılmaktadır. Tüm operasyonel süreçler (ikram, temizlik, sterilizasyon) tarafımızca yönetilmektedir.</p><p><strong>Aranan Nitelikler:</strong><br>✅ Kendi müşteri portföyüne sahip,<br>✅ Hijyen ve kalite standartlarına önem veren,<br>✅ Profesyonel etik kurallara sahip uzmanlar.</p><p>Milyonluk yatırım yapmanıza gerek yok; anahtar teslim lüks salonunuz burada hazır!</p><p><strong>Yer:</strong>&nbsp;19 Mayıs Mahallesi, Atatürk Caddesi, Yamaç Sokak, Şeref Yazgan İş Merkezi, No: 1, Kat: 2, Daire: 8, [şehir] (Şok Market Yanı/ Eski Ptt Üstü)&nbsp;</p><h3><em>\"Sadece belirli sayıda Güzellik Uzmanı ile kontenjanımız sınırlıdır.\"</em></h3><p></p>", "publishedAt": "2026-07-20T11:08:16.284Z", "currencyCode": "TRY", "positionLevel": "SPECIALIST", "isConfidential": false, "advertisementId": "019f7487-43a7-7860-ae86-2896fc0edede", "isMostPreferred": false, "statusUpdatedAt": "2026-07-20T11:08:16.284Z", "companyShortName": "EGUZELLIK", "locationSourceType": "Branch", "advertisementNumber": "1000177", "advertisementStatus": "Approved", "advertisementJobType": "Freelance", "advertisementModeOfOperation": "OnSite", "advertisementRecruitmentProcess": {"id": "019f5be9-140c-714a-81e2-cd67026312a0", "data": {"nodes": [{"id": "node-placeholder-1783953428733", "data": {"label": "Luxury baeuty güzellik merkezi eleman alımı", "description": "güzellik uzmanı", "_isPlaceholder": true}, "type": "processStep", "position": {"x": 0, "y": 0}}]}, "name": "Luxury baeuty güzellik merkezi eleman alımı", "version": 1, "isActive": true, "isSystem": false, "accountId": "15521bd8-ad1d-4811-8c05-7730909e5ce2", "createdAt": "2026-07-13T14:37:09.510Z", "isDefault": false, "updatedAt": "2026-07-13T14:37:09.510Z", "__typename": "AdvertisementRecruitmentProcess", "description": "güzellik uzmanı"}, "advertisementRecruitmentProcessId": "019f5be9-140c-714a-81e