INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f7489-1d01-76d9-adfc-1610b6579a88',
    'eguzellik-luxury-beauty-centera-deneyimli-guzellik-uzmani-araniyor-1000178',
    'Luxury Beauty Centera Deneyimli Güzellik Uzmanı Aranıyor...',
    'EGUZELLIK',
    '[şehir] prestijli lokasyonlarından birinde faaliyet gösteren, müşteri memnuniyeti odaklı ve yenilikçi uygulamalarıyla öne çıkan Luxury Beauty Center merkezimiz için güler yüzlü, enerjik ve alanında deneyimli Güzellik Uzmanları (Estetisyenler) arıyoruz. Ekibimizin bir parçası olarak, danışanlarımıza en yüksek kalitede hizmet sunacak çalışma arkadaşları ile tanışmak için sabırsızlanıyoruz. Genel Nitelikler Milli Eğitim Bakanlığı (MEB) onaylı Estetisyenlik/Güzellik Uzmanlığı diplomasına veya ustalık belgesine sahip, Cilt bakımı uygulamaları, bölgesel incelme, lazer epilasyon ve modern estetik cihazları konusunda deneyimli, Sektördeki yeni trendleri, ürün içeriklerini ve teknolojileri yakından takip eden, Diksiyonu düzgün, dış görünümüne özen gösteren ve iletişim becerileri yüksek, Danışan memnuniyeti ve kurumsal temsil bilincine sahip, Satış kabiliyeti olan, danışanlara ihtiyaçları doğrultusunda doğru ürün ve kür yönlendirmesi yapabilecek. İş Tanımı Merkezimize gelen danışanların cilt analizi ve ihtiyaç tespitini yapmak, Cilt bakımı, epilasyon ve vücut şekillendirme gibi protokolleri profesyonelce uygulamak, Uygulama odalarının hijyen, düzen ve sterilliğini korumak, Danışanların seans takibini düzenli ve güler yüzlü bir şekilde gerçekleştirmek.',
    'FullTime',
    'OnSite',
    'NEW_GRADUATE',
    '{"slug": "eguzellik-luxury-beauty-centera-deneyimli-guzellik-uzmani-araniyor-1000178", "title": "Luxury Beauty Centera Deneyimli Güzellik Uzmanı Aranıyor...", "_docId": "019f7489-1d06-7054-b616-12cd31cb159b", "branchId": "4e9ca5e7-1f48-4e60-9cfb-9a10dce62a48", "industry": "BEAUTY_CARE", "location": {"latitude": 0, "longitude": 0, "__typename": "Location", "city": "İstanbul"}, "accountId": "15521bd8-ad1d-4811-8c05-7730909e5ce2", "companyId": "1c7dd636-f67c-4edf-b838-39f7a46da633", "createdAt": "2026-07-18T09:22:50.763Z", "locations": [{"latitude": 0, "longitude": 0, "__typename": "Location"}], "maxSalary": 40000, "minSalary": 30000, "updatedAt": "2026-07-18T09:22:50.763Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<p>[şehir] prestijli lokasyonlarından birinde faaliyet gösteren, müşteri memnuniyeti odaklı ve yenilikçi uygulamalarıyla öne çıkan <strong>Luxury Beauty Center</strong> merkezimiz için güler yüzlü, enerjik ve alanında deneyimli <strong>Güzellik Uzmanları (Estetisyenler)</strong> arıyoruz.</p><p>Ekibimizin bir parçası olarak, danışanlarımıza en yüksek kalitede hizmet sunacak çalışma arkadaşları ile tanışmak için sabırsızlanıyoruz.</p><h3>Genel Nitelikler</h3><ul><li><p>Milli Eğitim Bakanlığı (MEB) onaylı Estetisyenlik/Güzellik Uzmanlığı diplomasına veya ustalık belgesine sahip,</p></li><li><p>Cilt bakımı uygulamaları, bölgesel incelme, lazer epilasyon ve modern estetik cihazları konusunda deneyimli,</p></li><li><p>Sektördeki yeni trendleri, ürün içeriklerini ve teknolojileri yakından takip eden,</p></li><li><p>Diksiyonu düzgün, dış görünümüne özen gösteren ve iletişim becerileri yüksek,</p></li><li><p>Danışan memnuniyeti ve kurumsal temsil bilincine sahip,</p></li><li><p>Satış kabiliyeti olan, danışanlara ihtiyaçları doğrultusunda doğru ürün ve kür yönlendirmesi yapabilecek.</p></li></ul><h3>İş Tanımı</h3><ul><li><p>Merkezimize gelen danışanların cilt analizi ve ihtiyaç tespitini yapmak,</p></li><li><p>Cilt bakımı, epilasyon ve vücut şekillendirme gibi protokolleri profesyonelce uygulamak,</p></li><li><p>Uygulama odalarının hijyen, düzen ve sterilliğini korumak,</p></li><li><p>Danışanların seans takibini düzenli ve güler yüzlü bir şekilde gerçekleştirmek.</p></li></ul><p><br></p>", "publishedAt": "2026-07-20T11:08:34.988Z", "currencyCode": "TRY", "positionLevel": "NEW_GRADUATE", "isConfidential": false, "advertisementId": "019f7489-1d01-76d9-adfc-1610b6579a88", "isMostPreferred": false, "statusUpdatedAt": "2026-07-20T11:08:34.988Z", "companyShortName": "EGUZELLIK", "locationSourceType": "Branch", "advertisementNumber": "1000178", "advertisementStatus": "Approved", "advertisementJobType": "FullTime", "advertisementModeOfOperation": "OnSite", "advertisementRecruitmentProcess": {"id": "019f5be9-140c-714a-81e2-cd67026312a0", "data": {"nodes": [{"id": "node-placeholder-1783953428733", "data": {"label": "Luxury baeuty güzellik merkezi eleman alımı", "description": "güzellik uzmanı", "_isPlaceholder": true}, "type": "processStep", "position": {"x": 0, "y": 0}}]}, "name": "Luxury baeuty güzellik merkezi eleman alımı", "version": 1, "isActive": true, "isSystem": false, "accountId": "15521bd8-ad1d-4811-8c05-7730909e5ce2", "createdAt": "2026-07-13T14:37:09.510Z", "isDefault": false, "updatedAt": "2026-07-13T14:37:09.510Z", "__typename": "AdvertisementRecruitmentProcess", "description": "güzellik uzmanı"}, "advertisementRecruitmentProcessId": "019f5be9-140c-714a-81e2-cd67026312a0", "advertisementRecruitmentProcessVersionId": "019f5be9-140e-730c-8911-b62fbdcb73b6", "AdvertisementRecruitmentProcessVersionNodeTranslation": [{"id": "019f5be9-1411-73d0-a578-aea333fa89fc", "label": "Luxury baeuty güzellik merkezi eleman alımı", "nodeId": "node-placeholder-1783953428733", "createdAt": "2026-07-13T14:37:09.517Z", "updatedAt": "2026-07-13T14:37:09.517Z", "__typename": "GetAdvertisementRecruitmentProcess