INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f748b-541a-7d71-96b0-4c04ab78a7bf',
    'eguzellik-acill-saha-satis-ve-tanitim-elemani-araniyor-1000179',
    'Acill saha satış ve tanıtım elemanı aranıyor.',
    'EGUZELLIK',
    'Luxury Beauty Center, [şehir] en prestijli lokasyonlarından birinde, yüksek müşteri memnuniyeti odaklı ve son teknoloji cihazlarla hizmet veren lüks bir güzellik merkezidir. Merkezimizin yerel pazardaki bilinirliğini ve kurumsal iş birliklerini artırmak üzere, sahada aktif rol alacak Saha Satış Elemanı aramaktayız. · Merkezimizin çevresinde yer alan plazalar, konut siteleri, bankalar, cafeler, restoranlar, marketler ve pastaneler ile birebir temas kurmak, bu işletmelerle ortak kampanyalar, "VIP Davetiye" dağıtım anlaşmaları ve kurumsal indirim organize ederek merkeze yeni müşteri trafiği yönlendirmek, İkna kabiliyeti güçlü, beşerî ilişkileri mükemmel ve diksiyonu düzgün, · Dinamik, enerjik ve sahada çalışmaktan keyif alan, · Dış görünümüne ve kişisel bakımına özen gösteren (Prezantabl), · [şehir] bölgesine ve çevre lokasyonlara hâkim. Haklar ve Sosyal İmkanlar: · Asgari Ücret + Performansa Dayalı (Yönlendirilen müşteri üzerinden) Tatminkâr Prim Sistemi,',
    'Freelance',
    'Remote',
    'ENTRY_LEVEL',
    '{"slug": "eguzellik-acill-saha-satis-ve-tanitim-elemani-araniyor-1000179", "title": "Acill saha satış ve tanıtım elemanı aranıyor.", "_docId": "019f748b-541e-714a-9f50-23e6395db47a", "branchId": "4e9ca5e7-1f48-4e60-9cfb-9a10dce62a48", "industry": "SALES", "location": {"latitude": 0, "longitude": 0, "__typename": "Location", "city": "İstanbul"}, "accountId": "15521bd8-ad1d-4811-8c05-7730909e5ce2", "companyId": "1c7dd636-f67c-4edf-b838-39f7a46da633", "createdAt": "2026-07-18T09:25:15.940Z", "locations": [{"latitude": 0, "longitude": 0, "__typename": "Location"}], "maxSalary": 60000, "minSalary": 30000, "updatedAt": "2026-07-18T09:25:15.940Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Commission", "sortWeight": 0, "description": "<p>Luxury Beauty Center, [şehir] en prestijli lokasyonlarından birinde, yüksek müşteri memnuniyeti odaklı ve son teknoloji cihazlarla hizmet veren lüks bir güzellik merkezidir. Merkezimizin yerel pazardaki bilinirliğini ve kurumsal iş birliklerini artırmak üzere, sahada aktif rol alacak <strong>Saha Satış Elemanı </strong>aramaktayız.</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Merkezimizin çevresinde yer alan plazalar, konut siteleri, bankalar, cafeler, restoranlar, marketler ve pastaneler ile birebir temas kurmak, bu işletmelerle ortak kampanyalar, \"VIP Davetiye\" dağıtım anlaşmaları ve kurumsal indirim organize ederek merkeze yeni müşteri trafiği yönlendirmek, İkna kabiliyeti güçlü, beşerî ilişkileri mükemmel ve diksiyonu düzgün,</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Dinamik, enerjik ve sahada çalışmaktan keyif alan,</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Dış görünümüne ve kişisel bakımına özen gösteren (Prezantabl),</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; [şehir] bölgesine ve çevre lokasyonlara hâkim.</p><p><strong>Haklar ve Sosyal İmkanlar:</strong></p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Asgari Ücret + Performansa Dayalı (Yönlendirilen müşteri üzerinden) Tatminkâr Prim Sistemi,</p>", "publishedAt": "2026-07-20T11:07:46.412Z", "currencyCode": "TRY", "positionLevel": "ENTRY_LEVEL", "isConfidential": false, "advertisementId": "019f748b-541a-7d71-96b0-4c04ab78a7bf", "isMostPreferred": false, "statusUpdatedAt": "2026-07-20T11:07:46.412Z", "companyShortName": "EGUZELLIK", "locationSourceType": "Branch", "advertisementNumber": "1000179", "advertisementStatus": "Approved", "advertisementJobType": "Freelance", "advertisementModeOfOperation": "Remote", "advertisementRecruitmentProcess": {"id": "019f5be9-140c-714a-81e2-cd67026312a0", "data": {"nodes": [{"id": "node-placeholder-1783953428733", "data": {"label": "Luxury baeuty güzellik merkezi eleman alımı", "description": "güzellik uzmanı", "_isPlaceholder": true}, "type": "processStep", "position": {"x": 0, "y": 0}}]}, "name": "Luxury baeuty güzellik merkezi eleman alımı", "version": 1, "isActive": true, "isSystem": false, "accountId": "15521bd8-ad1d-4811-8c05-7730909e5ce2", "createdAt": "2026-07-13T14:37:09.510Z", "isDefault": false, "updatedAt": "2026-07-13T14:37:09.510Z", "__typename": "AdvertisementRecruitmentProcess", "description": "güzellik uzmanı"}, "advertisementRecruitmentProcessId": "019f5be9-140c-714a-81e2-cd67026312a0", "advertisementRecruitmentProcessVersionId": "019f5be9-140e-730c-8911-b62fbdcb73b6", "AdvertisementRecruitmentProcessVersionNodeTranslation": [{"id": "019f5be9-1411-73d0-a578-aea333fa89fc", "label": "Luxury baeuty güzellik merkezi eleman alımı", "nodeId": "node-placeholder-1783953428733", "createdAt": "2026-07-13T14:37:09.517Z", "updatedAt": "2026-07-13T14:37:09.517Z", "__typename": "GetAdvertisementRecruitmentProcessVersionNodeTranslationResponseDto", "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "description": "güzellik uzmanı", "advertisementRecruitmentProcessVersionId": "019f5be9-140e-730c-8911-b62fbdcb73b6"}, {"id": "019f5be9-1411-760f-8781-0b78045f1abb", "label": "güzellik uzmanı", "nodeId": "node-placeholder-1783953428733", "createdAt": "2026-07-13T14:37:09.517Z", "updatedAt": "2026-07-13T14:37:09.517Z", "__typename": "GetAdvertisementRecruitmentProcessVersionNodeTranslationResponseDto", "languageId": "019d61b4-cffe-7552-b5ac-ee38dcf97438", "advertisementRecruitmentProcessVersionId": "019f5be9-140e-730c-8911-b62fbdcb73b6"}], "category": "SALES", "jobType": "Freelance", "modeOfOperation": "Remote"}'::jsonb,
