INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f748d-6b9a-7081-b8ce-34546906c5b3',
    'eguzellik-sosyal-medya-icerik-uretebilen-kadin-eleman-araniyor-1000180',
    'Sosyal medya içerik üretebilen, kadın eleman aranıyor.',
    'EGUZELLIK',
    'Güzellik salonumuzda sosyal medyaya hakim çekim yapabilen, içerik üreten, bunları paylaşabilen müşteri girdi çıktısından sorumlu sektörü bilen tercihen güzellik sektöründe çalışmış kadın personel aranmaktadır. ilgilenenlerin cv''lerini yaptığı çalışmaları anlatan yazılarını mesaj olarak yollamaları, tercih edilen adaylar aranıp yüzyüze konuşmaya çağrılacaktır. Ayrıca satış yapma becerisi olan adaylar daha dikkate alınacaktır. sağlanacak katkıya göre Part time ve full time olarak düşünülebilir. Yoğunluktan dolayı lütfen Telefon ile arama yapmayıınız.',
    'Freelance',
    'Remote',
    'NEW_GRADUATE',
