INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f84ab-b2e9-7486-840a-868bb4650f47',
    'markanowpatentas-cagri-merkezi-satis-temsilcisi-1000184',
    'Çağrı Merkezi Satış Temsilcisi (Telesatış)',
    'MARKANOW_PATENT_A_S',
    'Marka tescil ve fikri mülkiyet alanında büyüyen ekibimize, satış konusunda iddialı, ikna kabiliyeti yüksek Çağrı Merkezi Satış Temsilcileri arıyoruz. Pozisyonun Tanımı Gelen ve giden çağrılar üzerinden marka tescil hizmetlerinin satışını yapmak Marka sorgulaması yapan potansiyel müşterilere bilgi vermek ve satışa dönüştürmek Müşteri ihtiyaçlarını doğru analiz ederek uygun hizmeti sunmak Satış sürecini baştan sona profesyonel şekilde yönetmek CRM sistemi üzerinden müşteri takibini yapmak Aranan Nitelikler Tercihen çağrı merkezi / satış deneyimi olan Telefonda iletişimi güçlü, ikna kabiliyeti yüksek Satış hedefleriyle çalışmaya istekli Diksiyonu düzgün, enerjik ve çözüm odaklı Öğrenmeye açık, disiplinli ve sonuç odaklı Marka tescil deneyimi tercih sebebidir (deneyimsiz adaylara eğitim verilir.) Sunduğumuz İmkanlar Maaş + yüksek prim sistemi Aylık ve haftalık performans bonusları Hazır müşteri portföyü (sıcak lead) Profesyonel satış ve marka tescil eğitimi Uzun vadeli çalışma ve kariyer imkânı Kurumsal ve güvenilir çalışma ortamı Çalışma Şekli Hafta içi: 09:30 – 18:30 Cumartesi: Yarım gün Ofis içi çalışma (detay mülakatta paylaşılacaktır.)',
    'FullTime',
    'OnSite',
    'SPECIALIST',
    '{"slug": "markanowpatentas-cagri-merkezi-satis-temsilcisi-1000184", "title": "Çağrı Merkezi Satış Temsilcisi (Telesatış)", "_docId": "019f84ab-b2ed-770e-983a-c8b1936cfc81", "branchId": "83016624-440c-4f96-bdc0-42c099161e28", "category": "SALES", "industry": "SALES", "location": {"latitude": 0, "longitude": 0, "__typename": "Location", "city": "İzmir"}, "accountId": "03c32cfc-6bca-4bb8-b2a8-f68c4a6bcd8e", "companyId": "cf9d68c2-28c9-4f19-b312-693537690577", "createdAt": "2026-07-21T12:34:32.813Z", "locations": [{"latitude": 0, "longitude": 0, "__typename": "Location"}], "maxSalary": 70000, "minSalary": 33000, "updatedAt": "2026-07-21T12:34:32.813Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<p>Marka tescil ve fikri mülkiyet alanında büyüyen ekibimize, satış konusunda iddialı, ikna kabiliyeti yüksek Çağrı Merkezi Satış Temsilcileri arıyoruz.</p><p><strong>Pozisyonun Tanımı<br></strong></p><p></p><ul><li><p>Gelen ve giden çağrılar üzerinden marka tescil hizmetlerinin satışını yapmak</p></li><li><p>Marka sorgulaması yapan potansiyel müşterilere bilgi vermek ve satışa dönüştürmek</p></li><li><p>Müşteri ihtiyaçlarını doğru analiz ederek uygun hizmeti sunmak</p></li><li><p>Satış sürecini baştan sona profesyonel şekilde yönetmek</p></li><li><p>CRM sistemi üzerinden müşteri takibini yapmak</p></li></ul><p></p><p><strong>Aranan Nitelikler</strong></p><p>Tercihen çağrı merkezi / satış deneyimi olan<br>Telefonda iletişimi güçlü, ikna kabiliyeti yüksek<br>Satış hedefleriyle çalışmaya istekli<br>Diksiyonu düzgün, enerjik ve çözüm odaklı<br>Öğrenmeye açık, disiplinli ve sonuç odaklı<br>Marka tescil deneyimi tercih sebebidir (deneyimsiz adaylara eğitim verilir.)</p><p><strong>Sunduğumuz İmkanlar<br><br></strong>Maaş + yüksek prim sistemi<br>Aylık ve haftalık performans bonusları<br>Hazır müşteri portföyü (sıcak lead)<br>Profesyonel satış ve marka tescil eğitimi<br>Uzun vadeli çalışma ve kariyer imkânı<br>Kurumsal ve güvenilir çalışma ortamı</p><p><strong>Çalışma Şekli</strong></p><p>Hafta içi: 09:30 – 18:30<br>Cumartesi: Yarım gün</p><p>Ofis içi çalışma (detay mülakatta paylaşılacaktır.)</p>", "publishedAt": "2026-07-21T13:24:26.511Z", "currencyCode": "TRY", "positionLevel": "SPECIALIST", "isConfidential": false, "advertisementId": "019f84ab-b2e9-7486-840a-868bb4650f47", "isMostPreferred": false, "statusUpdatedAt": "2026-07-21T13:24:26.511Z", "companyShortName": "MARKANOW_PATENT_A_S", "locationSourceType": "Branch", "advertisementNumber": "1000184", "advertisementStatus": "Approved", "advertisementJobType": "FullTime", "advertisementModeOfOperation": "OnSite", "advertisementRecruitmentProcess": {"id": "019f84a7-695a-76e7-a8bb-3da24910ecf4", "data": {"edges": [{"id": "conn-1784637104018-h08idfq", "type": "smoothstep", "source": "node-1784637080226-q1y2p18", "target": "node-1784637081856-upiqln3", "condition": "pass"}, {"id": "conn-1784637112080-eo63x4o", "type": "smoothstep", "source": "node-1784637081856-upiqln3", "target": "node-1784637083440-hooxt7y", "condition": "pass"}], "nodes": [{"id": "node-1784637080226-q1y2p18", "data": {"icon": "📄", "name": "CV İnceleme", "color": "#6b7280", "label": "CV İnceleme"}, "type": "019f84a7-650a-7d5f-9046-5fc2290e0e42", "label": "CV İnceleme", "position": {"x": 329, "y": 184.9000015258789}}, {"id": "node-1784637081856-upiqln3", "data": {"icon": "📞", "name": "Telefon Görüşmesi", "color": "#6b7280", "label": "Telefon Görüşmesi"}, "type": "019f84a7-6676-7761-9f09-def30eb7b816", "label": "Telefon Görüşmesi", "position": {"x": 305, "y": 292.9000015258789}}, {"id": "node-1784637083440-hooxt7y", "data": {"icon": "🎉", "name": "Teklif", "color": "#6b7280", "label": "Teklif"}, "type": "019f84a7-67e5-7338-8a42-3af3d464df82", "label": "Teklif", "position": {"x": 302, "y": 375.9000015258789}}, {"id": "node-placeholder-1784636992412", "data": {"label": "Hızlı İşe Alım", "description