INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f89da-d740-732d-830f-9233231fba14',
    'mbemlak-bay-bayan-calisma-arkadaslari-ariyoruz-1000187',
    'BAY / BAYAN  ÇALIŞMA ARKADAŞLARI ARIYORUZ !',
    'MB_EMLAK',
    'BAY / BAYAN ÇALIŞMA ARKADAŞLARI ARIYORUZ !!! Satış Danışmanı İşin Tanımı : Emlak ofisimizde tam zamanlı olarak gayrimenkul alım-satım, kiralama aracılık hizmetlerinde faaliyet gösterecektir. Ofisimize gelen müşterileri karşılamak, ihtiyaçlarını tespit ederek portfoyümüzde bulunan uygun ilanları öncelikle bilgisayarda daha sonrasında yerinde göstermek, satışını yapmak ve tapu/kredi işlemlerini yürütmek üzere satış danışmanları alınacaktır. PRİM+YEMEK Aranan özellikler ve kişisel beceriler : * Tecrübeli / Tecrübesiz * Askerlik hizmetini yapmış﻿ * 25/45 yaş aralığında ﻿﻿﻿ * Tercihen satış konusunda en az 1 yıl deneyimli, deneyimi yok ise eğitilmek üzere ﻿ * Ehliyeti olan ve şehir içi araç kullanabilen, * Güçlü satış becerilerine sahip, * Güler yüzlü, dinamik,diksiyonu düzgün,proaktif ve vizyon sahibi, * Güçlü ve etkili iletişim kurabilen, * İkna ve yönlendirme becerisine sahip, * Misafir memnuniyetine önem veren ve misafir odaklı çalışabilen * Müşteri takibi ve iş takibi becerisi , * Takım çalışmasına yatkın, * Disiplinli, sorumluluk sahibi, * Kişisel bakımına, giyimine dikkat eden satış danışmanları arıyoruz mbemlak.sahibinden.com',
    'FullTime',
    'OnSite',
    'UNSPECIFIED',
    '{"slug": "mbemlak-bay-bayan-calisma-arkadaslari-ariyoruz-1000187", "title": "BAY / BAYAN  ÇALIŞMA ARKADAŞLARI ARIYORUZ !", "_docId": "019f89da-d744-7b84-be5d-ecfce455d133", "branchId": "efebdcf4-82a3-49f0-b436-c9d3dc51b38c", "industry": "CHEF_HORECA", "location": {"latitude": 0, "longitude": 0, "__typename": "Location", "city": "Antalya"}, "accountId": "27e0e10e-3ab0-4d39-89dd-6b0daf71c0bb", "companyId": "218cd10c-b66e-4c27-83d0-91d339bba1d9", "createdAt": "2026-07-22T12:44:08.386Z", "locations": [{"latitude": 0, "longitude": 0, "__typename": "Location"}], "updatedAt": "2026-07-22T12:44:08.386Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Commission", "sortWeight": 0, "description": "<p><strong>BAY / BAYAN&nbsp; ÇALIŞMA ARKADAŞLARI ARIYORUZ !!!</strong></p><p><strong><br></strong></p><p><strong>Satış Danışmanı</strong><br>İşin Tanımı :&nbsp;Emlak ofisimizde tam zamanlı olarak gayrimenkul alım-satım, kiralama aracılık hizmetlerinde faaliyet gösterecektir. Ofisimize gelen müşterileri karşılamak, ihtiyaçlarını tespit ederek portfoyümüzde bulunan uygun ilanları öncelikle bilgisayarda daha sonrasında yerinde göstermek, satışını yapmak ve tapu/kredi işlemlerini yürütmek üzere satış danışmanları alınacaktır.<br><br></p><p><strong>PRİM+YEMEK</strong></p><p><em>Aranan özellikler ve kişisel beceriler :</em></p><p><br><br>* <strong>Tecrübeli / Tecrübesiz&nbsp;</strong><br>*&nbsp;Askerlik hizmetini yapmış﻿</p><p>*&nbsp;25/45 yaş aralığında&nbsp;﻿﻿﻿</p><p>*&nbsp;Tercihen satış konusunda en az 1 yıl deneyimli, deneyimi yok ise eğitilmek üzere&nbsp;﻿</p><p><strong>*&nbsp;Ehliyeti olan ve şehir içi araç kullanabilen,</strong></p><p>*&nbsp;Güçlü satış becerilerine sahip,</p><p>*&nbsp;Güler yüzlü, dinamik,diksiyonu düzgün,proaktif ve vizyon sahibi,</p><p>*&nbsp;Güçlü ve etkili iletişim kurabilen,</p><p>*&nbsp;İkna ve yönlendirme becerisine sahip,</p><p>*&nbsp;Misafir memnuniyetine önem veren ve misafir odaklı çalışabilen</p><p>*&nbsp;Müşteri takibi ve iş takibi becerisi ,</p><p>*&nbsp;Takım çalışmasına yatkın,</p><p>*&nbsp;Disiplinli, sorumluluk sahibi,</p><p>*&nbsp;Kişisel bakımına, giyimine dikkat eden satış danışmanları arıyoruz</p><p></p><p></p><p><a target=\"_blank\" rel=\"noopener noreferrer nofollow\" href=\"http://mbemlak.sahibinden.com\">mbemlak.sahibinden.com</a></p>", "publishedAt": "2026-07-22T14:15:44.387Z", "currencyCode": "TRY", "positionLevel": "UNSPECIFIED", "isConfidential": false, "advertisementId": "019f89da-d740-732d-830f-9233231fba14", "isMostPreferred": false, "statusUpdatedAt": "2026-07-22T14:15:44.387Z", "companyShortName": "MB_EMLAK", "locationSourceType": "Branch", "advertisementNumber": "1000187", "advertisementStatus": "Approved", "advertisementJobType": "FullTime", "advertisementModeOfOperation": "OnSite", "advertisementRecruitmentProcess": {"id": "019f89d8-8525-7a6d-bdab-86e6ef7c035e", "data": {"edges": [{"id": "edge-1784723688098-0", "type": "smoothstep", "source": "node-1784723688098-0", "target": "node-1784723688098-1", "condition": "always"}, {"id": "edge-1784723688098-1", "type": "smoothstep", "source": "node-1784723688098-1", "target": "node-1784723688098-2"}], "nodes": [{"id": "node-1784723688098-0", "data": {"icon": "📄", "name": "CV İnceleme", "color": "#1f3a93", "label": "CV İnceleme"}, "type": "019f89d8-81cb-793c-9f0b-4fb6b803e34a", "label": "CV İnceleme", "position": {"x": 327, "y": 87}}, {"id": "node-1784723688098-1", "data": {"icon": "📞", "name": "Telefon Görüşmesi", "color": "#0ea5a4", "label": "Telefon Görüşmesi"}, "type": "019f89d8-82e7-7885-af2d-4d038ddebadd", "label": "Telefon Görüşmesi", "position": {"x": 320, "y": 230}}, {"id": "node-1784723688098-2", "data": {"icon": "🎉", "name": "Teklif", "color": "#157347", "label": "Teklif"}, "type": "019f89d8-83f7-7bb5-98d9-a3d6c7f22048", "label": "Teklif", "position": {"x": 320, "y": 380}}, {"id": "node-placeholder-1784723688098", "data": {"label": "Hızlı İşe Al