INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f8a4d-55ae-72b8-955b-a97521691d22',
    'isin-olacak-pazarlama-stajyeri-zorunlu-staj-1000189',
    'Pazarlama Stajyeri (Zorunlu Staj)',
    'İŞİN OLACAK',
    'İşin Olacak , Ayhanlar Holding bünyesinde geliştirilen yapay zekâ destekli bir işe alım platformudur. İşverenlerin doğru adaylara daha hızlı ulaşmasını sağlamak amacıyla geliştirilen platformumuz, yapay zekâ destekli eşleştirme teknolojisi sayesinde aday ve pozisyon uyumunu analiz ederek işe alım süreçlerini daha verimli ve etkili hale getirir. Pazarlama ekibimizin büyüyen operasyonuna destek verecek, öğrenmeye istekli, gelişime açık ve zorunlu stajı bulunan Pazarlama Stajyeri arıyoruz. Bu pozisyonda, dijital pazarlama, içerik üretimi, sosyal medya yönetimi, pazar araştırması ve marka iletişimi çalışmalarına destek vererek pazarlama süreçlerini yakından deneyimlemeniz beklenmektedir. Aynı zamanda kampanya planlama, raporlama ve pazarlama operasyonlarının yürütülmesine katkı sağlayarak profesyonel iş hayatına güçlü bir başlangıç yapma fırsatı elde edeceksiniz. Görev ve Sorumluluklar Dijital pazarlama çalışmalarına destek olmak. Sosyal medya içeriklerinin planlanması ve hazırlanmasına katkı sağlamak. Rakip ve pazar araştırmaları yapmak. Pazarlama kampanyalarının planlama ve raporlama süreçlerine destek vermek. Sunum, rapor ve doküman hazırlıklarında görev almak. Pazarlama ekibinin günlük operasyonel süreçlerine destek olmak. Aranan Nitelikler Üniversitelerin İşletme, Pazarlama, İletişim, Reklamcılık, Halkla İlişkiler veya ilgili bölümlerinde öğrenim gören, Zorunlu stajı bulunan ve bunu belgeleyebilen, Haftada en az 3 gün staja devam edebilecek, MS Office programlarını temel seviyede kullanabilen, İletişim becerileri güçlü, sorumluluk sahibi ve takım çalışmasına yatkın, Öğrenmeye açık, analitik düşünebilen ve gelişime istekli.',
    'Internship',
    'OnSite',
    'INTERN',
    '{"slug": "isin-olacak-pazarlama-stajyeri-zorunlu-staj-1000189", "title": "Pazarlama Stajyeri (Zorunlu Staj)", "_docId": "019f8a4d-55b2-7e5d-9565-1c12a4f68111", "branchId": "019dddfd-2509-7c6a-8f16-6b6781363c85", "industry": "MARKETING_MEDIA", "location": {"latitude": 40.8738863, "longitude": 29.3076729, "__typename": "Location", "city": "Antalya"}, "accountId": "019dddfd-23aa-721d-917f-839467158707", "companyId": "019dddfd-24e4-7fb9-8735-6d956ea2ad97", "createdAt": "2026-07-22T14:49:11.864Z", "locations": [{"latitude": 40.8738863, "longitude": 29.3076729, "__typename": "Location"}], "maxSalary": 8500, "minSalary": 8422.65, "updatedAt": "2026-07-22T14:49:11.864Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<p><strong>İşin Olacak</strong>, Ayhanlar Holding bünyesinde geliştirilen yapay zekâ destekli bir işe alım platformudur.</p><p>İşverenlerin doğru adaylara daha hızlı ulaşmasını sağlamak amacıyla geliştirilen platformumuz, yapay zekâ destekli eşleştirme teknolojisi sayesinde aday ve pozisyon uyumunu analiz ederek işe alım süreçlerini daha verimli ve etkili hale getirir.</p><p>Pazarlama ekibimizin büyüyen operasyonuna destek verecek, öğrenmeye istekli, gelişime açık ve <strong>zorunlu stajı bulunan Pazarlama Stajyeri</strong> arıyoruz.</p><p>Bu pozisyonda, dijital pazarlama, içerik üretimi, sosyal medya yönetimi, pazar araştırması ve marka iletişimi çalışmalarına destek vererek pazarlama süreçlerini yakından deneyimlemeniz beklenmektedir. Aynı zamanda kampanya planlama, raporlama ve pazarlama operasyonlarının yürütülmesine katkı sağlayarak profesyonel iş hayatına güçlü bir başlangıç yapma fırsatı elde edeceksiniz.</p><p></p><h2>Görev ve Sorumluluklar</h2><ul><li><p>Dijital pazarlama çalışmalarına destek olmak.</p></li><li><p>Sosyal medya içeriklerinin planlanması ve hazırlanmasına katkı sağlamak.</p></li><li><p>Rakip ve pazar araştırmaları yapmak.</p></li><li><p>Pazarlama kampanyalarının planlama ve raporlama süreçlerine destek vermek.</p></li><li><p>Sunum, rapor ve doküman hazırlıklarında görev almak.</p></li><li><p>Pazarlama ekibinin günlük operasyonel süreçlerine destek olmak.</p></li></ul><h2>Aranan Nitelikler</h2><ul><li><p>Üniversitelerin İşletme, Pazarlama, İletişim, Reklamcılık, Halkla İlişkiler veya ilgili bölümlerinde öğrenim gören,</p></li><li><p><strong>Zorunlu stajı bulunan</strong> ve bunu belgeleyebilen,</p></li><li><p>Haftada en az <strong>3 gün</strong> staja devam edebilecek,</p></li><li><p>MS Office programlarını temel seviyede kullanabilen,</p></li><li><p>İletişim becerileri güçlü, sorumluluk sahibi ve takım çalışmasına yatkın,</p></li><li><p>Öğrenmeye açık, analitik düşünebilen ve gelişime istekli.</p></li></ul><p></p>", "publishedAt": "2026-07-22T16:16:12.947Z", "currencyCode": "TRY", "positionLevel": "INTERN", "isConfidential": false, "advertisementId": "019f8a4d-55ae-72b8-955b-a97521691d22", "isMostPreferred": false, "statusUpdatedAt": "2026-07-22T16:16:12.947Z", "companyShortName": "İŞİN OLACAK", "locationSourceType": "Branch", "advertisementNumber": "1000189", "advertisementStatus": "Approved", "advertisementJobType": "Internship", "advertisementModeOfOperation": "OnSite", "advertisementRecruitmentProcess": {"id": "019ed95e-2816-7c24-9ecd-3ba0c529b0c3", "data": {"edges": [{"id": "edge-1781763286429-0", "type": "smoothstep", "source": "node-1781763286429-0", "target": "node-1781763286429-1"}, {"id": "edge-1781763286429-1", "type": "smoothstep", "source": "node-1781763286429-1", "target": "node-1781763286429-2"}], "nodes": [{"id": "node-placeholder-1781763286429", "data": {"label": "Hızlı İşe Alım", "description": "CV → Telefon Görüşmesi → Teklif", "_isPlaceholder": true}, "type": "processStep", "position": {"x": 0, "y": 0}}, {"id": "node-1781763286429-0", "data": {"icon": "📄", "name": "CV İnceleme", "color": "#1f3a93", "label": "CV İnceleme"}, "type": "019ed95e-21b5-7