INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f935a-bfe5-76b3-b84c-b6d1475930d3',
    'antandrosdeluxbung-halkla-iliskiler-departmani-1000190',
    'Halkla İlişkiler Departmanı',
    'ANTANDROS_DELUX_BUNG',
    '[şehir] ALTINOLUKTA BULUNAN=&gt; ANTANDROS DELÜX BUNGALOV OTEL BÜNYESINDE BULUNAN HALKLA ILIŞKILER VE TANITIM DEPARTMANINA TECRÜBELİ - TECRÜBESİZ, BAY - BAYAN PERSONEL ALIMI YAPILACAKTIR!!! (ARANAN NITELIKLER} #DİKSİYONU DÜZGÜN #EKIP ÇALIŞMASINA YATKIN #DIŞ GÖRÜNÜŞÜNE ÖNEM VEREN #ESNEK ÇALIŞMA SAATLERİNE AYAK UYDURABİLEN #SORUMLULUK SAHİBİ VE GÜLER YÜZLÜ OLMAK #İLETİŞİM BECERİLERİ GÜÇLÜ [SUNULAN IMKANLAR} #PRİM+EKSTRA ÖDÜLLER #ULAŞIM+YOL #YEMEK #SİGORTA #KONAKLAMA #TURİZİM SEKTÖRÜNDE TECRÜBE VE İŞ İMKANI KAZANMA FIRSATI BAŞVURU YAPAN TÜM ADAYLARA DÖNÜŞ YAPILACAKTIR!!!',
    'FullTime',
    'Hybrid',
