INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f9475-9bc3-7d5b-b885-b69fd82d3503',
    'bybarstalent-sales-and-marketing-specialist-1000191',
    'Sales and Marketing Specialist',
    'BY_BARS_TALENT',
    'İlan Özeti: [şehir] popüler iş merkezlerinden birinde faaliyet gösteren, hazır ofis, sanal ofis, coworking alanı ve toplantı odası kiralama hizmetleri sunan çözüm ortağımız için, dijital içerik üretiminde aktif rol alacak ve satış süreçlerini yönetecek "Satış ve Pazarlama Uzmanı" bünyemizde görev alacak yetkin adaylar değerlendirilecektir. Genel Nitelikler Prezentabl ve kişisel bakımına özen gösteren, 1-3 yıl deneyimli Diksiyonu düzgün, hitabet yeteneği kuvvetli ve ikna kabiliyeti yüksek, Sosyal medya içerik üretimi ve tanıtım filmlerinde sunum yapabilecek özgüvene sahip, MS Office programlarına hakim, CRM sistemlerini kullanabilen ve raporlama süreçlerinde deneyimli, Sorumluluk sahibi, iş takibi ve disiplini güçlü, Satış ve müşteri ilişkileri yönetimi konusunda tecrübeli (tercihen benzer sektörlerde çalışmış). İş Tanımı Potansiyel müşteri adaylarından gelen talepleri telefon ve e-posta yoluyla karşılamak, Müşterileri ofisimize davet ederek tesis tanıtımı gerçekleştirmek ve satış sürecini finalize etmek, Şirketin sosyal medya mecraları için satışa yönelik tanıtım videolarında sunum yapmak ve içerik sürecine katkı sağlamak, Satış faaliyetlerine dair düzenli olarak şirket yönetimine raporlama yapmak. Konum: [şehir] (Özlüce bölgesinde yer alan ofisimizde çalışacak çalışma arkadaşı aranmaktadır.)',
    'FullTime',
    'OnSite',
    'SPECIALIST',
