INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f9480-bfc4-7f04-b660-2f4f2575a0f5',
    'mslticaretanonims-temizlik-ve-cay-personeli-1000193',
    'Temizlik ve Çay Personeli',
    'MSL_TICARET_ANONIM_S',
    'Pozisyon Hakkında [şehir] bulunan ofisimizde, 3 kişilik ekibimize hizmet verecek deneyimli bir Temizlik ve Çay Personeli arıyoruz. Temizlik ve çay servisi konularında uzmanlaşmış, titiz ve güler yüzlü bir takım arkadaşı arıyoruz. Sorumluluklar Ofis temizliğini düzenli olarak sağlamak Çay ve kahve servisi yapmak Ofis malzemelerinin düzenli kontrolünü gerçekleştirmek Temizlik malzemelerinin stok takibini yapmak Ofis düzeninin ve hijyen standartlarının korunmasına katkıda bulunmak Aranan Nitelikler Temizlik ve çay servisi alanında en az 2 yıl deneyim [şehir] ikamet eden Titiz, güler yüzlü ve iletişim becerileri yüksek Takım çalışmasına yatkın Tercih Edilen Nitelikler Ofis ortamında deneyim sahibi olmak Hijyen standartları hakkında bilgi sahibi olmak',
    'FullTime',
    'OnSite',
    'SPECIALIST',
