INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019f94ad-e6b3-7c70-b8e8-3c55b7daf722',
    'modern-yemek-yemek-servis-elemani-1000195',
    'Yemek Servis Elemanı',
    'Modern Yemek',
    'Pozisyon Hakkında Müşteri sahalarında veya ana tesiste hijyenik koşullarda yemek servisi gerçekleştirecek bir Yemek Servis Elemanı arıyoruz. Temizlik ve hijyen standartlarına uygun bir ortam sağlamak için çalışacak, ekibimizin önemli bir parçası olacaksınız. Sorumluluklar Hazırlanan yemeklerin hijyenik koşullarda dağıtımını gerçekleştirmek Yemek servisi öncesi ve sonrası servis alanının, tezgahların ve ekipmanların temizliğini sağlamak Bulaşıkların (çöp ayıştırma, yıkama ve yerleştirme) hijyen standartlarına uygun şekilde yıkanmasını sağlamak Mutfak, yemekhane ve ortak kullanım alanlarının günlük genel temizlik ve hijyen süreçlerini yürütmek Çöp ve atıkların zamanında ve usulüne uygun şekilde bertaraf edilmesini sağlamak İlgili birim yöneticisinin yönlendirmelerine ve hijyen talimatlarına eksiksiz uymak Aranan Nitelikler Temizlik ve hijyen konularında deneyim Takım çalışmasına yatkınlık İletişim becerileri güçlü Detaylara dikkat eden bir yaklaşım',
    'FullTime',
    'OnSite',
    'ENTRY_LEVEL',
    '{"slug": "modern-yemek-yemek-servis-elemani-1000195", "title": "Yemek Servis Elemanı", "_docId": "019f94ad-e6b7-79a4-8b15-cb697ad14fad", "branchId": "f8a46260-1e85-41d6-b44e-fba22a495159", "industry": "CHEF_HORECA", "location": {"latitude": 38.72087619581728, "longitude": 35.34786701202393, "__typename": "Location", "city": "Ankara"}, "accountId": "998e73bd-8aae-4da6-9392-83386d67925a", "companyId": "0ba60a6b-dd21-4f91-bb6b-8babe07997b7", "createdAt": "2026-07-24T15:10:52.592Z", "locations": [{"latitude": 38.72087619581728, "longitude": 35.34786701202393, "__typename": "Location"}], "maxSalary": 32500, "minSalary": 28500, "updatedAt": "2026-07-24T15:10:52.592Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<h3>Pozisyon Hakkında</h3><p>Müşteri sahalarında veya ana tesiste hijyenik koşullarda yemek servisi gerçekleştirecek bir Yemek Servis Elemanı arıyoruz. Temizlik ve hijyen standartlarına uygun bir ortam sağlamak için çalışacak, ekibimizin önemli bir parçası olacaksınız.</p><h3>Sorumluluklar</h3><ul><li>Hazırlanan yemeklerin hijyenik koşullarda dağıtımını gerçekleştirmek</li><li>Yemek servisi öncesi ve sonrası servis alanının, tezgahların ve ekipmanların temizliğini sağlamak</li><li>Bulaşıkların (çöp ayıştırma, yıkama ve yerleştirme) hijyen standartlarına uygun şekilde yıkanmasını sağlamak</li><li>Mutfak, yemekhane ve ortak kullanım alanlarının günlük genel temizlik ve hijyen süreçlerini yürütmek</li><li>Çöp ve atıkların zamanında ve usulüne uygun şekilde bertaraf edilmesini sağlamak</li><li>İlgili birim yöneticisinin yönlendirmelerine ve hijyen talimatlarına eksiksiz uymak</li></ul><h3>Aranan Nitelikler</h3><ul><li>Temizlik ve hijyen konularında deneyim</li><li>Takım çalışmasına yatkınlık</li><li>İletişim becerileri güçlü</li><li>Detaylara dikkat eden bir yaklaşım</li></ul>", "publishedAt": "2026-07-24T18:50:13.121Z", "currencyCode