INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019fb2ca-ffd8-7288-81d0-8216d390325d',
    'yediyirmidortdogrud-kimya-muhendisi-1000200',
    'Kimya Mühendisi (Kalite Kontrol)',
    'YEDIYIRMIDORT_DOGRUD',
    'İş Açıklaması Üniversitelerin Kimya Mühendisliği Bölümünden mezun Kalite Kontrol alanında en az 3 yıl tecrübeli, Kalite Kontrol test cihazları ve ekipmanlarını kullanabilen, Kalite Yönetim Sistemleri konusunda bilgi sahibi, Analitik düşünebilen, problem çözme yeteneğine sahip, raporlama yapabilen, Ekip çalışmasına yatkın, iletişim becerisi yüksek, Tercihen ERP programları ile çalışmış, Askerlik görevini tamamlamış, [şehir] ikamet eden, [şehir] çevresinde ikamet eden veya ulaşım sorunu olmayan. ERKEK adaylar için uygundur. İstenen Yetenek ve Uzmanlıklar Kimyasal hammadde satın alması. Üretim sahasına gelen hammaddelerin kalite kontrolünü yapmak. Üretim proseslerinin hatasız işlemesini sağlamak. Tamamlanmış ürünlerin Ambalaj, Tarih, Gramaj vb. kontrollerini yapmak. Gelen hammaddelerin ve tamamlanmış ürünlerin veri girişlerini yaparak sevk edilmeye hazır hale getirmek. Üretim alanında aktif olarak görev almak. İş sağlığı ve güvenliği kurallarına uyulmasını sağlamak. Çalışanların kişisel koruyucu donanımlarının takibini yapmak. Amirinin vermiş olduğu görevleri eksiksiz yerine getirmek.',
    'FullTime',
    'OnSite',
    'SPECIALIST',
