INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019fb31e-990b-72a7-8adb-3b62fc10092d',
    'hobiegitimdunyasi-asistan-1000201',
    'Asistan',
    'HOBI_EGITIM_DUNYASI',
    'Hafta içi 5 gün [şehir] disindaki okulları akıl oyunları ile alakalı ziyaret etmekteyim.bu dönemde asistanligimi (eğitim danismanli)yapacak yardımcı asistana ihtiyacım var. konaklama yemek vs giderler tarafıma ait olup net maaş ve prim sistemi vardır. yaş aralığı 25-40 tecrübe istemiyorum.En az lise mezunu olmasi giyimine önem vermesi diksiyonu düzgün olması yeterli. ilgilenenlerin WhatsApp yolu ile oturdugu ilçe yaş ve mezuniyet bilgilerini yazmalarini rica ederim. en kısa sürede iletişime geçeceğim.',
    'FullTime',
    'OnSite',
    'ASSISTANT',
