INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019fb341-459b-7d72-8049-67a08c30bf3f',
    'yediyirmidortdogrud-magaza-satis-danismani-1000202',
    'MAĞAZA SATIŞ DANIŞMANI',
    'YEDIYIRMIDORT_DOGRUD',
    'Aşağıdaki niteliklere sahip ve belirtilen süreçleri yönetecek adayların başvurularını bekliyoruz: sektöründe lider müşterimiz adına, Ürün tanıtımı yapacak, Ürün satışına destek sağlayacak, Teşhir çalışmalarını gerçekleştirecek, Mağaza yetkilisi ile ikili ilişkileri sağlayacak, Rakip çalışmalarını ve aktivitelerini gözlemleyecek, Yapılan çalışmaları raporlayacak, MAĞAZA SATIŞ DANIŞMANLARI alınacaktır. En az lise mezunu, İkili ilişkileri kuvvetli, Daha önce mağazacılık tecrübesi olan, Gelişime açık, 20-45 yaş aralığında adayların başvurularını bekliyoruz.',
