INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019fc77a-2a71-7992-85d3-8ec3a02df797',
    'isin-olacak-kidemli-mobil-yazilim-muhendisi-hibrit-istanbul-1000208',
    'Kıdemli Mobil Yazılım Mühendisi',
    'İŞİN OLACAK',
    'Pozisyon Hakkında Büyüyen mobil geliştirme ekibimize katılacak bir Kıdemli Mobil Yazılım Mühendisi arıyoruz. Modern mobil uygulamalar tasarlayacak ve geliştirecek, kullanıcı deneyimini en üst düzeye çıkaracak bir takım arkadaşı arıyoruz. Sorumluluklar Java ve Kotlin kullanarak mobil uygulama geliştirmek Uygulama mimarisini tasarlamak ve uygulamak Performans optimizasyonu yapmak ve kullanıcı geri bildirimlerini değerlendirmek Takım içinde işbirliği yaparak projelerin zamanında tamamlanmasını sağlamak En iyi uygulamaları ve kod standartlarını takip etmek Aranan Nitelikler Mobil yazılım geliştirme alanında en az 5 yıl deneyim Java ve Kotlin dillerinde güçlü bilgi ve deneyim Android uygulama geliştirme konusunda derin bilgi RESTful API entegrasyonu ve veri yönetimi konularında deneyim Tercih Edilen Nitelikler Flutter veya React Native gibi çapraz platform geliştirme deneyimi UI/UX tasarım prensipleri hakkında bilgi Agile metodolojileri ile çalışma deneyimi Sunduklarımız Rekabetçi maaş paketi Yan haklar Hibrit çalışma modeli',
    'FullTime',
    'OnSite',
    'ASSISTANT_SPECIALIST',
    '{"slug": "isin-olacak-kidemli-mobil-yazilim-muhendisi-hibrit-istanbul-1000208", "title": "Kıdemli Mobil Yazılım Mühendisi", "_docId": "019fc77a-2a77-7627-9de5-9b7b1356b543", "branchId": "019dddfd-2509-7c6a-8f16-6b6781363c85", "industry": "IT_SOFTWARE", "location": {"latitude": 40.8738863, "longitude": 29.3076729, "__typename": "Location", "city": "Konya"}, "accountId": "019dddfd-23aa-721d-917f-839467158707", "companyId": "019dddfd-24e4-7fb9-8735-6d956ea2ad97", "createdAt": "2026-08-03T11:55:00.086Z", "locations": [{"latitude": 40.8738863, "longitude": 29.3076729, "__typename": "Location"}], "updatedAt": "2026-08-03T11:55:00.086Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<p>Pozisyon Hakkında</p><p>Büyüyen mobil geliştirme ekibimize katılacak bir Kıdemli Mobil Yazılım Mühendisi arıyoruz. Modern mobil uygulamalar tasarlayacak ve geliştirecek, kullanıcı deneyimini en üst düzeye çıkaracak bir takım arkadaşı arıyoruz.</p><p>Sorumluluklar</p><ul><li>Java ve Kotlin kullanarak mobil uygulama geliştirmek</li><li>Uygulama mimarisini tasarlamak ve uygulamak</li><li>Performans optimizasyonu yapmak ve kullanıcı geri bildirimlerini değerlendirmek</li><li>Takım içinde işbirliği yaparak projelerin zamanında tamamlanmasını sağlamak</li><li>En iyi uygulamaları ve kod standartlarını takip etmek</li></ul><p>Aranan Nitelikler</p><ul><li>Mobil yazılım geliştirme alanında en az 5 yıl deneyim</li><li>Java ve Kotlin dillerinde güçlü bilgi ve deneyim</li><li>Android uygulama geliştirme konusunda derin bilgi</li><li>RESTful API entegrasyonu ve veri yönetimi konularında deneyim</li></ul><p>Tercih Edilen Nitelikler</p><ul><li>Flutter veya React Native gibi çapraz platform geliştirme deneyimi</li><li>UI/UX tasarım prensipleri hakkında bilgi</li><li>Agile metodolojileri ile çalışma deneyimi</li></ul><p>Sunduklarımız</p><ul><li>Rekabetçi maaş paketi</li><li>Ya