INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019fcc04-36e2-7723-a37d-60b1d943af85',
    'insertkesicitakiml-yonetici-asistani-ve-uluslararasi-is-gelistirme-koordinatoru-1000213',
    'Dış Ticaret ve Uluslararası İş Geliştirme Koordinatörü',
    'INSERT_KESICI_TAKIML',
    'UVVA A.Ş., İnsert Kesici Takımlar A.Ş. ve Emin Endüstri Malzemeleri Ltd. Şti. bünyesinde, şirket ortağına doğrudan bağlı çalışacak bir ekip arkadaşı arıyoruz. Pozisyonun temel amacı; İngilizce iletişim ve yazışmaların yürütülmesi, yurt içi ve yurt dışı fuar organizasyonlarının planlanması ve iş süreçlerinin düzenli şekilde takip edilmesidir. Görev ve Sorumluluklar Yabancı üretici, tedarikçi ve iş ortaklarıyla İngilizce yazılı ve sözlü iletişim kurmak İngilizce e-posta, teklif talebi, firma tanıtımı ve iş birliği yazışmaları hazırlamak Yurt içi ve yurt dışı fuarlarda şirket ortağına eşlik ederek İngilizce iletişim desteği sağlamak Fuar öncesi firma araştırması, görüşme planı ve seyahat organizasyonu yapmak Fuar sonrası teklif, numune ve görüşme süreçlerini takip etmek Günlük, haftalık ve aylık iş planlarını hazırlamak ve takip etmek Toplantı, randevu, seyahat ve müşteri ziyaretlerini organize etmek Yapay zekâ araçlarını araştırma, yazışma, raporlama ve planlama süreçlerinde kullanmak Şirketler arasındaki iş ve bilgi akışının koordinasyonuna destek olmak Rapor, sunum, takip tablosu ve toplantı notları hazırlamak Aranan Nitelikler İleri seviyede yazılı ve sözlü İngilizce bilgisi Yabancı firma temsilcileriyle rahat iletişim kurabilme Yurt içi ve yurt dışı seyahat engelinin bulunmaması Planlama, organizasyon ve iş takibi konusunda güçlü olmak MS Office programlarını etkin kullanabilmek Yapay zekâ uygulamalarını aktif ve verimli kullanabilmek Araştırmacı, düzenli, disiplinli ve sonuç odaklı olmak Güçlü temsil ve iletişim yeteneğine sahip olmak Gizliliğe önem vermek ve sorumluluk alabilmek Aktif araç kullanabilmek ve B sınıfı sürücü belgesine sahip olmak [şehir] ve [şehir] şirketler arasında gerektiğinde koordinasyon sağlayabilmek Tercih Sebepleri Dış ticaret, satın alma veya yönetici asistanlığı deneyimi Yurt dışı fuar ve tedarikçi görüşmesi tecrübesi Endüstriyel ürünler, kesici takımlar veya teknik hırdavat sektöründe deneyim CRM, ERP, Odoo veya benzeri iş takip programlarını kullanmış olmak Çalışma Şekli Tam zamanlı Doğrudan şirket ortağına bağlı Ana çalışma lokasyonu: [[şehir]] Yurt içi ve yurt dışı seyahatlere uygunluk Gerektiğinde esnek çalışma düzenine uyum Başvurularda adayların İngilizce seviyesi, seyahat uygunluğu, kullandığı yapay zekâ ve ofis programları ile işe başlayabileceği tarihi belirtmesi beklenmektedir. İhracat, ithalat, gümrük ve dış ticaret yazışmaları yürütülecektir.',
