INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019fd14b-81b3-726c-aab4-93c68199ad63',
    'quanticteknoloji-mid-yazilim-gelistirici-1000215',
    'Mid Yazılım Geliştirici',
    'QUANTIC_TEKNOLOJI',
    'Mid Yazılım Geliştirici 2–4 yıl deneyimli yazılım geliştiriciler için Quanticst Teknoloji olarak büyüyen ekibimize deneyimli bir yazılım geliştirici arıyoruz. Gerçek ve ölçeklenebilir projelerde söz sahibi olmak, modern teknolojilerle çalışmak ve kariyer yolculuğunda bir adım öteye geçmek istiyorsan bu pozisyon tam sana göre! Biz Kimiz? .NET Core & React.js ile kurumsal ölçekte uygulamalar geliştiriyoruz React Native ile çapraz platform mobil çözümler üretiyoruz Kubernetes & DevOps altyapısıyla sağlam ve ölçeklenebilir sistemler yönetiyoruz Teknik kararların birlikte alındığı, düz hiyerarşili ve hızlı büyüyen bir ekibiz Aranan Nitelikler C# / .NET Core 2+ yıl deneyim React.jsBileşen mimarisi & state yönetimi RESTful APITasarım & entegrasyon deneyimi Git & CI/CDVersiyon kontrol & pipeline yönetimi VeritabanıSQL & ORM kullanımı Takım çalışmasıAgile / Scrum ortamında çalışma deneyimi Logo J-Platform ile geliştirme yapmak.',
    'FullTime',
    'Hybrid',
    'SPECIALIST',
