INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019fea40-9007-7ea1-b949-9a61a62c61f9',
    'teksanhidrolik-depo-sevkiyat-personeli-1000220',
    'DEPO SEVKİYAT PERSONELİ',
    'TEKSAN_HIDROLIK',
    'Büyüyen ve gelişen organizasyonumuzda aktif rol alacak takım arkadaşı arayışımız için genel profil: belirtilen niteliklere sahip personel bünyemize kazandırılacaktır.Tercihen depo/sevkiyat alanında deneyimli .Ekip çalışmasına yatkın, düzenli, sorumluluk sahibi .Fiziksel çalışmaya engel durumu olmayan .B sınıfı ehliyet sahibi, aktif araç kullanan .Erkek adaylar için askerlik görevini tamamlamış GÖREV TANIMI .Gelen ürünlerin teslim alınması ve kontrol edilmesi .Ürünlerin depo düzenine uygun şekilde yerleştirilmesi .Siparişlerin hazırlanması ve paketlenmesi .Sevkiyat için ürünlerin hazırlanması ve yüklenmesi .Depo düzen ve temizliğinin sağlanması .Stok takibine destek olunması',
    'FullTime',
    'OnSite',
    'ENTRY_LEVEL',
