INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019fea64-bc8a-7b54-b86f-5ca93a145629',
    'teksanhidrolik-elektrik-teknisyeni-1000222',
    'ELEKTRİK TEKNİSYENİ',
    'TEKSAN_HIDROLIK',
    'Pozisyon kapsamında üstlenilecek temel sorumluluklar ve aranan yetkinlikler: belirtilen niteliklere sahip teknisyen rolünde çalışacak profesyoneller aranmaktadır. Aranan Nitelikler .Meslek lisesi ve ya MYO Elektrik, Elektrik-Elektronik, Mekatronik bölümlerinden mezun .Endüstriyel elektrik sistemleri konusunda deneyimli .Tercihen CNC tezgahları ve hidrolik makineler konusunda deneyimli .Elektrik şeması okuyabilen .Arıza çözüm ve tespit becerisi gelişmiş .İş güvenliği kurallarına önem veren, takım çalışmasına yatkın .Erkek adaylar için askerlik hizmetini tamamlamış Görev Tanımı .CNC tezgahlarının elektrik sistemlerinin bakım ve onarımlarını gerçekleştirmek .Hidrolik pres üretim süreçlerinde elektrik montaj ve devre bağlantısı çalışmalarını yapmak .Makine arızalarının tespiti ve giderilmesini sağlamak .Elektrik panolarının montajı, kontrolü ve devreye alınmasında görev almak .Periyodik bakım faaliyetlerini yürütmek .Üretim ve bakım ekipleriyle koordineli çalışmak',
    'FullTime',
    'OnSite',
    'SPECIALIST',
    '{"slug": "teksanhidrolik-elektrik-teknisyeni-1000222", "title": "ELEKTRİK TEKNİSYENİ", "_docId": "019fea64-bc8f-759e-8907-ce472be1316e", "branchId": "b0c709c1-6f91-42fa-b9a3-9b59df132790", "industry": "INDUSTRIAL_MANUFACTURING", "location": {"latitude": 39.9765901, "longitude": 32.5530842, "__typename": "Location", "city": "Ankara"}, "accountId": "e4d70fb3-e63c-4144-8a47-0ea568f73394", "companyId": "a160af3f-a90a-4f28-b953-2705a169c2a7", "createdAt": "2026-08-10T06:38:18.247Z", "locations": [{"latitude": 39.9765901, "longitude": 32.5530842, "__typename": "Location"}], "updatedAt": "2026-08-10T06:39:26.591Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<p>[şehir] OSB''de faaliyet gösteren ve hidrolik rakor üretimi yapan firmamızda görevlendirilmek üzere, belirtilen niteliklere sahip teknisyen rolünde çalışacak profesyoneller aranmaktadır.</p><p>Aranan Nitelikler</p><p>.Meslek lisesi ve ya MYO Elektrik, Elektrik-Elektronik, Mekatronik bölümlerinden mezun</p><p>.Endüstriyel elektrik sistemleri konusunda deneyimli</p><p>.Tercihen CNC tezgahları ve hidrolik makineler konusunda deneyimli</p><p>.Elektrik şeması okuyabilen</p><p>.Arıza çözüm ve tespit becerisi gelişmiş</p><p>.İş güvenliği kurallarına önem veren, takım çalışmasına yatkın</p><p>.Erkek adaylar için askerlik hizmetini tamamlamış</p><p>Görev Tanımı</p><p>.CNC tezgahlarının elektrik sistemlerinin bakım ve onarımlarını gerçekleştirmek</p><p>.Hidrolik pres üretim süreçlerinde elektrik montaj ve devre bağlantısı çalışmalarını yapmak</p><p>.Makine arızalarının tespiti ve giderilmesini sağlamak</p><p>.Elektrik panolarının montajı, kontrolü ve devreye alınmasında görev almak</p><p>.Periyodik bakım faaliyetlerini yürütmek</p><p>.Üretim ve bakım ekipleriyle koordineli çalışmak</p>", "publishedAt": "2026-08-10T08:14:10.334Z", "currencyCode": "TRY", "positionLevel": "SPECIALIST", "isConfi