INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019feb9d-e9c8-79d7-8f0e-67177aef6e53',
    'gulinsaat-ic-mimar-1000223',
    'İç Mimar',
    'GUL_INSAAT',
    'Takımımıza dahil olacak profesyonelde aradığımız temel özellikler ve iş kapsamı: aşağıda belirtilen kriterlere uygun İç Mimar aramaktayız. Genel nitelikler: Üniversitelerin İç Mimarlık, Çevre Tasarımı veya Mimarlık bölümlerinden mezun, Özellikle Alışveriş Merkezi , Büyük hacimli konut, ofis vb. üst yapı projelerinin iç mimari fonksiyonlarının tasarımında yer almış, minimum 5 yıl deneyimli, Tercihen yatırımcı firma bünyesinde çalışmış Detay üretebilecek, iç mimari, cephe ve gözlem sahibi, Projelerin mimari tasarım sürecine konsept aşamasından itibaren dahil olabilecek, iç mimari fonksiyonları projenin değerini artırıcı yönde geliştirebilecek, projeye değer katabilecek, İnşaat, içmekan tasarımı, mobilya tasarımı ve uygulama projelerinde deneyimli, · Ölçü alma, tasarım, projelendirme, teklif hazırlama ve satış konularına hakim, · Üst yönetime raporlama ve iş analizlerini düzenli olarak yapabilecek, ekip çalışması ve ekip yönetebilme becerisine sahip. Projenin tüm üretim aşamalarında (Teknik, mali, idari, satın alma yönetimi, planlama, organizasyon vb.) koordinasyon ve yönetme becerilerine sahip ve ilgili hazır bilgisayar programları kullanabilen, AutoCAD, Autodesk 3ds Max, SketchUp, Photoshop ve MS Office programlarını etkin şekilde kullanabilen, Estetik bakış açısına sahip, yaratıcı ve yenilikçi tasarım yeteneği gelişmiş, Detaylara önem veren, analitik düşünme ve problem çözme yeteneğine sahip, Takım çalışmasına yatkın, iletişim becerileri güçlü, Müşteri ihtiyaçlarını analiz ederek, fonksiyonel ve estetik çözümler üretebilen, Sorumluluğundaki işlerin zamanında ve kaliteli bir şekilde yapılmasını sağlayacak, Analitik düşünme yetisi olan ve disiplinli, Yoğun çalışma temposuna ve takım çalışmasına uyum sağlayabilecek, B sınıfı sürücü belgesine sahip ve aktif araç kullanabilen, Erkek adaylar için askerlik görevini tamamlamış. [şehir] ’a ulaşım sorunu olmayan veya [şehir] civarında ikamet eden, Ayrıca [şehir] Eskice Mah. ve [şehir] bölgelerine yakın ikamet eden veya bu bölgelere ulaşım sorunu olmayan adayların müracaatlarını beklemekteyiz. İş tanımı: · Şantiyede mevcut müteahhit organizasyonunda yer alan iç mimari sistemlerinde çalışan teknik personelin yönlendirilmesi, · İşin projesine ve teknik şartnamesine uygun olarak iş programına göre hedef süreler de sonuçlandırılması, Gelen mimari projeleri kabul kriterlerimize göre incelemek, Gayrimenkul geliştirme projelerimizin mimari ve diğer disiplin projelerini koordine etmek, Dekorasyon projesi konsept ve uygulama süreçlerini ilgili disiplinleri ile koordineli olarak yürütmek, Tasarım ve konsept alternatifleri getirebilecek, her türlü dekorasyon projesinin bütçesine uygunluğunun denetlenmesini yönetebilmek, · Problem çözme, detay ve maliyet optimizasyonu, müşteri ve sonuç odaklı iş yönetimi yapılması,',
    'FullTime',
    'OnSite',
    'SPECIALIST',
    '{"slug": "gulinsaat-ic-mimar-1000223", "title": "İç Mimar", "_docId": "019feb9d-e9cd-7fec-acd5-6b1ec4dfefd8", "branchId": "5622f109-4142-4d1b-80c7-1cba77daa208", "industry": "CONSTRUCTION", "location": {"latitude": 41.00029922707456, "longitude": 28.839111328125, "__typename": "Location", "city": "İstanbul"}, "accountId": "4c475a58-0ba1-4e77-8e1e-0e4ca92b7960", "companyId": "569766d6-7a3b-4e09-81a8-dc65c05b49fe", "createdAt": "2026-08-10T12:20:22.615Z", "locations": [{"latitude": 41.00029922707456, "longitude": 28.839111328125, "__typename": "Location"}], "maxSalary": 28081, "minSalary": 28080, "updatedAt": "2026-08-10T12:20:22.615Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<p>Nitelikli ve kaliteli konut projeleri geliştiren şirketimizin [şehir]&nbsp;başlamış ve devam etmekte olan projemize ait&nbsp;<strong>[şehir] bulunan Şantiyemizde görevlendirilmek üzere, </strong>aşağıda belirtilen kriterlere uygun<strong>&nbsp;<u>İç Mimar</u>&nbsp;</strong>aramaktayız.</p><p><strong>&nbsp;</strong></p><p><strong>Genel nitelikler:</strong></p><p>&nbsp;</p><ul><li><p>Üniversitelerin İç Mimarlık, Çevre Tasarımı veya Mimarlık bölümlerinden mezun,</p></li><li><p>Özellikle <strong><u>Alışveriş Merkezi</u></strong>, Büyük hacimli konut, ofis vb. üst yapı projelerinin iç mimari fonksiyonlarının tasarımında yer almış, minimum 5 yıl deneyimli,</p></li><li><p>Tercihen yatırımcı firma bünyesinde çalışmış</p></li><li><p>Detay üretebilecek, iç mimari, cephe ve gözlem sahibi,</p></li><li><p>Projelerin mimari tasarım sürecine konsept aşamasından itibaren dahil olabilecek, iç mimari fonksiyonları projenin değerini artırıcı yönde geliştirebilecek, projeye değer katabilecek,</p></li><li><p>İnşaat, içmekan tasarımı, mobilya tasarımı ve uygulama projelerinde deneyimli,</p></li></ul><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Ölçü alma, tasarım, projelendirme, teklif hazırlama ve satış konularına hakim,</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Üst yönetime raporlama ve iş analizlerini düzenli olarak yapabilecek, ekip çalışması ve ekip yönetebilme becerisine sahip.</p><ul><li><p>Projenin tüm üretim aşamalarında (Teknik, mali,&nbsp;idari, satın alma yönetimi,&nbsp;planlama, organizasyon vb.) koordinasyon ve yönetme becerilerine sahip ve ilgili hazır bilgisayar programları kullanabilen,</p></li><li><p>AutoCAD, Autodesk 3ds Max, SketchUp, Photoshop ve MS Office programlarını etkin şekilde kullanabilen,</p></li><li><p>Estetik bakış açısına sahip, yaratıcı ve yenilikçi tasarım yeteneği gelişmiş,</p></li><li><p>Detaylara önem veren, analitik düşünme ve problem çözme yeteneğine sahip,</p></li><li><p>Takım çalışmasına yatkın, iletişim becerileri güçlü,</p></li><li><p>Müşteri ihtiyaçlarını analiz ederek, fonksiyonel ve estetik çözümler üretebilen,</p></li><li><p>Sorumluluğundaki işlerin zamanında ve kaliteli bir şekilde yapılmasını sağlayacak,</p></li><li><p>Analitik düşünme yetisi olan ve disiplinli,</p></li><li><p>Yoğun çalışma temposuna ve takım çalışmasına uyum sağlayabilecek,</p></li><li><p>B sınıfı sürücü belgesine sahip ve aktif araç kullanabilen,</p></li><li><p>Erkek adaylar için askerlik görevini tamamlamış.</p></li><li><p><strong>[şehir]</strong>’a ulaşım sorunu olmayan veya [şehir] civarında ikamet eden,</p></li></ul><p>&nbsp;</p><p><strong>Ayrıca [şehir] Eskice Mah. ve [şehir] bölgelerine yakın ikamet eden veya bu bölgelere ulaşım sorunu olmayan&nbsp;</strong>adayların müracaatlarını beklemekteyiz.</p><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p><p><strong>İş tanımı:</strong></p><p>&nbsp;</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Şantiyede mevcut müteahhit organizasyonunda yer alan iç mimari sistemlerinde çalışan teknik personelin yönlendirilmesi,</p><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; İşin projesine ve teknik şartnamesine uygun olarak iş programına göre hedef süreler de sonuçlandırılması,</p><ul><li><p>Gelen mimari projeleri kabul kriterlerimize göre incelemek,</p></li><li><p>Gayrimenkul geliştirme projelerimizin mimari ve diğer disiplin projelerini koordine etmek,</p></li><li><p>Dekorasyon projesi konsept ve uygulama süreçlerini ilgili disiplinleri ile koordineli olarak yürütmek,</p></li><li><p>Tasarım ve konsept alternatifleri getirebilecek, her türlü dekorasyon projesinin bütçesine uygunluğunun denetlenmesini yönetebilmek,</p></li></ul><p>·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Problem çözme, detay ve maliyet optimizasyonu, müşteri ve sonuç odaklı iş yönetimi yapılması,</p>", "publishedAt": "2026-08-10T14:01:25.116Z", "currencyCode": "TRY", "positionLevel": "SPECIALIST", "isConfidential": false, "advertisementId": "019feb9d-e9c8-79d7-8f0e-67177aef6e53", "isMostPreferred": false, "statusUpdatedAt": "2026-08-10T14:01:25.116Z", "companyShortName": "GUL_INSAAT", "locationSourceType": "Branch", "advertisementNumber": "1000223", "advertisementStatus": "Approved", "advertisementJobType": "FullTime", "advertisementModeOfOperation": "OnSite", "advertisementRecruitmentProcess": {"id": "019feb9b-2510-72fd-996c-eba8c2e949ef", "data": {"edges": [{"id": "edge-fast-0", "type": "smoothstep", "source": "node-fast-0", "target": "node-fast-1"}, {"id": "edge-fast-1", "type": "smoothstep", "source": "node-fast-1", "target": "node-fast-2"}], "nodes": [{"id": "node-placeholder-fast", "data": {"label": "Hızlı İşe Alım", "description": "CV → Telefon Görüşmesi → Teklif", "_isPlaceholder": true}, "type": "processStep", "position": {"x": 0, "y": 0}}, {"id": "node-fast-0", "data": {"icon": "📄", "name": "CV İnceleme", "color": "#1f3a93", "label": "CV İnceleme"}, "type": "0d3a00ff-0000-4000-8000-000000000001", "label": "CV İnceleme", "position": {"x": 320, "y": 80}}, {"id": "node-fast-1", "data": {"icon": "📞", "name": "Telefon Görüşmesi", "color": "#0ea5a4", "label": "Telefon Görüşmesi"}, "type": "0d3a00ff-0000-4000-8000-000000000002", "label": "Telefon Görüşmesi", "position": 