INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019fef5a-8637-7549-90a8-2d80487a92db',
    'quasarinsankaynakl-elektrik-teknikeri-1000225',
    'Elektrik Teknikeri',
    'QUASAR_INSAN_KAYNAKL',
    'Danışmanlığını yapmakta olduğumuz [şehir] faaliyet gösteren müşterimiz için Elektrik Teknikeri/Teknisyeni arıyoruz. ARANILAN ÖZELLİKLER: Teknik lise, MYO veya üniversitelerin ilgili bölümlerinden mezun, Endüstriyel tesislerin elektrik altyapı kurulumu konusunda deneyimli, Saha montaj işlemleri (tava vs.) ve AG sistemlerine ait kablo/terminasyon işlerinde tecrübeli, MCC/PLC panoları hakkında bilgi sahibi, Saha için gerekli olan elektrik malzemelerin seçim süreçlerine destek olabilecek, Endüstriyel proses cihazlarına hakim, Yurt içi seyahat engeli olmayan',
    'FullTime',
    'OnSite',
    'SPECIALIST',
    '{"slug": "quasarinsankaynakl-elektrik-teknikeri-1000225", "title": "Elektrik Teknikeri", "_docId": "019fef5a-863c-7057-a056-bdabe3a633c3", "branchId": "d82e7383-5de2-4fd2-bc6e-a5bb3a017d71", "industry": "INDUSTRIAL_MANUFACTURING", "location": {"latitude": 41.0864676755922, "longitude": 28.817138671875, "__typename": "Location", "city": "Kocaeli"}, "accountId": "404a0c27-002d-44ed-8b1b-0086afcaee35", "companyId": "91dd267e-82a4-4432-902c-fb9bf7ac4573", "createdAt": "2026-08-11T05:45:15.066Z", "locations": [{"latitude": 41.0864676755922, "longitude": 28.817138671875, "__typename": "Location"}], "updatedAt": "2026-08-11T09:56:49.443Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<p>Danışmanlığını yapmakta olduğumuz [şehir] faaliyet gösteren müşterimiz için Elektrik Teknikeri/Teknisyeni arıyoruz.</p><p></p><p>ARANILAN ÖZELLİKLER:</p><ul><li><p>Teknik lise, MYO veya üniversitelerin ilgili bölümlerinden mezun,</p></li><li><p>Endüstriyel tesislerin elektrik altyapı kurulumu konusunda deneyimli,</p></li><li><p>Saha montaj işlemleri (tava vs.) ve AG sistemlerine ait kablo/terminasyon işlerinde tecrübeli,</p></li><li><p>MCC/PLC panoları hakkında bilgi sahibi,</p></li><li><p>Saha için gerekli olan elektrik malzemelerin seçim süreçlerine destek olabilecek,</p></li><li><p>Endüstriyel proses cihazlarına hakim,</p></li><li><p>Yurt içi seyahat engeli olmayan</p></li></ul><p></p>", "publishedAt": "2026-08-11T13:51:09.656Z", "currencyCode": "TRY", "positionLevel": "SPECIALIST", "isConfidential": false, "advertisementId": "019fef5a-8637-7549-90a8-2d80487a92db", "isMostPreferred": false, "statusUpdatedAt": "2026-08-11T13:51:09.656Z", "companyShortName": "QUASAR_INSAN_KAYNAKL", "locationSourceType": "Branch", "advertisementNumber": "1000225", "advertisementStatus": "Approved", "advertisementJobType": "FullTime", "advertisementModeOfOperation": "OnSite"