INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019ffaa1-847d-7bcf-b177-f6e4d1a4a4f9',
    'dogrupkurumsalcoz-ofis-asistani-idari-isler-personeli-1000228',
    'Ofis Asistanı ve İdari İşler Personeli',
    'DO_GRUP_KURUMSAL_COZ',
    'Genel Nitelikler Üniversitelerin Ön Lisans (Bilgi Yönetimi, Büro Yönetimi, Yönetici Sekreterliği, Halkla İlişkiler ve Tanıtım, İnsan Kaynakları Yönetimi, İşletme Yönetimi) veya Lisans (Siyasal Bilgiler, İktisadi ve İdari Bilimler, İktisat, İşletme veya Yönetim Bilimleri Fakülteleri) bölümlerinden mezun, Ofis yönetimi, idari işler veya benzeri pozisyonlarda deneyimli ya da bu alanda gelişime açık, MS Office programlarını (Word, Excel vb.) etkin kullanabilen, Sözlü ve yazılı iletişimi güçlü, temsil kabiliyeti yüksek, Planlama, organizasyon ve zaman yönetimi becerileri gelişmiş, Güler yüzlü, dinamik ve takip yönü güçlü. Görev Tanımı Ofisin genel düzenini, temizliğini ve günlük işleyişini organize etmek, Karşılama, telefon, kargo ve evrak trafiğini yönetmek, Mutfak, kırtasiye ve genel ofis ihtiyaçlarının takibini ve tedariğini yapmak, Şirket içi toplantı, ağırlama ve etkinlik organizasyonlarına destek olmak, İdari işler kapsamındaki fatura, masraf ve belge takiplerine yardımcı olmak. Detaylar yüz yüze konuşulacaktır. Lokasyon: ([şehir])',
    'FullTime',
    'OnSite',
