INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019ffb09-c26b-775c-bb09-b978242dbab3',
    'krcyazilim-satis-yapip-yuksek-paralar-kazanmak-isteyen-satiscilar-araniyor-1000229',
    'Satış Yapıp Yüksek Paralar Kazanmak İsteyen Satışcılar Aranıyor',
    'KRC_YAZILIM',
    'KLC Yazılım olarak yapay zeka, otomasyon ve SaaS alanında geliştirdiğimiz yenilikçi yazılım ürünlerinin satış süreçlerinde görev alacak ekip arkadaşları arıyoruz. Görev Tanımı * Potansiyel müşterilerle iletişime geçerek ürünlerimizin tanıtımını yapmak. * Telefon ve online görüşmeler gerçekleştirerek müşteri ihtiyaçlarını analiz etmek. * Ürünlerimizin satış süreçlerini takip etmek ve müşteri ilişkilerini yönetmek. * Satış hedefleri doğrultusunda aktif rol almak. Aranan Nitelikler * İletişim becerisi güçlü ve ikna kabiliyeti yüksek. * Satış ve pazarlama alanında kendine güvenen. * Hedef odaklı çalışabilen. * Teknoloji ve yazılım sektörüne ilgi duyan. * Öğrenmeye açık ve ekip çalışmasına uyumlu. KLC Yazılım’da Seni Neler Bekliyor? * Yapay zeka ve yazılım sektöründe çalışma fırsatı. * Yenilikçi projelerde aktif görev alma imkanı. * Eğitim ve sürekli destek. * Uzun vadeli iş birliği fırsatı. Başvuru: CV’nizi WhatsApp ( [telefon] )üzerinden göndererek başvurabilirsiniz.',
    'FullTime',
    'Remote',
    'UNSPECIFIED',
    '{"slug": "krcyazilim-satis-yapip-yuksek-paralar-kazanmak-isteyen-satiscilar-araniyor-1000229", "title": "Satış Yapıp Yüksek Paralar Kazanmak İsteyen Satışcılar Aranıyor", "_docId": "019ffb09-c270-7590-90ca-262c81dfe880", "branchId": "b4d572b5-ffab-4c77-adae-10cc14b33acb", "industry": "SALES", "location": {"latitude": 41.0428465, "longitude": 29.0075283, "__typename": "Location", "city": "İstanbul"}, "accountId": "71678de0-d413-4056-92e6-1b7b00287a8d", "companyId": "3324bd04-8549-4d32-a21b-b0a4720d39db", "createdAt": "2026-08-13T12:12:28.653Z", "locations": [{"latitude": 41.0428465, "longitude": 29.0075283, "__typename": "Location"}], "updatedAt": "2026-08-13T12:12:28.653Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Commission", "sortWeight": 0, "description": "<p>KLC Yazılım olarak yapay zeka, otomasyon ve SaaS alanında geliştirdiğimiz yenilikçi yazılım ürünlerinin satış süreçlerinde görev alacak ekip arkadaşları arıyoruz.</p><p>Görev Tanımı</p><p>* Potansiyel müşterilerle iletişime geçerek ürünlerimizin tanıtımını yapmak.</p><p>* Telefon ve online görüşmeler gerçekleştirerek müşteri ihtiyaçlarını analiz etmek.</p><p>* Ürünlerimizin satış süreçlerini takip etmek ve müşteri ilişkilerini yönetmek.</p><p>* Satış hedefleri doğrultusunda aktif rol almak.</p><p>Aranan Nitelikler</p><p>* İletişim becerisi güçlü ve ikna kabiliyeti yüksek.</p><p>* Satış ve pazarlama alanında kendine güvenen.</p><p>* Hedef odaklı çalışabilen.</p><p>* Teknoloji ve yazılım sektörüne ilgi duyan.</p><p>* Öğrenmeye açık ve ekip çalışmasına uyumlu.</p><p>KLC Yazılım’da Seni Neler Bekliyor?</p><p>* Yapay zeka ve yazılım sektöründe çalışma fırsatı.</p><p>* Yenilikçi projelerde aktif görev alma imkanı.</p><p>* Eğitim ve sürekli destek.</p><p>* Uzun vadeli iş birliği fırsatı.</p><p>Başvuru:</p><p>CV’nizi WhatsApp ( [telefon] )üzerinden göndererek başvurabilirsiniz.</p>", "publishedAt": "2026-08-13T12:16:51.069Z", "currencyCode": "TRY", "positionLevel": "UNSPECIFIED", "isConfidential": false, "advertisementId": "019ffb09-c26b-775c-bb09-b978242dbab3", "isMostPreferred": false, "statusUpdatedAt": "2026-08-13T12:16:51.069Z", "companyShortName": "KRC_YAZILIM", "locationSourceType": "Branch", "advertisementNumber": "1000229", "advertisementStatus": "Approved", "advertisementJobType": "FullTime", "advertisementModeOfOperation": "Remote", "advertisementRecruitmentProcess": {"id": "019ffb08-022f-7fbc-9481-564b1b973b1d", "data": {"edges": [{"id": "edge-fast-0", "type": "smoothstep", "source": "node-fast-0", "target": "node-fast-1"}, {"id": "edge-fast-1", "type": "smoothstep", "source": "node-fast-1", "target": "node-fast-2"}], "nodes": [{"id": "node-fast-0", "data": {"icon": "📄", "name": "CV İnceleme", "color": "#1f3a93", "label": "CV İnceleme"}, "type": "0d3a00ff-0000-4000-8000-000000000001", "label": "CV İnceleme", "position": {"x": 320, "y": 80}}, {"id": "node-fast-1", "data": {"icon": "📞", "name": "Telefon Görüşmesi", "color": "#0ea5a4", "label": "Telefon Görüşmesi"}, "type": "0d3a00ff-0000-4000-8000-000000000002", "label": "Telefon Görüşmesi", "position": {"x": 320, "y": 230}}, {"id": "node-fast-2", "data": {"icon": "🎉", "name": "Teklif", "color": "#157347", "label": "Teklif"}, "type": "0d3a00ff-0000-4000-8000-000000000006", "label": "Teklif", "position": {"x": 320, "y": 380}}, {"id": "node-placeholder-fast", "data": {"label": "Hızlı İşe Alım", "description": "CV → Telefon Görüşmesi → Teklif", "_isPlaceholder": true}, "type": "processStep", "position": {"x": 0, "y": 0}}]}, "name": "Hızlı İşe Alım", "version": 2, "isActive": true, "isSystem": false, "accountId": "71678de0-d413-4056-92e6-1b7b00287a8d", "createdAt": "2026-08-13T12:10:33.900Z", "isDefault": false, "updatedAt": "2026-08-13T12:10:43.953Z", "__typename": "AdvertisementRecruitmentProcess", "description": "CV → Telefon Görüşmesi → Teklif"}, "advertisementRecruitmentProcessId": "019ffb08-022f-7fbc-9481-564b1b973b1d",