INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019ffeff-d679-7dcf-8c9b-8814069e3d4f',
    'inkayurticiyurtdis-magaza-destek-elemani-1000233',
    'MAĞAZA DESTEK ELEMANI',
    'INKA_YURTICI_YURTDIS',
    'Perakende sektörünün önde gelen markalarında görev almak ister misiniz? Müşteri karşılama, yönlendirme, hediye paketleme ve reyon düzeni konularında part-time çalışacak, enerjik ve iletişim becerileri yüksek ekip arkadaşları arıyoruz. Görev Tanımı: Mağaza içerisinde müşteri karşılama ve yönlendirme, Hediye paketleme işlemlerinin gerçekleştirilmesi, Reyon düzeni ve görsel düzenlemelere destek verilmesi, Mağaza içerisindeki genel işleyişe katkı sağlanması, Genel Nitelikler: Takım çalışmasına yatkın, İletişim becerisi güçlü, diksiyonu düzgün ve güler yüzlü, Ayakta çalışmaya ve yoğun tempoya uyum sağlayabilecek, Kişisel bakım ve hijyenine özen gösteren, Haftanın en az 3-4 günü çalışmaya uygun.',
    'PartTime',
    'OnSite',
    'UNSPECIFIED',
