INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '019fff8d-3475-780e-ae91-f15801af861d',
    'firmamentum-promotor-tekirdag-corlu-1000234',
    'Promotör',
    'FIRMAMENTUM',
    '“Ürün Tanıtım Görevlisi” istihdam edilecektir. İstenen Yetenek ve Uzmanlıklar Müşteri ilişkileri güçlü, ikna ve iletişim becerileri yüksek, Belirlenen hedefler doğrultusunda mevcut ve potansiyel müşterilerinin satış hacminin artırılmasından sorumlu olacak, Satış, stok ve siparişlerin kontrolünü sağlayacak, Tanzim-teşhir faaliyetlerini gerçekleştirecek adayları aramaktayız. Tercihen küçük ev aletleri ürün satışı konusunda deneyimli, Markasına bağlı, Etkili iletişim ve ikna becerilerine sahip, Değişime hızlı adapte olabilen ve hızlı öğrenebilen, Teknolojiyi takip edip, güçlü iletişim becerilerine sahip, uzlaşmacı, Bayi ve toptan satış kanalı yönetimi konusunda deneyimli, Müşteri ilişkileri güçlü, ikna ve iletişim becerileri yüksek, Hedef ve sonuç odaklı çalışabilen, Tercihen askerliğini yapmış,',
    'FullTime',
    'OnSite',
    'SPECIALIST',
    '{"slug": "firmamentum-promotor-tekirdag-corlu-1000234", "title": "Promotör", "_docId": "019fff8d-347a-72e9-a505-1ff0b411d61f", "branchId": "41c2e56a-2520-453c-a55f-4c4653a58ca9", "industry": "SALES", "location": {"latitude": 41.0707456, "longitude": 29.0509414, "__typename": "Location", "city": "Ankara"}, "accountId": "dd21d9f6-d2ed-4afd-8e43-a7d9c92281de", "companyId": "41014c51-bea5-4a87-91f3-9302b76e9854", "createdAt": "2026-08-14T09:14:31.930Z", "locations": [{"latitude": 41.0707456, "longitude": 29.0509414, "__typename": "Location"}], "updatedAt": "2026-08-14T09:14:31.930Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<p><strong>İş Açıklaması</strong></p><p>İş Açıklaması</p><p>Sektöründe lider, uluslararası standartlarda hizmet sunan kurumsal firmamız bünyesinde görevlendirilmek üzere “Ürün Tanıtım Görevlisi” kadromuza katılacaktır.</p><p><strong>İstenen Yetenek ve Uzmanlıklar</strong></p><p>Müşteri ilişkileri güçlü, ikna ve iletişim becerileri yüksek,</p><p>Belirlenen hedefler doğrultusunda mevcut ve potansiyel müşterilerinin satış hacminin artırılmasından sorumlu olacak,</p><p>Satış, stok ve siparişlerin kontrolünü sağlayacak,</p><p>Tanzim-teşhir faaliyetlerini gerçekleştirecek adayları aramaktayız.</p><p>Tercihen küçük ev aletleri ürün satışı konusunda deneyimli,</p><p>Markasına bağlı,</p><p>Etkili iletişim ve ikna becerilerine sahip,</p><p>Değişime hızlı adapte olabilen ve hızlı öğrenebilen,</p><p>Teknolojiyi takip edip, güçlü iletişim becerilerine sahip, uzlaşmacı,</p><p>Bayi ve toptan satış kanalı yönetimi konusunda deneyimli,</p><p>Müşteri ilişkileri güçlü, ikna ve iletişim becerileri yüksek,</p><p>Hedef ve sonuç odaklı çalışabilen,</p><p>Tercihen askerliğini yapmış,</p><p><br></p>", "publishedAt": "2026-08-14T12:12:48.775Z", "currencyCode": "TRY", "positionLevel": "SPECIALIST", "isConfidential": false, "advertisementId