INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a01521-6376-722f-a0ed-ac0ae4cf852f',
    'ihlaspazarlamaas-satis-temsilcisi-sorumlusu-1000240',
    'Saha Satış Temsilcisi Sorumlusu',
    'IHLAS_PAZARLAMA_AS',
    'Ekibimizi güçlendirmek amacıyla aramıza katılacak çalışma arkadaşları arıyoruz: ; sunum, tanıtım, satış ve pazarlama alanında kendisini geliştirmek isteyen ve yetiştirilmek üzere kariyer hedefi olan saha satış temsilcisi personeller alınacaktır. Gösterilen başarının kariyere dönüştüğü bu kurumda enerjinizin karşılığını almanın mutluluğunu yaşayacaksınız * İletişim becerisi güçlü ve ikna kabiliyeti yüksek. * Satış ve pazarlama alanında kendine güvenen. * Hedef odaklı çalışabilen. • [şehir] en az 1 yıldır ikamet eden. * Kariyerini satış alanında ilerletmeyi hedefleyen, * Güler yüzlü ve Eğitime açık, Kazanç : Maaş destek yüksek prim, başarılı çalışanlarımızın aylık ortalama gelir oranı 60-90 Bin TL arasıdır. Kariyer : Performans ve tecrübeye göre kariyer basamağı sırasıyla Grup liderliği, Ofis müdürlüğü ve Bölge müdürlüğüne ulaşma imkanı süreç içerisinde kariyer planlaması, tüm çalışmalar ve bütün imkanlar açıktır. Promosyon ve ödüller 4 aylık periyotlarda belirlenen kriterleri yakalayan çalışanlarımıza Türkiye’nin en gözde 5 yıldızlı otellerinde unutulmaz tatil, Yılda 2 defa yurt dışı gezileri. Şirket çalışanlarının kazanımları etkili iletişim seminerleri, analitik düşünme ve analiz seminerleri, diksiyon ve hitabet seminerleri, portföy yönetimi ve oluşturma seminerleri. Saha satışı, kurumsal satış ve mağaza satış danışmanlığı yürütülecektir.',
    'FullTime',
    'OnSite',
    'UNSPECIFIED',
    '{"slug": "ihlaspazarlamaas-satis-temsilcisi-sorumlusu-1000240", "title": "Saha Satış Temsilcisi Sorumlusu", "_docId": "01a01521-637a-7f54-b352-d1b4505b2284", "branchId": "e08589b2-788c-408d-9f47-e00db0d1dcf3", "industry": "SALES", "location": {"latitude": 39.91895073120917, "longitude": 32.85409927368165, "__typename": "Location", "city": "Ankara"}, "accountId": "ff9589dc-f127-4cc4-ad16-dcb265004867", "companyId": "586d3ee2-5508-4a77-a54a-42e862dea28c", "createdAt": "2026-08-18T13:48:24.825Z", "locations": [{"latitude": 39.91895073120917, "longitude": 32.85409927368165, "__typename": "Location"}], "updatedAt": "2026-08-18T13:48:24.825Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<p><strong><em>[şehir] BÖLGE MÜDÜRLÜĞÜ</em></strong><br>Türkiye’nin 81 ilinde ve uluslararası alanda faaliyet gösteren köklü gruplarından <strong>İhlas Pazarlama A.Ş. </strong>olarak [şehir] Bölge Müdürlüğü bünyesinde görevlendirilmek üzere; sunum, tanıtım, satış ve pazarlama alanında kendisini geliştirmek isteyen ve yetiştirilmek üzere kariyer hedefi olan saha <strong>satış temsilcisi</strong> personeller alınacaktır.</p><p>Gösterilen başarının kariyere dönüştüğü bu kurumda enerjinizin karşılığını almanın mutluluğunu yaşayacaksınız</p><p><br>* İletişim becerisi güçlü ve ikna kabiliyeti yüksek.<br>* Satış ve pazarlama alanında kendine güvenen.<br>* Hedef odaklı çalışabilen.<br>• [şehir] en az 1 yıldır ikamet eden.</p><p>* Kariyerini satış alanında ilerletmeyi hedefleyen,</p><p>* Güler yüzlü ve Eğitime açık,<br><br><strong>Kazanç</strong> : Maaş destek yüksek prim, başarılı çalışanlarımızın aylık ortalama gelir oranı 60-90 Bin TL arasıdır.<br><br><strong>Kariyer</strong> : Performans ve tecrübeye göre kariyer basamağı sırasıyla Grup liderliği, Ofis müdürlüğü ve Bölge müdürlüğüne ulaşma imkanı süreç içerisinde kariyer planlaması, tüm çalışmalar ve bütün imkanlar açıktır.<br><br>Promosyon ve ödüller 4 aylık periyotlarda belirlenen kriterleri yakalayan çalışanlarımıza Türkiye’nin en gözde 5 yıldızlı otellerinde unutulmaz tatil, Yılda 2 defa yurt dışı gezileri.<br><br>Şirket çalışanlarının kazanımları etkili iletişim seminerleri, analitik düşünme ve analiz seminerleri, diksiyon ve hitabet seminerleri, portföy yönetimi ve oluşturma seminerleri.</p>", "publishedAt": "2026-08-18T13:48:48.585Z", "currencyCode": "TRY", "positionLevel": "UNSPECIFIED", "isConfidential": false, "advertisementId": "01a01521-6376-722f-a0ed-ac0ae4cf852f", "isMostPreferred": false, "statusUpdatedAt": "2026-08-18T13:48:48.585Z", "companyShortName": "IHLAS_PAZARLAMA_AS", "locationSourceType": "Branch", "advertisementNumber": "1000240", "advertisementStatus": "Approved", "advertisementJobType": "FullTime", "advertisementModeOfOperation": "OnSite", "advertisementRecruitmentProcess": {"id": "01a014b5-5575-7a02-8a36-1a655031ef21", "data": {"edges": [{"id": "edge-fast-0", "type": "smoothstep", "source": "node-fast-0", "target": "node-fast-1"}, {"id": "edge-fast-1", "type": "smoothstep", "source": "node-fast-1", "target": "node-fast-2"}], "nodes": [{"id": "node-placeholder-fast", "data": {"label": "Hızlı İşe Alım", "description": "CV → Telefon Görüşmesi → Teklif", "_isPlaceholder": true}, "type": "processStep", "position": {"x": 0, "y": 0}}, {"id": "node-fast-0", "data": {"icon": "📄", "name": "CV İnceleme", "color": "#1f3a93", "label": "CV İnceleme"}, "type": "0d3a00ff-0000-4000-8000-000000000001", "label": "CV İnceleme", "position": {"x": 320, "y": 80}}, {"id": "node-fast-1", "data": {"icon": "📞", "name": "Telefon Görüşmesi", "color": "#0ea5a4", "label": "Telefon Görüşmesi"}, "type": "0d3a00ff-0000-4000-8000-000000000002", "label": "Telefon Görüşmesi", "position": {"x": 320, "y": 230}}, {"id": "node-fast-2", "data": {"icon": "🎉", "name": "Teklif", "color": "#157347", "label": "Teklif"}, "type": "0d3a00ff-0000-4000-8000-000000000006", "label": "Teklif", "po