INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a018df-db99-787f-a366-657b84b47f20',
    'ustunicvedistic-ihracat-pazarlama-uzmani-1000241',
    'İHRACAT PAZARLAMA UZMANI',
    'USTUN_IC_VE_DIS_TIC_',
    '## İHRACAT SATIŞ PAZARLAMA POZİSYONU AKD TRAFİK [şehir] ilçesinde faaliyet göstermek üzere dinamik ve deneyimli bir İhracat Satış Pazarlama Uzmanı aramaktadır. ### Gereksinimler - Tam zamanlı çalışmaya uygunluk. -[şehir] ikamet eden veya edebilecek. - 4-5 yıl ihracat satış ve pazarlama deneyimine sahip olmak. - Çok iyi derecede İNGİLİZCE Tercihen Arapça bilmek - Ön Lisans, Lisans veya Yüksek Lisans mezunu olmak. ### Sorumluluklar - Yurt dışı pazarlama stratejilerinin geliştirilmesi ve uygulanması. - Yurtdışından yeni alıcılar (müşteriler) bulmak. - Pazar araştırmaları yaparak hedef kitleyi belirlemek ve analiz etmek. - İhracat süreçlerini koordine etmek ve tüm lojistik faaliyetlerin düzgün bir şekilde yürütülmesini sağlamak. -Raporlama ve dosyalama konusunda tecrübeli, çözüm ve sonuç odaklı, - Rakip ve pazar analizleri yaparak rapor hazırlamak ve sunmak. - Ülke bazlı hedefler oluşturacak, ihracat yöneticisinin bilgisi dahilin de buna uygun eylem planları geliştirip yöneticisine sunacak, - Satış sözleşmeleri ve proforma gibi belgelerin hazırlanması ve onay sürecinin takibi, - Geliştirilen bu planları uygulayacak, takip edecek, sonucunu raporlayıp önlemler alacak, - Gerektiğinde fuar katılımları, müşteri ziyaretleri yapacak, - Pazarın inceliklerini bilecek ve sürekli olarak tabini yapacak, üstlerine aktaracak Akd Trafik şirketinin güçlü bir ekibin parçası olmak ve kazancınıza değer katmak isterseniz başvurularınızı bekliyoruz.',
    'FullTime',
    'OnSite',
    'SPECIALIST',
    '{"slug": "ustunicvedistic-ihracat-pazarlama-uzmani-1000241", "title": "İHRACAT PAZARLAMA UZMANI", "_docId": "01a018df-db9e-7f9f-996d-e3aab86a0003", "branchId": "f9999ffb-dc42-4884-9584-43ffc532a144", "industry": "SALES", "location": {"latitude": 37.3132581, "longitude": 40.7354383, "__typename": "Location", "city": "Muğla"}, "accountId": "b45e60a1-ff48-446f-ac6a-9fdf9e6e77b7", "companyId": "c1f3da8e-2394-4c11-b6e3-0d6565579c28", "createdAt": "2026-08-19T07:15:19.074Z", "locations": [{"latitude": 37.3132581, "longitude": 40.7354383, "__typename": "Location"}], "updatedAt": "2026-08-19T07:15:19.074Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<p>## İHRACAT SATIŞ PAZARLAMA POZİSYONU</p><p></p><p>AKD TRAFİK [şehir] ilçesinde faaliyet göstermek üzere dinamik ve deneyimli bir İhracat Satış Pazarlama Uzmanı aramaktadır.</p><p></p><p>### Gereksinimler</p><p>- Tam zamanlı çalışmaya uygunluk.</p><p>-[şehir] ikamet eden veya edebilecek.</p><p>- 4-5 yıl ihracat satış ve pazarlama deneyimine sahip olmak.</p><p>- Çok iyi derecede İNGİLİZCE Tercihen Arapça bilmek</p><p>- Ön Lisans, Lisans veya Yüksek Lisans mezunu olmak.</p><p></p><p>### Sorumluluklar</p><p>- Yurt dışı pazarlama stratejilerinin geliştirilmesi ve uygulanması.</p><p>-&nbsp;Yurtdışından yeni alıcılar (müşteriler) bulmak.</p><p>- Pazar araştırmaları yaparak hedef kitleyi belirlemek ve analiz etmek.</p><p>- İhracat süreçlerini koordine etmek ve tüm lojistik faaliyetlerin düzgün bir şekilde yürütülmesini sağlamak.</p><p>-Raporlama ve dosyalama konusunda tecrübeli, çözüm ve sonuç odaklı,</p><p>- Rakip ve pazar analizleri yaparak rapor hazırlamak ve sunmak.</p><p>- Ülke bazlı hedefler oluşturacak, ihracat yöneticisinin bilgisi dahilin de buna uygun eylem planları geliştirip yöneticisine sunacak,</p><p>- Satış sözleşmeleri ve proforma gibi belgelerin hazırlanması ve onay sürecinin takibi,</p><p>- Geliştirilen bu planları uygulayacak, takip edecek, sonucunu raporlayıp önlemler alacak,</p><p>- Gerektiğinde fuar katılımları, müşteri ziyaretleri yapacak,</p><p>- Pazarın inceliklerini bilecek ve sürekli olarak tabini yapacak, üstlerine aktaracak</p><p></p><p>Akd Trafik şirketinin güçlü bir ekibin parçası olmak ve kazancınıza değer katmak isterseniz başvurularınızı bekliyoruz.</p>", "publishedAt": "2026-08-19T08:44:26.693Z", "currencyCode": "TRY", "positionLevel": "SPECIALIST", "isConfidential": false, "advertisementId": "01a018df-db99-787f-a366-657b84b47f20", "isMostPreferred": false, "statusUpdatedAt": "2026-08-19T08:44:26.693Z", "companyShortName": "USTUN_IC_VE_DIS_TIC_", "locationSourceType": "Branch", "advertisementNumber": "1000241", "advertisementStatus": "Approved", "advertisementJobType": "FullTime", "advertisementModeOfOperation": "OnSite", "advertisementRecruitmentProcess": {"id": "01a018de-bad7-7ee0-b250-58579f0adb74", "data": {"edges": [{"id": "edge-fast-0", "type": "smoothstep", "source": "node-fast-0", "target": "node-fast-1"}, {"id": "edge-fast-1", "type": "smoothstep", "source": "node-fast-1", "target": "node-fast-2"}], "nodes": [{"id": "node-placeholder-fast", "data": {"label": "Hızlı İşe Alım", "description": "CV → Telefon Görüşmesi → Teklif", "_isPlaceholder": true}, "type": "processStep", "position": {"x": 0, "y": 0}}, {"id": "node-fast-0", "data": {"icon": "📄", "name": "CV İnceleme", "color": "#1f3a93", "label": "CV İnceleme"}, "type": "0d3a00ff-0000-4000-8000-000000000001", "label": "CV İnceleme", "position": {"x": 320, "y": 80}}, {"id": "node-fast-1", "data": {"icon": "📞", "name": "Telefon Görüşmesi", "color": "#0ea5a4", "label": "Telefon Görüşmesi"}, "type": "0d3a00ff-0000-4000-8000-000000000002", "label": "Telefon Görüşmesi", "position": {"x": 320, "y": 230}}, {"id": "node-fast-2", "data": {"icon": "🎉", "name": "Teklif", "color": "#157347", "label": "Teklif"}, "type": "0d3a00ff-0000-4000-8000-000000000006", "label": "Teklif", "