INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a01911-ad48-76e8-af7c-8fe5a4dc8eda',
    'igmrobotiksistemle-on-muhasebe-ve-sekretarya-sorumlusu-1000242',
    'Ön Muhasebe ve Sekretarya Sorumlusu',
    'IGM_ROBOTIK_SISTEMLE',
    'igm Türkiye Ekibimize Ön Muhasebe ve Sekretarya Sorumlusu Arıyoruz Yeni kurulan ve büyüme yolculuğunun başında olan igm Türkiye ekibimize, ön muhasebe ve sekretarya görevlerini üstlenecek kadın bir çalışma arkadaşı arıyoruz. Küçük ve samimi bir ekibiz. Bu nedenle aradığımız kişinin yalnızca kendisine verilen görevleri yerine getirmesi değil; ofisimizi, işimizi ve şirketimizi gerçekten sahiplenmesi bizim için çok önemli. Başlıca görevler: * Ön muhasebe işlemlerinin ve evrak akışının takibi * Fatura, masraf, ödeme ve cari hesap süreçlerine destek olunması * Mali müşavirimizle evrak koordinasyonunun sağlanması * Telefon, e-posta, yazışma, dosyalama ve kargo süreçlerinin yürütülmesi * Gelen misafirlerin karşılanması ve çay-kahve ikramlarının yapılması * Ofisin günlük düzenine ve temizliğine özen gösterilmesi * Ofis ihtiyaçlarının ve sarf malzemelerinin takip edilmesi Aradığımız özellikler: * Temel ön muhasebe bilgisine sahip veya bu alanda öğrenmeye istekli * MS Office programlarını kullanabilen * Düzenli, güvenilir, çalışkan ve sorumluluk sahibi * Mütevazı, güler yüzlü ve insan ilişkileri güçlü * Küçük bir ekibin gerektirdiği farklı sorumluluklara gönüllü yaklaşan * Uzun vadeli çalışmayı ve şirketimizle birlikte gelişmeyi isteyen Uzun yıllara dayanan deneyimden çok; doğru karaktere, öğrenme isteğine ve işini sahiplenme duygusuna önem veriyoruz. 📍 Çalışma yeri: İMES Organize Sanayi Bölgesi, [şehir] 🕘 Çalışma şekli: Tam zamanlı #İşİlanı #ÖnMuhasebe #Sekreterya #[şehir] #igmTürkiye',
    'FullTime',
    'OnSite',
    'ENTRY_LEVEL',
