INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a033f3-efe7-73ed-b1a4-8eb26727c4ad',
    'omurendustri-on-muhasebe-ve-idari-isler-personeli-1000251',
    'Ön Muhasebe ve  İdari İşler personeli',
    'OMUR_ENDUSTRI',
    'GENEL NİTELİKLER [şehir] de bulunan, Alışveriş Merkezimiz için Ön Muhasebe ve İdari İşler personeli alınacaktır. · 25-55 yaş aralığında, · En az lise mezunu, · B sınıfı Ehliyeti olan, aktif olarak minimum 2 yıldır araç kullanan · Tercihen [şehir] ve çevresinde ikamet eden, · Ms Office programlarına hakim, · Yazılı ve sözlü iletişim becerileri gelişmiş, · Referans verebilecek olan · Erkek adaylar için Askerlik görevini tamamlamış İŞ TANIMI · Muhasebe departmanın da yardımcı personel olarak görev alacak · Basit satın alma işlemlerini takip edecek · Banka ve kamu kurumlarında gerekli işlemlerin takip edecek · Şirket gayrimenkulleri ile ilgili tamir ve satın alma işlerinin takibini yapacak',
    'FullTime',
    'OnSite',
