INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a03922-e2c3-701f-9229-e410b9e613df',
    'tepenetguvenlik-mudur-yardimcisi-1000257',
    'Müdür Yardımcısı',
    'TEPENET_GÜVENLİK_',
    'Departmanımızda görev alarak operasyonel ve stratejik hedeflerimize katkı sağlayacak: şirketimizin operasyonel ve idari süreçlerinde yöneticimize destek olacak Müdür Yardımcısı pozisyonu için başvurular değerlendirilecektir. Görev ve Sorumluluklar Şirket yöneticisine günlük operasyonlarda destek olmak, Personel ve ekip süreçlerinin koordinasyonuna katkı sağlamak, Şirket içi işleyişin düzenli ve verimli şekilde yürütülmesini takip etmek, Müşteri, personel ve iş ortaklarıyla gerçekleştirilen süreçlerin koordinasyonunu sağlamak, Raporlama, toplantı ve planlama süreçlerine destek olmak, Operasyonel aksaklıkların tespit edilmesi ve çözüm süreçlerinin takip edilmesini sağlamak, Yönetim tarafından verilen görev ve sorumlulukları zamanında yerine getirmek, Şirketin kurumsal çalışma düzenine ve gizlilik politikalarına uygun hareket etmek. Aranan Nitelikler En az ön lisans, tercihen lisans mezunu, Yönetim, operasyon veya ekip koordinasyonu konusunda deneyimli, Planlama ve organizasyon yeteneği güçlü, İletişim ve temsil kabiliyeti yüksek, Sorumluluk bilinci gelişmiş ve çözüm odaklı, MS Office programlarını etkin kullanabilen, Yoğun çalışma temposuna uyum sağlayabilen, Takım çalışmasına yatkın, Kurumsal iletişim ve iş disiplinine önem veren, Erkek adaylar için askerlik görevini tamamlamış veya muaf. Pozisyon Bilgileri Pozisyon: Müdür Yardımcısı Çalışma Şekli: Tam Zamanlı Sektör: Güvenlik Hizmetleri Şirket: Tepenet Güvenlik Tepenet Güvenlik ailesine katılmak ve kariyerinizi güvenlik sektöründe geliştirmek istiyorsanız başvurunuzu bekliyoruz.',
    'FullTime',
    'Remote',
    'NEW_GRADUATE',
    '{"slug": "tepenetguvenlik-mudur-yardimcisi-1000257", "title": "Müdür Yardımcısı", "_docId": "01a03922-e2c7-7b44-b7ac-e5ce16328095", "branchId": "01a0391d-60c7-7ab9-8e38-7b53a1d42a26", "industry": "SALES", "location": {"latitude": 40.0800359, "longitude": 29.5096528, "__typename": "Location", "city": "İstanbul"}, "accountId": "7b8b4e6f-1f4c-4b40-905a-65551387b30f", "companyId": "42b8f88d-3144-452d-ab15-840fd9ac2db6", "createdAt": "2026-08-25T13:36:22.731Z", "locations": [{"latitude": 40.0800359, "longitude": 29.5096528, "__typename": "Location"}], "maxSalary": 58500, "minSalary": 58500, "updatedAt": "2026-08-25T13:36:22.731Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<h1>Müdür Yardımcısı</h1><p><strong>Tepenet Güvenlik</strong> bünyesinde görevlendirilmek üzere, şirketimizin operasyonel ve idari süreçlerinde yöneticimize destek olacak <strong>Müdür Yardımcısı</strong> istihdam edilecektir.</p><h3>Görev ve Sorumluluklar</h3><ul><li><p>Şirket yöneticisine günlük operasyonlarda destek olmak,</p></li><li><p>Personel ve ekip süreçlerinin koordinasyonuna katkı sağlamak,</p></li><li><p>Şirket içi işleyişin düzenli ve verimli şekilde yürütülmesini takip etmek,</p></li><li><p>Müşteri, personel ve iş ortaklarıyla gerçekleştirilen süreçlerin koordinasyonunu sağlamak,</p></li><li><p>Raporlama, toplantı ve planlama süreçlerine destek olmak,</p></li><li><p>Operasyonel aksaklıkların tespit edilmesi ve çözüm süreçlerinin takip edilmesini sağlamak,</p></li><li><p>Yönetim tarafından verilen görev ve sorumlulukları zamanında yerine getirmek,</p></li><li><p>Şirketin kurumsal çalışma düzenine ve gizlilik politikalarına uygun hareket etmek.</p></li></ul><h3>Aranan Nitelikler</h3><ul><li><p>En az ön lisans, tercihen lisans mezunu,</p></li><li><p>Yönetim, operasyon veya ekip koordinasyonu konusunda deneyimli,</p></li><li><p>Planlama ve organizasyon yeteneği güçlü,</p></li><li><p>İletişim ve temsil kabiliyeti yüksek,</p></li><li><p>Sorumluluk bilinci gelişmiş ve çözüm odaklı,</p></li><li><p>MS Office programlarını etkin kullanabilen,</p></li><li><p>Yoğun çalışma temposuna uyum sağlayabilen,</p></li><li><p>Takım çalışmasına yatkın,</p></li><li><p>Kurumsal iletişim ve iş disiplinine önem veren,</p></li><li><p>Erkek adaylar için askerlik görevini tamamlamış veya muaf.</p></li></ul><h3>Pozisyon Bilgileri</h3><p><strong>Pozisyon:</strong> Müdür Yardımcısı<br><strong>Çalışma Şekli:</strong> Tam Zamanlı<br><strong>Sektör:</strong> Güvenlik Hizmetleri<br><strong>Şirket:</strong> Tepenet Güvenlik</p><p><strong>Tepenet Güvenlik ailesine katılmak ve kariyerinizi güvenlik sektöründe geliştirmek istiyorsanız başvurunuzu bekliyoruz.</strong></p>", "publishedAt": "2026-08-25T14:02:33.642Z", "currencyCode": "TRY", "positionLevel": "NEW_GRADUATE", "isConfidential": false, "advertisementId": "01a03922-e2c3-701f-9229-e410b9e613df", "isMostPreferred": false, "statusUpdatedAt": "2026-08-25T14:02:33.642Z", "companyShortName": "TEPENET_GÜVENLİK_", "locationSourceType": "Branch", "advertisementNumber": "1000257", "advertisementStatus": "Approved", "advertisementJobType": "FullTime", "advertisementModeOfOperation": "Remote", "advertisementRecruitmentProcess": {"id": "01a03921-8588-7ce9-be28-0f1cc66b7ab5", "data": {"edges": [{"id": "edge-fast-0", "type": "smoothstep", "source": "node-fast-0", "target": "node-fast-1"}, {"id": "edge-fast-1", "type": "smoothstep", "source": "node-fast-1", "target": "node-fast-2"}], "nodes": [{"id": "node-placeholder-fast", "data": {"label": "Hızlı İşe Alım", "description": "CV → Telefon Görüşmesi → Teklif", "_isPlaceholder": true}, "type": "processStep", "position": {"x": 0, "y": 0}}, {"id": "node-fast-0", "data": {"icon": "📄", "name": "CV İnceleme", "color": "#1f3a93", "label": "CV İnceleme"}, "type": "0d3a00ff-0000-4000-8000-000000000001", "label": "CV İnceleme", "position": {"x": 320, "y": 80}}, {"id": "nod