INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a03e5d-2e47-7e45-b3f7-fc1023cd4f62',
    'cagrinet-cagri-merkezi-hizmetleri-telesatis-uzmani-1000259',
    'Telesatış Uzmanı',
    'CAGRİNET CAGRI MERKEZİ HİZMETLERİ',
    'Takımımıza dahil olacak profesyonelde aradığımız temel özellikler ve iş kapsamı: GENEL NİTELİKLER; Aşağıdaki kriterleri karşılayan, satışta başarıyı hedefleyen ekip arkadaşları arıyoruz: Çağrı merkezi veya telefonla satış alanında en az 2 yıl deneyimli, Tercihen sağlık sektörü tecrübesi olan, En az Lise mezunu, Hasta ve hasta yakınları ile etkili iletişim kurabilen, Problem çözebilme yeteneğine sahip, İkna kabiliyeti yüksek, Takım çalışmasına uyumlu, Diksiyonu düzgün, güler yüzlü, iletişime açık, Erkek adaylar için askerlik hizmetini tamamlamış, Sorumluluk sahibi, dikkatli, Ofis içi kurallara ve çalışma disiplinine uygun. Çalışma arkadaşları arıyoruz. İŞ TANIMI; Data aramaları yaparak müşterilere Hastanemizin sağladığı hizmetlerin tanıtımını yapmak, satış sürecini başlatmak ve tamamlamak, Satış öncesi ve sonrası süreçleri takip ederek hasta memnuniyetini sağlamak, Hasta ve hasta yakınları ile sürdürülebilir ilişkiler kurup, ihtiyaçlarını belirleyerek ve satış fırsatlarını değerlendirmek.',
    'FullTime',
    'OnSite',
    'SPECIALIST',
    '{"slug": "cagrinet-cagri-merkezi-hizmetleri-telesatis-uzmani-1000259", "title": "Telesatış Uzmanı", "_docId": "01a03e5d-2e4d-73aa-9056-0af18bc819d5", "branchId": "e1e5227d-bbc5-4607-9092-dc0d21bccc3b", "category": "SALES", "industry": "SALES", "location": {"latitude": 40.8456867, "longitude": 29.3000382, "__typename": "Location", "city": "İstanbul"}, "accountId": "8a7f381b-8767-4a4c-b081-ed3781f2b6b4", "companyId": "fffd2946-8dae-4321-b57b-f2b3e944a980", "createdAt": "2026-08-26T13:58:09.226Z", "locations": [{"latitude": 40.8456867, "longitude": 29.3000382, "__typename": "Location"}], "maxSalary": 40000, "minSalary": 40000, "updatedAt": "2026-08-26T13:58:09.226Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<p>İŞ İLANI</p><p>[şehir] bulunan Üniversite Hastanemizde görevlendirmek üzere, hizmetlerimizin telefon üzerinden tanıtımını ve satışını yapacak Tele - Satış alanında ekip arkadaşı pozisyonu için başvurular değerlendirilecektir.</p><p>GENEL NİTELİKLER;</p><p>Aşağıdaki kriterleri karşılayan, satışta başarıyı hedefleyen ekip arkadaşları arıyoruz:</p><p>Çağrı merkezi veya telefonla satış alanında en az 2 yıl deneyimli,</p><p>Tercihen sağlık sektörü tecrübesi olan,</p><p>En az Lise mezunu,</p><p>Hasta ve hasta yakınları ile etkili iletişim kurabilen,</p><p>Problem çözebilme yeteneğine sahip,</p><p>İkna kabiliyeti yüksek,</p><p>Takım çalışmasına uyumlu,</p><p>Diksiyonu düzgün, güler yüzlü, iletişime açık,</p><p>Erkek adaylar için askerlik hizmetini tamamlamış,</p><p>Sorumluluk sahibi, dikkatli,</p><p>Ofis içi kurallara ve çalışma disiplinine uygun.</p><p>Çalışma arkadaşları arıyoruz.</p><p>İŞ TANIMI;</p><p>Data aramaları yaparak müşterilere Hastanemizin sağladığı hizmetlerin tanıtımını yapmak, satış sürecini başlatmak ve tamamlamak,</p><p>Satış öncesi ve sonrası süreçleri takip ederek hasta memnuniyetini sağlamak,</p><p>Hasta ve hasta yakınları ile sürdürülebilir ilişkiler kurup, ihtiyaçlarını belirleyerek ve satış fırsatlarını değerlendirmek.</p>", "publishedAt": "2026-08-26T14:20:50.159Z", "currencyCode": "TRY", "positionLevel": "SPECIALIST", "isConfidential": false, "advertisementId": "01a03e5d-2e47-7e45-b3f7-fc1023cd4f62", "isMostPreferred": false, "statusUpdatedAt": "2026-08-26T14:20:50.159Z", "companyShortName": "CAGRİNET CAGRI MERKEZİ HİZMETLERİ", "locationSourceType": "Branch", "advertisementNumber": "1000259", "advertisementStatus": "Approved", "advertisementJobType": "FullTime", "advertisementModeOfOperation": "OnSite", "advertisementRecruitmentProcess": {"id": "01a03e13-eead-73a1-9e4d-cdfd6b2cca3b", "data": {"edges": [{"id": "edge-fast-0", "type": "smoothstep", "source": "node-fast-0", "target": "node-fast-1"}, {"id": "edge-fast-1", "type": "smoothstep", "source": "node-fast-1", "target": "node-fast-2"}], "nodes": [{"id": "node-placeholder-fast", "data": {"label": "Hızlı İşe Alım", "description": "CV → Telefon Görüşmesi → Teklif", "_isPlaceholder": true}, "type": "processStep", "position": {"x": 0, "y": 0}}, {"id": "node-fast-0", "data": {"icon": "📄", "name": "CV İnceleme", "color": "#1f3a93", "label": "CV İnceleme"}, "type": "0d3a00ff-0000-4000-8000-000000000001", "label": "CV İnceleme", "position": {"x": 320, "y": 80}}, {"id": "node-fast-1", "data": {"icon": "📞", "name": "Telefon Görüşmesi", "color": "#0ea5a4", "label": "Telefon Görüşmesi"}, "type": "0d3a00ff-0000-4000-8000-000000000002", "label": "Telefon Görüşmesi", "position": {"x": 320, "y": 230}}, {"id": "node-fast-2", "data": {"icon": "🎉", "name": "Teklif", "color": "#157347", "label": "Teklif"}, "type": "0d3a00ff-0000-4000-8000-000000000006", "label": "Teklif", "position": {"x": 320, "y": 380}}]}, "name": "Hızlı İşe Alım", "version": 1, "isActive": true, "isSystem": false, "accountId": "8a7f381b-8767-4a4c-b081-ed3781f2b6b4", "createdAt": "2026-08-26T12:38:08.803Z", "isDefault": false, "updatedAt": "2026-08-26T12:38:08.803Z",