INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a04721-f744-7b86-8cd5-d21e1fd633d1',
    'mskalitekontrol-kalite-kontrol-uretim-destek-personeli-1000263',
    'Kalite Kontrol -Üretim Destek Personeli',
    'MS_KALITE_KONTROL',
    'Rol Özeti & Temel Beklentiler: Üretim hattında ara ve son kontrol süreçlerinin kalite standartlarına uygun olarak yürütülmesi, ölçüm ve test aletlerinin etkin kullanılması, hatalı ürünlerin tespit edilerek ilgili birimlere raporlanması ve üretim destek operasyonlarına katkı sağlanması amacıyla kalite kontrol ve üretim destek personeli ekibimize dahil edilecektir. Tercihen teknik lise/MYO mezunu veya üretim alanında deneyimli adaylar değerlendirilecektir.',
