INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a0483a-a5b3-7633-9482-21f39dc23e15',
    'hizirglobalas-e-ticaret-saha-personeli-istanbul-avrupa-ve-anadolu-yakasi-1000268',
    'E-Ticaret Saha Personeli',
    'HIZIR GLOBAL',
    'Pozisyon Hakkında Yetiş+ Çarşı ve Yetiş Yemek platformlarımızın büyüyen organizasyonunda görev almak üzere, [şehir] ve [şehir] tüm ilçelerinde sahada aktif olarak çalışacak E-Ticaret Saha Personelleri arıyoruz. Sorumluluklar [şehir] genelinde kendisine atanan bölgede aktif saha çalışmaları gerçekleştirmek İşletmeleri ziyaret ederek Yetiş+ Çarşı ve Yetiş Yemek platformlarının tanıtımını yapmak Yeni üye iş yeri kazanımı sağlamak ve üyelik süreçlerini tamamlamak İşletmeler ile birebir görüşmeler gerçekleştirerek platform avantajlarını profesyonel şekilde aktarmak Günlük ziyaret ve üye iş yeri kazanım hedeflerini gerçekleştirmek Saha faaliyetlerini düzenli olarak raporlamak Şirket tarafından belirlenen operasyonel süreç ve çalışma standartlarına uygun hareket etmek Aranan Nitelikler En az lise mezunu Tercihen saha satış, pazarlama veya müşteri kazanımı alanında deneyimli İkna kabiliyeti ve iletişim becerisi yüksek Hedef ve sonuç odaklı çalışabilen Dış görünümüne önem veren Sahada aktif çalışmayı seven Planlı, disiplinli ve sorumluluk sahibi Akıllı telefon ve temel mobil uygulamaları etkin kullanabilen [şehir] veya [şehir] ikamet eden',
    'FullTime',
    'OnSite',
    'UNSPECIFIED',
