INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a04874-3d8e-79d4-b943-ab162365eca0',
    'sertankirco-konuk-koordinatoru-32000-60000-maas-prim-1000269',
    'Konuk Koordinatörü 32.000 - 60.000 Maaş + Prim',
    'SERTAN_KIRCO',
    'Aşağıdaki niteliklere sahip ve belirtilen süreçleri yönetecek adayların başvurularını bekliyoruz: Tecrübeli adaylar önceliğimizdir ancak tecrübesiz adaylar için satış pazarlama üzerine gerekli eğitimler verilecektir. İş tanımı: Bölgede yer alan firma sahipleriyle telefonda görüşme sağlayarak programa davet ederek reklam satışı sağlama. Aranılan özellikler: 20-30 yaş arası Etkili iletişim becerisine sahip, Diksiyonu düzgün, Ekip çalışmasına yatkın, Dinamik ve bu alanda kariyer hedefleyen, İkna kabiliyeti yüksek',
    'FullTime',
