INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a0488c-8c70-7257-abe2-4d13e0255e74',
    'santafarmailac-tablet-baski-makine-operatoru-1000270',
    'Tablet Baskı Makine Operatörü',
    'SANTA_FARMA_ILAC',
    'Tercihen ön lisans mezunu, en az lise veya meslek lisesi mezunu. İlaç veya hızlı tüketim ürünleri sektörlerinde tablet baskı proseslerinde tecrübesi olan, GMP uygulamalarına uyum sağlayabilecek, Esnek çalışma saatlerine ve vardiyalı çalışmaya uyum sağlayabilecek, Takım çalışmasına yatkın olan, Erkek adaylar için askerlik görevini tamamlamış. İŞ TANIMI Katı Form tablet baskı proseslerinde çalışmak, Ürünleri GMP kuralları çerçevesinde istenilen zaman ve kalitede üretmek, İlgili tüm SOP ve talimatlara uygun şekilde makineleri etkin, verimli ve en az fire ile çalıştırmak.',
