INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a05794-c1ea-710e-a5c4-4307fc062541',
    'okuducuyatirimhold-grafik-tasarim-uzmani-1000275',
    'Sosyal Medya ve Dijital İçerik Üreticisi',
    'OKUDUCU_YATIRIM_HOLD',
    'Sosyal medya mecralarımızda (Instagram, Facebook vb.) markamızın vizyonunu yansıtacak, yenilikçi, trendleri yakından takip eden ve dijital varlığımızı güçlendirecek bir Sosyal Medya Uzmanı / Dijital İçerik Üreticisi arıyoruz. Aranan Nitelikler & Görev Tanımı: Yapay Zeka & Tasarım: Photoshop, Illustrator, Canva gibi temel tasarım araçlarının yanı sıra yapay zeka destekli içerik ve görsel üretim araçlarını aktif olarak kullanabilen, Video & Edit: Reels/Shorts formatlarına uygun video kurgusu (edit) yapabilen veya AI destekli video araçlarına hakim olan, İçerik Stratejisi: Markamız için profesyonel, estetik ve etkileşim odaklı görsel/metinsel içerikler tasarlayıp planlayabilen, Trend Takibi: Sosyal medya algoritma değişikliklerini, güncel akımları ve dijital pazarlama trendlerini yakından izleyen, Genel Özellikler: Üretken, estetik bakış açısına sahip, zaman yönetimi güçlü ve alanında tecrübeli, Ulaşım: Tercihen iş yerimize yakın konumda ikamet eden adayların başvurularını bekliyoruz.',
    'FullTime',
    'OnSite',
    'SPECIALIST',
    '{"slug": "okuducuyatirimhold-grafik-tasarim-uzmani-1000275", "title": "Sosyal Medya ve Dijital İçerik Üreticisi", "_docId": "01a05794-c1f0-7b2e-9b2e-c7396235027f", "branchId": "1e9783c4-ae44-46d8-9657-523b1337be8c", "industry": "MARKETING_MEDIA", "location": {"latitude": 41.1634302, "longitude": 28.7664408, "__typename": "Location", "city": "Eskişehir"}, "stateIds": ["019d61b4-d094-73b3-94b7-71be25868e6f"], "accountId": "e676d76a-adf2-415e-ace1-78ba8c18d15c", "companyId": "36466895-8126-4d47-afdb-03bfed2760f2", "createdAt": "2026-08-31T11:29:21.903Z", "locations": [{"latitude": 41.1634302, "longitude": 28.7664408, "__typename": "Location"}], "updatedAt": "2026-08-31T11:29:21.903Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<p>Sosyal medya mecralarımızda (Instagram, Facebook vb.) markamızın vizyonunu yansıtacak, yenilikçi, trendleri yakından takip eden ve dijital varlığımızı güçlendirecek bir Sosyal Medya Uzmanı / Dijital İçerik Üreticisi arıyoruz.</p><p>Aranan Nitelikler &amp; Görev Tanımı:</p><p> Yapay Zeka &amp; Tasarım: Photoshop, Illustrator, Canva gibi temel tasarım araçlarının yanı sıra yapay zeka destekli içerik ve görsel üretim araçlarını aktif olarak kullanabilen,</p><p> Video &amp; Edit: Reels/Shorts formatlarına uygun video kurgusu (edit) yapabilen veya AI destekli video araçlarına hakim olan,</p><p> İçerik Stratejisi: Markamız için profesyonel, estetik ve etkileşim odaklı görsel/metinsel içerikler tasarlayıp planlayabilen,</p><p> Trend Takibi: Sosyal medya algoritma değişikliklerini, güncel akımları ve dijital pazarlama trendlerini yakından izleyen,</p><p> Genel Özellikler: Üretken, estetik bakış açısına sahip, zaman yönetimi güçlü ve alanında tecrübeli,</p><p> Ulaşım: Tercihen iş yerimize yakın konumda ikamet eden adayların başvurularını bekliyoruz.</p>", "publishedAt": "2026-08-31T11:44:54.578Z", "currencyCode": "TR