INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a058d3-23e1-7fac-8e6e-cb496c2324a4',
    'ugurcanuysal-turkiye-genelinde-magaza-gozlemleme-ve-gizli-musteriler-icin-yeni-takim-uyeleri-gerekiyor-1000278',
    'TÜRKİYE GENELİNDE MAĞAZA GÖZLEMLEME VE GİZLİ MÜŞTERİLER İÇİN YENİ TAKIM ÜYELERİ GEREKİYOR!',
    'UGURCAN_UYSAL',
    'Pozisyon Genel Bakış Mağazaları denetleyecek yeni takım arkadaşları arıyoruz! Türkiye''nin dört bir yanından, belirli işletmelerde müşteri olarak günlük yaşamlarında hizmet kalitesini, temizlik durumunu, çalışanların dikkatini ve genel deneyimi değerlendirecek gizli müşterilere ihtiyacımız var. Sorumluluklar Belirlenen işletmelerde müşteri deneyimini gözlemlemek Hizmet kalitesini, temizlik durumunu ve çalışanların dikkatini değerlendirmek Gözlemlerinizi kısa bir rapor halinde bildirmek Gözlem sonuçlarını doğru ve zamanında raporlamak Nitelikler 18 yaşında veya daha büyük olmalı Güçlü gözlem becerileri Telefon ve internete erişim Türkiye''nin her yerinden başvurabilme Sunduklarımız Esnek çalışma saatleri Ek gelir fırsatları Farklı sektörlerde deneyim kazanma şansı Büyüyen bir ekibin parçası olma fırsatı',
    'PartTime',
    'Hybrid',
    'ENTRY_LEVEL',
    '{"slug": "ugurcanuysal-turkiye-genelinde-magaza-gozlemleme-ve-gizli-musteriler-icin-yeni-takim-uyeleri-gerekiyor-1000278", "title": "TÜRKİYE GENELİNDE MAĞAZA GÖZLEMLEME VE GİZLİ MÜŞTERİLER İÇİN YENİ TAKIM ÜYELERİ GEREKİYOR!", "_docId": "01a058d3-23e9-723e-957d-a2d3ff0465fd", "branchId": "2d9767ea-2e63-4659-8f05-d7bc4305cec0", "industry": "SALES", "location": {"latitude": 38.3591693, "longitude": 27.2676116, "__typename": "Location", "city": "Hatay"}, "stateIds": ["019d61b4-d094-73b3-94b8-165fba42fc2d"], "accountId": "d49689f4-950c-4e66-9534-024635271471", "companyId": "78a718aa-5322-4b4b-9da9-154c06005ff9", "createdAt": "2026-08-31T17:17:07.445Z", "locations": [{"latitude": 38.3591693, "longitude": 27.2676116, "__typename": "Location"}], "maxSalary": 100000, "minSalary": 1000, "updatedAt": "2026-08-31T17:17:07.445Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<p>Pozisyon Genel Bakış</p><p>Mağazaları denetleyecek yeni takım arkadaşları arıyoruz! Türkiye''nin dört bir yanından, belirli işletmelerde müşteri olarak günlük yaşamlarında hizmet kalitesini, temizlik durumunu, çalışanların dikkatini ve genel deneyimi değerlendirecek gizli müşterilere ihtiyacımız var.</p><p>Sorumluluklar</p><ul><li>Belirlenen işletmelerde müşteri deneyimini gözlemlemek</li><li>Hizmet kalitesini, temizlik durumunu ve çalışanların dikkatini değerlendirmek</li><li>Gözlemlerinizi kısa bir rapor halinde bildirmek</li><li>Gözlem sonuçlarını doğru ve zamanında raporlamak</li></ul><p>Nitelikler</p><ul><li>18 yaşında veya daha büyük olmalı</li><li>Güçlü gözlem becerileri</li><li>Telefon ve internete erişim</li><li>Türkiye''nin her yerinden başvurabilme</li></ul><p>Sunduklarımız</p><ul><li>Esnek çalışma saatleri</li><li>Ek gelir fırsatları</li><li>Farklı sektörlerde deneyim kazanma şansı</li><li>Büyüyen bir ekibin parçası olma fırsatı</li></ul>", "publishedAt": "2026-09-01T06:45:17.750Z", "currencyCode": "TRY", "positionLevel": "ENTRY_LEVEL", "professionIds": ["01a04336-d4fe-775d-9ad4-7c2d18cc0813"], "isConfidential": false, "advertisementId": "01a058d3-23e1-7fac-8e6e-cb496c2324a4", "isMostPreferred": false, "statusUpdatedAt": "2026-09-01T06:45:17.750Z", "companyShortName": "UGURCAN_UYSAL", "locationSourceType": "Cities", "advertisementNumber": "1000278", "advertisementStatus": "Approved", "advertisementJobType": "PartTime", "advertisementModeOfOperation": "Hybrid", "advertisementRecruitmentProcess": {"id": "01a058cc-98dc-7e76-8801-d0cf0518c271", "data": {"nodes": [{"id": "node-placeholder-1788196198293", "data": {"label": "TÜRKİYE GENELİNDE MAĞAZA GÖZLEMLEME VE GİZLİ MÜŞTERİLER İÇİN YENİ TAKIM ÜYELERİ ARIYORUZ!", "description": "Türkiye''nin neresinde olursanız olun;  \nGünlük yaşamınızda bir müşteri gibi davranarak, belirli işletmelerde hizmet kalitesini, temizlik durumunu, personel ilgisini ve genel deneyimi değerlendirerek para kazanmak ve gözlemlerinizi kısa bir rapora dökmek ister misiniz?\n\n🎯 Kimler Başvurabilir?  \n✅ 18 yaş ve üzeri  \n✅ Güçlü gözlem becerileri  \n✅ Telefon/internete erişim  \n✅ Türkiye''nin herhangi bir yerinden katılabilen bireyler", "_isPlaceholder": true}, "type": "processStep", "position": {"x": 0, "y": 0}}]}, "name": "TÜRKİYE GENELİNDE MAĞAZA GÖZLEMLEME VE GİZLİ MÜŞTERİLER İÇİN YENİ TAKIM ÜYELERİ ARIYORUZ!", "version": 2, "isActive": true, "isSystem": false, "accountId": "d49689f4-950c-4e66-9534-024635271471", "createdAt": "2026-08-31T17:09:58.632Z", "isDefault": false, "updatedAt": "2026-08-31T17:10:11.518Z", "__typename": "AdvertisementRecruitmentProcess", "description": "Türkiye''nin neresinde olursanız olun;  \nGünlük yaşamınızda bir müşteri gibi davranarak, belirli işletmelerde hizmet kalitesini, temizlik durumunu, personel ilgisini ve genel deneyimi değerlendirerek para kazanmak ve gözlemlerinizi kısa bir rapora dökmek ister misiniz?\n\n🎯 Kimler Başvurabilir?  \n✅ 18 yaş ve üzeri  \n✅ Güçlü gözlem becerileri  \n✅ Telefon/internete erişim  \n✅ Türkiye''nin herhangi bir yerinden katılabilen bireyler"}, "advertisementRecruitmentProcessId": "01a058cc-98dc-7e76-8801-d0cf0518c271", "advertisementRecruitmentProcessVersionId": "01a058cc-cb37-7787-a9bb-3c15ae6bfed4", "AdvertisementRecruitmentProcessVersionNodeTranslation": [{"id": "01a058cc-cb39-7844-a5d6-cbb80b013835", "label": "TÜRKİYE GENELİNDE MAĞAZA GÖZLEMLEME VE GİZLİ MÜŞTERİLER İÇİN YENİ TAKIM ÜYELERİ ARIYORUZ!", "nodeId": "node-placeholder-1788196198293", "createdAt": "2026-08-31T17:10:11.523Z", "updatedAt": "2026-08-31T17:10:11.523Z", "__typename": "GetAdvertisementRecruitmentProcessVersionNodeTranslationResponseDto", "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "description": "Türkiye''nin neresinde olursanız olun;  \nGünlük yaşamınızda bir müşteri gibi davranarak, belirli işletmelerde hizmet kalitesini, temizlik durumunu, personel ilgisini ve genel deneyimi değerlendirerek para kazanmak ve gözlemlerinizi kısa bir rapora dökmek ister misiniz?\n\n🎯 Kimler Başvurabilir?  \n✅ 18 yaş ve üzeri  \n✅ Güçlü gözlem becerileri  \n✅ Telefon/internete erişim  \n✅ Türkiye''nin herhangi bir yerinden katılabilen bireyler", "advertisementRecruitmentProcessVersionId": "01a058cc-cb37-7787-a9bb-3c15ae6bfed4"}, {"id": "01a058cc-cb39-7d3e-b0a2-19930839c02a", "label": "WE ARE LOOKING FOR NEW TEAM MEMBERS FOR STORE MONITORING, MYSTERY SHOPPERS ACROSS ALL OF TURKEY!", "nodeId": "node-placeholder-1788196198293", "createdAt": "2026-08-31T17:10:11.523Z", "updatedAt": "2026-08-31T17:10:11.523Z", "__typename": "GetAdvertisementRecruitmentProcessVersionNodeTranslationResponseDto", "languageId": "019d61b4-cffe-7552-b5ac-ee38dcf97438", "description": "No matter where you are in Turkey;\nWould you like to earn money by behaving like a customer in your daily life, evaluating the service quality, cleanliness, staff attention, and overall experience at certain businesses, and putting your observations into a short report?\n\n🎯