INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a05dc5-ac32-7c22-8ca4-b5f89114a6ab',
    'hollygardeneskiseh-garson-komi-kaptan-sef-garson-1000281',
    'Garson, Komi, Kaptan, Şef Garson',
    'HOLLY_GARDEN_ESKISEH',
    'Yeni açılacak mekanımız Holly Garden''da çalıştırılmak üzere farklı çalışma saatleri ve farklı pozisyonlarda personele ihtiyacımız vardır. Ücret, çalışma saatleri tecrübe ve çalışma konumuna göre yüz yüze yapılacak görüşmeden sonra belirlenecektir.',
    'FullTime',
