INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a06759-d814-7edf-850f-2bdc2ba813df',
    'bm-s-grup-mimarlik-ofis-elamani-sekreter-1000286',
    'Ofis Elamanı-Sekreter',
    'BM-S GRUP MIMARLIK',
    'Pozisyon Hakkında Dinamik ofis ortamımızda, planlama, raporlama ve randevu yönetimi konularında destek verecek bir Ofis Elemanı Sekreter arıyoruz. Takvim düzenlemeleri ve ofis içi iletişimi etkin bir şekilde yöneterek, ekibimizin verimliliğini artırmaya yardımcı olacaksınız. Sorumluluklar - Ofis içi takvim ve randevu yönetimini sağlamak - Günlük raporlamaları hazırlamak ve yöneticilere sunmak - Ofis içi iletişimi düzenlemek ve gerekli bilgilendirmeleri yapmak - Planlama süreçlerine destek vermek ve organizasyonel görevleri yerine getirmek - İlgili belgelerin düzenlenmesi ve arşivlenmesi Aranan Nitelikler - Ofis yönetimi veya sekreterlik alanında en az 2 yıl deneyim - İyi derecede MS Office programlarına hakimiyet - İletişim becerileri güçlü, takım çalışmasına yatkın - Detaylara dikkat eden ve organizasyon yeteneği yüksek Sunduklarımız - Tam zamanlı çalışma imkanı - Rekabetçi maaş - Profesyonel gelişim fırsatları - Sıcak ve destekleyici bir çalışma ortamı',
    'FullTime',
    'OnSite',
    'ASSISTANT',
