INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a06ca4-ae7a-7862-80c1-0de06fc3f406',
    'aktifkimyasalveti-ofis-elemani-1000289',
    'Ön Muhasebe ve Ofis Elemanı',
    'AKTIF_KIMYASAL_VE_TI',
    '1997 yılından beri sağlık alanında, kamu ve üniversite hastanelerine hizmet vermekte olan firmamıza aşağıdaki özelliklere sahip ön muhasebe konusunda deneyimli kadın ofis elemanı, sekreter aranmaktadır. · Üniversitelerin, en az ön lisans mezunu · Tercihen Logo Tiger Muhasebe programını kullanabilen · Diksiyonu düzgün, prezantabl, insan ilişkilerinde başarılı · İş takibi kuvvetli, öğrenmeye açık, dikkatli ve detaylara önem veren, iş disiplini yüksek, raporlamaya hakim · MS Office programlarını, ofis araç ve gereçlerini iyi derecede kullanabilen · Ofis içi genel işleyişteki tüm düzenden sorumlu olacak Sadece online başvuru kabul edilecektir.',
    'FullTime',
    'OnSite',
    'UNSPECIFIED',
