INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a07b23-8049-79c4-a6c1-dfbf51cfc20b',
    'aktident-avrupa-yakasi-saha-satis-personeli-1000293',
    'Medikal ve Eczane Saha Satış Personeli',
    'AKTIDENT',
    'İş Açıklaması - Sorumlu olduğu bölgelerdeki doktor ve eczaneleri, iş planı doğrultusunda periyodik olarak ziyaret etmek, - Pazarlama ve Satış stratejilerini kendi bölgesinde eksiksiz uygulamak, - Belirlenen tanıtım ve satış hedefleri doğrultusunda (günlük/haftalık/aylık) çalışma planını oluşturmak ve uygulamak, - Sorumluluğundaki pazar faaliyetlerini takip etmek, - Mevcut ilişkilerin sürekliliğini sağlamak ve Doktor / Eczane portföyünü geliştirmek, - Kampanya ve promosyon süreçlerini etkin bir şekilde yönetmek, İstenen Yetenek ve Uzmanlıklar [şehir] için personel alımı yapılacaktır. Fotoğraflı cv''ler mail yolu ile gönderilmesi gerekmektedir. mail:[eposta] 20 - 45 yaş arası, En az Lise tercihen 2 yıllık yüksekokul veya üniversite mezunu, Satış sektöründe kariyer planlaması olan, İkna kabiliyeti yüksek,diksiyonu düzgün, Temsil yeteneği güçlü,insan ilişkilerinde başarılı, Sorumluluk sahibi,disiplinli ve pozitif düşünen, Yoğun iş temposuna uyum gösterebilecek,güler yüzlü ve çözüm odaklı,takım çalışmasına yatkın, MS Office programlarını etkin bir şekilde kullanabilen, Seyahat engeli bulunmayan, Erkek adaylar için askerliğini tamamlamış, Medikal ürünlerin saha satışı, eczane ve kliniklere ürün satışı, doğrudan saha satışı, müşteri satışı ve portföy satış yönetimi yapılacaktır.',
    'FullTime',
    'Remote',
