INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a08080-2a84-70a9-80bf-478949fb1c78',
    'birebiringilizce-ingilizce-ogretmeni-1000295',
    'İngilizce Öğretmeni',
    'BIREBIR_INGILIZCE',
    'Genel İngilizce eğitimi ile IELTS, TOEFL, PTE gibi akademik ve özel amaçlı (ESP) dil sınavlarına hazırlık alanında deneyimli, öğrenci odaklı ve dinamik İngilizce Eğitmenleri arıyoruz. Genel Nitelikler: Üniversitelerin İngilizce Öğretmenliği, İngiliz Dili ve Edebiyatı, Amerikan Kültürü ve Edebiyatı veya Mütercim-Tercümanlık bölümlerinden mezun, Formasyon belgesine veya uluslararası geçerliliği olan bir eğitmenlik sertifikasına (CELTA, DELTA, TESOL vb.) sahip, Genel İngilizce seviye eğitimlerinde ve IELTS/TOEFL gibi akademik sınav formatlarında en az 2 yıl eğitmenlik tecrübesi bulunan, Sınav stratejilerine, soru tiplerine ve değerlendirme kriterlerine (özellikle Speaking ve Writing süreçlerine) hakim, Dijital eğitim araçlarını ve yeni nesil öğretim materyallerini aktif kullanabilen, İletişim becerileri güçlü, öğrenci gelişimini düzenli takip edip geri bildirim sağlayabilen.',
    'Contract',
    'Hybrid',
    'ENTRY_LEVEL',
    '{"slug": "birebiringilizce-ingilizce-ogretmeni-1000295", "title": "İngilizce Öğretmeni", "_docId": "01a08080-2a89-7be8-86aa-244ba4d3a3bd", "branchId": "5b521f38-b1c9-4262-a3fe-aa6f4dec1671", "industry": "EDUCATION", "location": {"latitude": 40.9929379, "longitude": 29.1135187, "__typename": "Location", "city": "Tokat"}, "accountId": "6b5f5e04-13ed-499e-a5ff-792a82afe18c", "companyId": "aca2833e-2141-4660-8079-a1df4f0c68c1", "createdAt": "2026-09-08T10:11:18.293Z", "locations": [{"latitude": 40.9929379, "longitude": 29.1135187, "__typename": "Location"}], "updatedAt": "2026-09-08T10:11:18.293Z", "__typename": "AdvertisementSearchResult", "isFeatured": true, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Hourly", "sortWeight": 0, "description": "<p>Genel İngilizce eğitimi ile IELTS, TOEFL, PTE gibi akademik ve özel amaçlı (ESP) dil sınavlarına hazırlık alanında deneyimli, öğrenci odaklı ve dinamik <strong>İngilizce Eğitmenleri</strong> arıyoruz.</p><p><strong>Genel Nitelikler:</strong></p><ul><li><p>Üniversitelerin İngilizce Öğretmenliği, İngiliz Dili ve Edebiyatı, Amerikan Kültürü ve Edebiyatı veya Mütercim-Tercümanlık bölümlerinden mezun,</p></li><li><p>Formasyon belgesine veya uluslararası geçerliliği olan bir eğitmenlik sertifikasına (CELTA, DELTA, TESOL vb.) sahip,</p></li><li><p>Genel İngilizce seviye eğitimlerinde ve IELTS/TOEFL gibi akademik sınav formatlarında en az 2 yıl eğitmenlik tecrübesi bulunan,</p></li><li><p>Sınav stratejilerine, soru tiplerine ve değerlendirme kriterlerine (özellikle Speaking ve Writing süreçlerine) hakim,</p></li><li><p>Dijital eğitim araçlarını ve yeni nesil öğretim materyallerini aktif kullanabilen,</p></li><li><p>İletişim becerileri güçlü, öğrenci gelişimini düzenli takip edip geri bildirim sağlayabilen.<br><br></p></li></ul><p></p>", "publishedAt": "2026-09-08T14:22:28.736Z", "currencyCode": "TRY", "positionLevel": "ENTRY_LEVEL", "professionIds": ["01a04336-d506-749a-8592-57210d81a83e"], "isConfidentia