INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a08b7f-6fc1-74e9-84d1-381caadcd913',
    'isin-olacak-stratejik-musteri-yoneticisi-1000304',
    'Stratejik Müşteri Yöneticisi',
    'İŞİN OLACAK',
    'Stratejik Müşteri Yöneticisi İşinOlacak A.Ş. olarak büyüyen ekibimize katılacak, müşteri ilişkileri ve satış yönetimi konusunda deneyimli Stratejik Müşteri Yöneticisi arıyoruz. Bu pozisyonda, şirketimizin stratejik ve kilit müşterileriyle ilişkilerin yönetilmesi, mevcut müşteri portföyünün geliştirilmesi ve yeni iş fırsatlarının yaratılması süreçlerinde aktif rol alacaksınız. Sorumluluklar Stratejik ve kilit müşterilerle uzun vadeli, güçlü ve sürdürülebilir ilişkiler geliştirmek, Mevcut müşteri portföyünü yönetmek ve müşteri memnuniyetini artırmak, Müşterilerin ihtiyaçlarını analiz ederek uygun ürün ve hizmet çözümleri sunmak, Yeni satış ve iş geliştirme fırsatlarını tespit etmek, Satış hedefleri doğrultusunda müşteri bazlı aksiyon planları oluşturmak ve takip etmek, Teklif, sözleşme, fiyatlandırma ve müzakere süreçlerini yönetmek, Müşteri taleplerini ilgili iç ekiplerle koordineli şekilde sonuçlandırmak, Pazar ve rakip analizleri yaparak satış stratejilerinin geliştirilmesine katkı sağlamak, Düzenli olarak satış, müşteri ve portföy raporlamaları hazırlamak, Müşteri ziyaretleri, toplantıları ve sunumlarını gerçekleştirmek. Aradığımız Nitelikler Tercihen üniversitelerin ilgili bölümlerinden mezun, Stratejik Müşteri Yönetimi, Kurumsal Satış, B2B Satış veya İş Geliştirme alanlarında en az 5 yıl deneyimli, Kurumsal müşteri yönetimi ve satış süreçlerine hâkim, Güçlü iletişim ve müzakere becerilerine sahip, Müşteri ilişkileri yönetiminde başarılı ve çözüm odaklı, Satış hedefleriyle çalışmaya ve sonuç odaklı ilerlemeye alışkın, Analitik düşünme ve problem çözme becerileri güçlü, CRM ve MS Office programlarını etkin kullanabilen, Planlama, takip ve organizasyon becerileri gelişmiş, Seyahat engeli bulunmayan, Takım çalışmasına yatkın ve yüksek motivasyonlu. Eğer siz de güçlü müşteri ilişkileri kurabileceğinize, satış hedeflerini büyütebileceğinize ve İşinOlacak''ın büyüme yolculuğuna katkı sağlayabileceğinize inanıyorsanız, sizi ekibimize bekliyoruz!',
    'FullTime',
    'OnSite',
    'SENIOR_SPECIALIST',
    '{"slug": "isin-olacak-stratejik-musteri-yoneticisi-1000304", "title": "Stratejik Müşteri Yöneticisi", "_docId": "01a08b7f-6fca-7bec-808c-5e3f2c9781d5", "branchId": "019dddfd-2509-7c6a-8f16-6b6781363c85", "industry": "SALES", "location": {"latitude": 40.8738863, "longitude": 29.3076729, "__typename": "Location", "city": "Muğla"}, "accountId": "019dddfd-23aa-721d-917f-839467158707", "companyId": "019dddfd-24e4-7fb9-8735-6d956ea2ad97", "createdAt": "2026-09-10T13:26:19.849Z", "locations": [{"latitude": 40.8738863, "longitude": 29.3076729, "__typename": "Location"}], "updatedAt": "2026-09-10T13:26:19.849Z", "__typename": "AdvertisementSearchResult", "isFeatured": false, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<h1>Stratejik Müşteri Yöneticisi </h1><p><strong>İşinOlacak A.Ş.</strong> olarak büyüyen ekibimize katılacak, müşteri ilişkileri ve satış yönetimi konusunda deneyimli Stratejik Müşteri Yöneticisi  arıyoruz.</p><p>Bu pozisyonda, şirketimizin stratejik ve kilit müşterileriyle ilişkilerin yönetilmesi, mevcut müşteri portföyünün geliştirilmesi ve yeni iş fırsatlarının yaratılması süreçlerinde aktif rol alacaksınız.</p><h3><strong>Sorumluluklar</strong></h3><ul><li><p>Stratejik ve kilit müşterilerle uzun vadeli, güçlü ve sürdürülebilir ilişkiler geliştirmek,</p></li><li><p>Mevcut müşteri portföyünü yönetmek ve müşteri memnuniyetini artırmak,</p></li><li><p>Müşterilerin ihtiyaçlarını analiz ederek uygun ürün ve hizmet çözümleri sunmak,</p></li><li><p>Yeni satış ve iş geliştirme fırsatlarını tespit etmek,</p></li><li><p>Satış hedefleri doğrultusunda müşteri bazlı aksiyon planları oluşturmak ve takip etmek,</p></li><li><p>Teklif, sözleşme, fiyatlandırma ve müzakere süreçlerini yönetmek,</p></li><li><p>Müşteri taleplerini ilgili iç ekiplerle koordineli şekilde sonuçlandırmak,</p></li><li><p>Pazar ve rakip analizleri yaparak satış stratejilerinin geliştirilmesine katkı sağlamak,</p></li><li><p>Düzenli olarak satış, müşteri ve portföy raporlamaları hazırlamak,</p></li><li><p>Müşteri ziyaretleri, toplantıları ve sunumlarını gerçekleştirmek.</p></li></ul><h3><strong>Aradığımız Nitelikler</strong></h3><ul><li><p>Tercihen üniversitelerin ilgili bölümlerinden mezun,</p></li><li><p><strong>Stratejik Müşteri Yönetimi, Kurumsal Satış, B2B Satış veya İş Geliştirme alanlarında en az 5 yıl deneyimli,</strong></p></li><li><p>Kurumsal müşteri yönetimi ve satış süreçlerine hâkim,</p></li><li><p>Güçlü iletişim ve müzakere becerilerine sahip,</p></li><li><p>Müşteri ilişkileri yönetiminde başarılı ve çözüm odaklı,</p></li><li><p>Satış hedefleriyle çalışmaya ve sonuç odaklı ilerlemeye alışkın,</p></li><li><p>Analitik düşünme ve problem çözme becerileri güçlü,</p></li><li><p>CRM ve MS Office programlarını etkin kullanabilen,</p></li><li><p>Planlama, takip ve organizasyon becerileri gelişmiş,</p></li><li><p>Seyahat engeli bulunmayan,</p></li><li><p>Takım çalışmasına yatkın ve yüksek motivasyonlu.</p></li></ul><p><strong>Eğer siz de güçlü müşteri ilişkileri kurabileceğinize, satış hedeflerini büyütebileceğinize ve İşinOlacak''ın büyüme yolculuğuna katkı sağlayabileceğinize inanıyorsanız, sizi ekibimize bekliyoruz!</strong></p>", "publishedAt": "2026-09-10T13:35:57.241Z", "currencyCode": "TRY", "positionLevel": "SENIOR_SPECIALIST", "professionIds": ["01a04336-d50c-76cf-a638-d32eb7a43951"], "isConfidential": false, "advertisementId": "01a08b7f-6fc1-74e9-84d1-381caadcd913", "isMostPreferred": false, "statusUpdatedAt": "2026-09-10T13:35:57.241Z", "companyShortName": "İŞİN OLACAK", "locationSourceType": "Branch", "advertisementNumber": "1000304", "advertisementStatus": "Approved", "advertisementJobType": "FullTime", "advertisementModeOfOperation": "OnSite", "advertisementRecruitmentProcess": {"id": "019fc773-2db8-7cf5-a8de-6ad08e3d57ec", "data": {"edges": [{"id": "conn-1785757993468-0-twcg68v", "type": "smoothstep", "source": "node-1785757972566-yhpwaoa", "target": "node-1785757975549-n