INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a08f79-29ec-7242-900a-2dbd06ac46aa',
    'mayatelekominikasyo-tele-satis-temsilcisi-ofis-tam-zamanli-1000308',
    'Tele Satış Temsilcisi (Ofis - Tam Zamanlı)',
    'MAYA_TELEKOMINIKASYO',
    'Pozisyon Hakkında Anlaşmalı hastane kurumlarımızın check-up paketlerinin satışını yapmaktayız. Dinamik bir satış ekibine katılacak bir Tele Satış Temsilcisi arıyoruz. Müşteri ilişkilerini güçlendirmek ve satış hedeflerimizi gerçekleştirmek için etkili iletişim becerilerinizi kullanarak, potansiyel müşterilere ulaşacak ve ürünlerimizi tanıtacaksınız. Sorumluluklar Potansiyel müşterilere telefonla ulaşarak ürünlerimizi tanıtmak Müşteri taleplerini dinleyerek, uygun çözümler sunmak Satış hedeflerini gerçekleştirmek için stratejiler geliştirmek Müşteri geri bildirimlerini toplamak ve raporlamak Ekip içi işbirliğini sağlamak ve bilgi paylaşımında bulunmak Aranan Nitelikler Tele satış veya çağrı merkezi alanında 1-3 yıl deneyim Güçlü iletişim ve ikna becerileri Müşteri odaklı yaklaşım Hedef odaklı çalışma yeteneği Takım çalışmasına yatkınlık Sunduklarımız Aylık 5.000 - 50.000 TRY maaş aralığı Profesyonel gelişim fırsatları Dinamik ve destekleyici bir çalışma ortamı Performansa dayalı prim sistemi',
    'FullTime',
    'OnSite',
    'UNSPECIFIED',
