INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a093ca-a045-7e76-af86-aa8c7e7c4ef5',
    'erdaltopcuoglusigorta-aracilik-hizmetleri-ofis-yoneticisi-part-time-mugla-1000309',
    'Ofis Yöneticisi (Part-Time)',
    'ERDAL_TOPCUOGLU_SIGORTA ARACILIK HİZMETLERİ',
    'Pozisyon Hakkında E-ticaret sistemimizi yönetecek ve ofis içi süreçleri organize edecek bir Ofis Yöneticisi arıyoruz. Bu pozisyonda, iş disiplinine sahip, hedefleri olan ve sürekli gelişime açık bir takım arkadaşı arıyoruz. Sorumluluklar Ofis içi süreçleri yönetmek ve düzenlemek E-ticaret sisteminin günlük operasyonlarını takip etmek MS Office programlarını etkin bir şekilde kullanmak İlgili bölümlerle iletişim kurarak iş akışını sağlamak İş hedeflerine ulaşmak için gerekli adımları atmak Aranan Nitelikler İlgili bölümden eğitim almış olmak Öğrenci veya yeni mezun olmak MS Office programlarına hakimiyet İş disiplini ve süreklilik gösterebilme yeteneği [şehir] ve çevresinde ikamet eden Sunduklarımız Esnek çalışma saatleri Gelişim fırsatları Dinamik bir çalışma ortamı',
    'FullTime',
    'OnSite',
    'NEW_GRADUATE',
