INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a0aeaf-aaff-7f5a-aea0-84b09875a6ed',
    'bildirici-gida-magaza-satis-danismani-ve-kasiyer-1000348',
    'MAĞAZA SATIŞ DANIŞMANI VE KASİYER',
    'BILDIRICI GIDA',
    'İş İlanı Hakkında Mağazacılık sektöründe hizmet veren şirketimizin, [şehir] tüm Marketlerinde görevlendirmek üzere, 1-İnsan ilişkilerinde başarılı, 2-Güler yüzlü, dinamik, hızlı, girişken, güvenilir, 3-İkna gücüne inanan ve hesap işlerinde kendine güvenen 3-Esnek çalışma saatlerine uyum sağlayıp, vardiyalı çalışabilecek 4-İş disiplinine sahip, ekip çalışmasına uyumlu, 5- Tecrübeli, Tecrübesiz Müşteri memnuniyeti odaklı çalışacak takım arkadaşları arıyoruz… İŞ TANIMI Daha önce tecrübesi olmayan adaylara eğitim verilmektedir.',
    'FullTime',
