INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a0af88-903a-781d-925b-e347f509babe',
    'akturk-geri-donusum-mutfak-and-temizlik-personeli-1000352',
    'MUTFAK & TEMİZLİK PERSONELİ',
    'AKTURK GERI DÖNÜŞÜM',
    'Takımımıza dahil olacak profesyonelde aradığımız temel özellikler ve iş kapsamı: Mutfak ve Temizlik Personeli bünyemizde görev alacak yetkin adaylar değerlendirilecektir. 📌 Görev Tanımı Ofislerin ve ortak kullanım alanlarının günlük temizliğini yapmak, Patron ve misafirlerini karşılamak, çay-kahve-ikram servisi yapmak. Çalışanların çay, kahve ve benzeri ikramlarını servis yapmak, Mutfak düzenini ve temizliğini sağlamak, Yemek sonrası mutfak ve kullanılan ekipmanların temizliğini yapmak, Hijyen ve temizlik kurallarına uygun şekilde çalışmak, 📌 Aranan Nitelikler Temizlik ve mutfak işlerinde deneyimli, Hijyen kurallarına önem veren, Düzenli, titiz ve sorumluluk sahibi, Ekip çalışmasına uyumlu, Yoğun çalışma temposuna uyum sağlayabilecek, Daha önce fabrika veya iş yeri ortamında çalışmış. 📍 Çalışma Yeri: [şehir]/ Sarıhamzalı bölgesi 💼 Pozisyon: Mutfak & Temizlik Personeli ⏰ Çalışma Şekli: Tam zamanlı',
    'FullTime',
    'OnSite',
    'UNSPECIFIED',
