INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a0af95-2537-794f-b769-aa547f4fbfa6',
    'akturk-geri-donusum-on-muhasebe-personeli-araniyor-1000353',
    'ÖN MUHASEBE PERSONELİ ARANIYOR',
    'AKTURK GERI DÖNÜŞÜM',
    'Kadın Ön Muhasebe Personeli ekibimize katılacak çalışma arkadaşı aranmaktadır. 📌 Görev Tanımı Günlük ön muhasebe işlemlerinin yürütülmesi, Alış ve satış faturalarının düzenlenmesi, sisteme işlenmesi ve takibi, Cari hesapların kontrolü ve mutabakatların yapılması, Kasa ve banka hareketlerinin takibi, E-fatura / e-arşiv süreçlerinin yürütülmesi, Alış ve satış evraklarının düzenlenmesi ve arşivlenmesi, Resmî muhasebe süreçlerinin takibi ve muhasebe kayıtlarının kontrolü, KDV beyannamesi başta olmak üzere ilgili beyannamelerin hazırlanma ve takip süreçlerine hâkim olunması, Muhasebe kayıtlarının mevzuata uygun şekilde takip edilmesi, Mali müşavir ile koordineli çalışılması, Gerekli muhasebe raporlarının hazırlanması. 📌 Aranan Nitelikler Kadın adaylar, Ön muhasebe ve resmî muhasebe süreçlerinde deneyimli, Geri dönüşüm sektöründe muhasebe deneyimi bulunan adaylara öncelik verilecektir, KDV beyannamesi ve beyanname süreçlerinin takibinde deneyimli, Fatura, cari hesap, kasa ve banka işlemlerine hâkim, Logo veya benzeri muhasebe programlarını etkin kullanabilen, E-fatura ve e-arşiv uygulamalarına hâkim, MS Office programlarını kullanabilen, Muhasebe mevzuatı konusunda bilgi sahibi, Dikkatli, düzenli ve sorumluluk sahibi, Takip ve iletişim becerileri güçlü, Mali müşavir ve diğer departmanlarla koordineli çalışabilecek. 📍 Çalışma Yeri: [şehir] / Sarıhamzalı Bölgesi 💼 Pozisyon: Ön Muhasebe Personeli ⏰ Çalışma Şekli: Tam zamanlı Geri dönüşüm sektöründe muhasebe deneyimi bulunan ve KDV/beyanname süreçlerine hâkim adaylara öncelik verilecektir.',
    'FullTime',
    'OnSite',
    'SPECIALIST',
    '{"slug": "akturk-geri-donusum-on-muhasebe-personeli-araniyor-1000353", "title": "ÖN MUHASEBE PERSONELİ ARANIYOR", "_docId": "01a0af95-253e-7afb-9706-716648eb3098", "branchId": "704f2adf-3df9-4d48-9fe7-4c420a1c4cad", "industry": "FINANCE_ACCOUNTING", "location": {"latitude": 37.2612315, "longitude": 35.3905046, "__typename": "Location", "city": "Adana"}, "stateIds": ["019d61b4-d093-76aa-8ef6-530681ba33d1"], "accountId": "a92d71c4-e903-49cb-97bf-8e493ec1d00b", "companyId": "c0b68b6f-9e18-4591-b08a-466fa931c96f", "createdAt": "2026-09-17T13:36:22.341Z", "locations": [{"latitude": 37.2612315, "longitude": 35.3905046, "__typename": "Location"}], "maxSalary": 60000, "minSalary": 50000, "updatedAt": "2026-09-17T13:52:20.288Z", "__typename": "AdvertisementSearchResult", "isFeatured": true, "languageId": "019d61b4-cffd-72da-b0fb-15f0ded42ef2", "salaryType": "Monthly", "sortWeight": 0, "description": "<p><strong>Aktürk Geri Dönüşüm</strong> bünyesinde görevlendirilmek üzere <strong>Kadın Ön Muhasebe Personeli</strong> istihdam edilecektir.</p><h3>📌 Görev Tanımı</h3><ul><li><p>Günlük ön muhasebe işlemlerinin yürütülmesi,</p></li><li><p>Alış ve satış faturalarının düzenlenmesi, sisteme işlenmesi ve takibi,</p></li><li><p>Cari hesapların kontrolü ve mutabakatların yapılması,</p></li><li><p>Kasa ve banka hareketlerinin takibi,</p></li><li><p>E-fatura / e-arşiv süreçlerinin yürütülmesi,</p></li><li><p>Alış ve satış evraklarının düzenlenmesi ve arşivlenmesi,</p></li><li><p><strong>Resmî muhasebe süreçlerinin takibi ve muhasebe kayıtlarının kontrolü,</strong></p></li><li><p><strong>KDV beyannamesi başta olmak üzere ilgili beyannamelerin hazırlanma ve takip süreçlerine hâkim olunması,</strong></p></li><li><p>Muhasebe kayıtlarının mevzuata uygun şekilde takip edilmesi,</p></li><li><p>Mali müşavir ile koordineli çalışılması,</p></li><li><p>Gerekli muhasebe raporlarının hazırlanması.</p></li></ul><h3>📌 Aranan Nitelikler</h3><ul><li><p><strong>Kadın adaylar,</strong></p></li><li><p>Ön muhasebe ve resmî muhasebe süreçlerinde deneyimli,</p></li><li><p><strong>Geri dönüşüm sektöründe muhasebe deneyimi bulunan adaylara öncelik verilecektir,</strong></p></li><li><p><strong>KDV beyannamesi ve beyanname süreçlerinin takibinde deneyimli,</strong></p></li><li><p>Fatura, cari hesap, kasa ve banka işlemlerine hâkim,</p></li><li><p><strong>Logo veya benzeri muhasebe programlarını etkin kullanabilen,</strong></p></li><li><p>E-fatura ve e-arşiv uygulamalarına hâkim,</p></li><li><p>MS Office programlarını kullanabilen,</p></li><li><p>Muhasebe mevzuatı konusunda bilgi sahibi,</p></li><li><p>Dikkatli, düzenli ve sorumluluk sahibi,</p></li><li><p>Takip ve iletişim becerileri güçlü,</p></li><li><p>Mali müşavir ve diğer departmanlarla koordineli çalışabilecek.</p></li></ul><p>📍 <strong>Çalışma Yeri:</strong> [şehir] / Sarıhamzalı Bölgesi<br>💼 <strong>Pozisyon:</strong> Ön Muhasebe Personeli<br>⏰ <strong>Çalışma Şekli:</strong> Tam zamanlı</p><p><strong>Geri dönüşüm sektöründe muhasebe deneyimi bulunan ve KDV/beyanname süreçlerine hâkim adaylara öncelik verilecektir.</strong></p><p></p>", "publishedAt": "2026-09-17T13:54:59.330Z", "currencyCode": "TRY", "positionLevel": "SPECIALIST", "professionIds": ["01a04336-d50a-71d0-9e8d-939d075fa2f8", "01a04336-d505-7182-8ba4-13052d537d27"], "isConfidential": false, "advertisementId": "01a0af95-2537-794f-b769-aa547f4fbfa6", "isMostPreferred": false, "statusUpdatedAt": "2026-09-17T13:54:59.330Z", "companyShortName": "AKTURK GERI DÖNÜŞÜM", "locationSourceType": "Cities", "advertisementNumber": "1000353", "advertisementStatus": "Approved", "advertisementJobType": "FullTime", "advertisementModeOfOperation": "OnSite", "advertisementRecruitmentProcess": {"id": "01a0af86-9f15-74c3-8fb8-83c607793db8", "data": {"edges": [{"id": "edge-fast-0", "type": "smoothstep", "source": "node-fast-0", "target": "node-fast-1", "condition": "pass"}, {"id": "edge-fast-1", "type": "smoothstep", "source": "node-fast-1", "target": "node-fast-2"}], "nod