INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a0afa6-7cda-71de-b8da-e25c8fcae6c1',
    'isin-olacak-insan-kaynaklari-stajyeri-ofis-zorunlu-staj-1000354',
    'İnsan Kaynakları Stajyeri (Ofis - Zorunlu Staj)',
    'İŞİN OLACAK',
    'Pozisyon Hakkında İnsan Kaynakları departmanımızda, dinamik bir ekip içinde yer alacak bir İnsan Kaynakları Stajyeri arıyoruz. Bu pozisyonda, stajyer olarak temel insan kaynakları süreçlerini öğrenme ve uygulama fırsatı bulacaksınız. Sorumluluklar İnsan kaynakları süreçlerine destek vermek Aday tarama ve mülakat süreçlerine katılmak Çalışan dosyalarının düzenlenmesi ve güncellenmesi Eğitim ve gelişim programlarının organizasyonuna yardımcı olmak Çeşitli raporlamalar ve veri analizi yapmak Aranan Nitelikler Üniversite öğrencisi veya yeni mezun İletişim becerileri güçlü Takım çalışmasına yatkın Öğrenmeye açık ve proaktif bir yaklaşım sergileyen MS Office programlarına hakim Sunduklarımız Profesyonel bir çalışma ortamı Eğitim ve gelişim fırsatları Deneyim kazanma imkanı Dinamik bir ekip içinde yer alma fırsatı',
    'FullTime',
    'OnSite',
    'INTERN',
