INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01a0b329-5987-7ae5-be11-1cb046ca30fd',
    'synapse-lynk-danisma-maasli-psikolog-1000355',
    'Maaşlı Psikolog',
    'SYNAPSE LYNK DANISMA',
    'Synapse Lynk bünyesinde faaliyet gösteren Danışan Ağı olarak, ruh sağlığı uzmanlarının yalnızca mesleğine odaklandığı bir çalışma düzeni kuruyoruz. Kurumsal anlaşmalarımız sayesinde uzmanlarımıza düzenli danışan akışı sağlıyor; tüm yasal, operasyonel ve özlük hakları süreçlerini biz üstleniyoruz. Maaşlı, tamamen online ve kendi saatlerinde çalışmak isteyen psikolog / klinik psikolog arıyoruz. Başvuran tüm uzmanlar, Danışan Ağı standartlarını ve portal kullanımını içeren zorunlu bir eğitim programından geçer. Bu eğitim sonunda başarılı olan ve istihdam edilmeye uygun görülen adaylarla 1 yıllık freelance sözleşme imzalanır. Uzmanlarımız tamamen home office ve kendi takvimlerine göre çalışır. Mesai zorunluluğu yoktur. Yapay zeka destekli portalımız üzerinden uzmanlara haftalık belirli sayıda danışan yönlendirilir. Uzmanlardan beklenen, yönlendirilen her danışanla ilk görüşmeyi yapmak ve detaylı anamnez almaktır. Danışanlarla uzun vadeli seans planlaması yapma zorunluluğu bulunmamaktadır. Uzmanlar, portal üzerinden danışanlarla mesaj yoluyla iletişim kurarak kendi müsaitlik ve takvim bilgilerine göre randevuları planlayabilir. Haftalık çalışma süresi yaklaşık 10 saattir. Haftalık yönlendirilen maksimum danışan sayısı 20 kişidir. Eğitim programı ve çalışma modülleri hakkında tüm detaylar başvuru yapan adaylarla paylaşılacaktır.',
    'FullTime',
    'Remote',
    'SPECIALIST',
