INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '01ded707-699a-46aa-a3f0-1db2a8da5537',
    'roketsan-ar-ge-tasar-m-m-hendisi-sim-lasyon-termal-1001197',
    'Ar-Ge Tasarım Mühendisi (Simülasyon & Termal)',
    'ROKETSAN',
    'Takımımıza dahil olacak profesyonelde aradığımız temel özellikler ve iş kapsamı: ''Ar-Ge Tasarım Mühendisi (Simülasyon & Termal)'' bünyemizde görev alacak yetkin adaylar değerlendirilecektir. Rolün Getirdiği Başlıca Görevler: Ansys Fluent kullanarak termal ve akışkanlar mekaniği analizleri yapacak, savunma sanayii savunma sistemleri tasarlayacak. Kimleri Arıyoruz? - Tasarım ve analiz programlarından (SolidWorks, Catia, AutoCAD, TIA Portal, Ansys vb.) en az birine hakim - Saha problemlerinde kök neden analizi yapabilen, çözüm odaklı mühendis - Teknik dokümantasyon, FMEA, proses kontrol ve kalite planlarını hazırlayacak - Pazartesi - Cuma günleri tam zamanlı, hafta sonu tatil',
    'FullTime',
    'OnSite',
    'SPECIALIST',
    '{"slug": "roketsan-ar-ge-tasar-m-m-hendisi-sim-lasyon-termal-1001197", "title": "Ar-Ge Tasarım Mühendisi (Simülasyon & Termal)", "_docId": "237d745a-9915-408c-ad63-d727947750a3", "industry": "INDUSTRIAL_MANUFACTURING", "location": {"city": "Ankara", "__typename": "Location", "district": "Elmadağ"}, "createdAt": "2026-09-30T10:00:00.000Z", "isFeatured": false, "description": "<p>ROKETSAN bünyesinde [şehir] lokasyonunda istihdam edilmek üzere <strong>Ar-Ge Tasarım Mühendisi (Simülasyon & Termal)</strong> istihdam edilecektir.</p><p><strong>İş Tanımı ve Görevler:</strong></p><p>Ansys Fluent kullanarak termal ve akışkanlar mekaniği analizleri yapacak, savunma sanayii savunma sistemleri tasarlayacak.</p><p><strong>Adaylarda Aranan Şartlar ve Nitelikler:</strong></p><ul><li>Tasarım ve analiz programlarından (SolidWorks, Catia, AutoCAD, TIA Portal, Ansys vb.) en az birine hakim</li><li>Saha problemlerinde kök neden analizi yapabilen, çözüm odaklı mühendis</li><li>Teknik dokümantasyon, FMEA, proses kontrol ve kalite planlarını hazırlayacak</li><li>Pazartesi - Cuma günleri tam zamanlı, hafta sonu tatil</li></ul>", "positionLevel": "SPECIALIST", "advertisementId": "01ded707-699a-46aa-a3f0-1db2a8da5537", "companyShortName": "ROKETSAN", "advertisementJobType": "FullTime", "advertisementModeOfOperation": "OnSite", "category": "INDUSTRIAL_MANUFACTURING", "jobType": "FullTime", "modeOfOperation": "OnSite"}'::jsonb,
    'INDUSTRIAL_MANUFACTURING'
);

INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    '020a56ab-9a00-408d-b721-dde37226141d',
    'danfoss-turkiye-satis-muhendisi-020a56ab',
    'Satış Mühendisi',
    'Danfoss Türkiye İklimlendirme ve Isıtma Çözümleri',
    'Danfoss Türkiye bünyesinde [şehir] ofisimizde ticari binalar, endüstriyel tesisler ve konut projeleri için enerji verimli iklimlendirme, vanalar ve ısıtma sistemleri satışını gerçekleştirecek Satış Mühendisi arıyoruz.

Görev Tanımı ve Sorumluluklar:
- Mekanik tesisat taahhüt firmaları, proje tasarım ofisleri ve OEM üreticilerini ziyaret ederek Danfoss ürün ve sistemlerinin projelerde yer almasını sağlamak.
- Mekanik tesisat projelerini (HVAC, hidronik balanslama, yerden ısıtma, frekans konvertörleri) inceleyerek teknik seçimler ve hidrolik hesaplamalar yapmak.
