    'OnSite',
    'SENIOR',
    '{"title": "Dağıtık Sistemler ve Konsensüs Mühendisi", "jobType": "PartTime", "category": "IT_SOFTWARE", "language": "TR", "location": {"city": "İstanbul"}, "positionLevel": "SENIOR", "modeOfOperation": "OnSite", "companyShortName": "Midas Finansal Teknolojiler"}'::jsonb,
    'IT_SOFTWARE'
);

