    '{"title": "Mobil Uygulama Geliştirici", "jobType": "FullTime", "category": "IT_SOFTWARE", "language": "TR", "location": {"city": "İzmir"}, "positionLevel": "MID_LEVEL", "modeOfOperation": "Hybrid", "companyShortName": "Papara Mobil Geliştirme Ekibi"}'::jsonb,
