);

INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    'e2442976-3c48-400d-843f-4c3b202837c4',
    'peak-games-oyun-seviye-tasarimcisi-e2442976',
    'Oyun Seviye Tasarımcısı (Level Designer)',
    'Peak Games',
    'Dünyanın dört bir yanındaki milyonlarca oyuncuya hitap eden Peak Games bünyesinde [şehir] ofisimizde oyun deneyiminin kalbini oluşturan seviyeleri ve mekanik bulmacaları tasarlayacak Oyun Seviye Tasarımcısı arıyoruz.

Görev Tanımı ve Sorumluluklar:
- Casual / puzzle oyunlarımız için bağımlılık yaratıcı, yenilikçi ve dengeli seviyeler tasarlamak.
- Yeni oyun mekaniklerinin (bloklar, engeller, kombolar) kademeli olarak öğretildiği ve ustalaşıldığı pürüzsüz bir onboarding ve zorluk eğrisi kurgulamak.
- Seviyelerin ham prototiplerini oluşturmak, oynanabilirlik testlerini gerçekleştirmek ve seviye akışındaki (pacing) tıkanıklıkları gidermek.
- Veri analitiği araçları üzerinden seviye geçiş başarı oranlarını (churn, drop-off, win-rate, move count) günlük olarak takip edip seviye ayarlamaları yapmak.
- Seviye havuzunu düzenli olarak genişletmek ve sezonluk canlı etkinlikler (live-ops) için özel temalı bölümler üretmek.

Aranan Nitelikler:
- Lisans derecesine sahip, oyun tasarımı ve mekanik kurgu konusunda tutkulu.
- Mobil bulmaca veya casual oyunlarda Seviye Tasarımı (Level Design) alanında en az 2 yıl deneyimli.
- Bulmaca mekanikleri, oyuncu psikolojisi, ödül hissi ve bölüm akışı prensiplerine hakim.
- Analitik düşünebilen, oyuncu geri bildirimlerini ve veriyi tasarım kararlarına dönüştürebilen.
- Ekip çalışmasına yatkın, hızlı iterasyon yapabilen ve yaratıcı çözümler üreten.',
    'FullTime',
    'Remote',
    'SPECIALIST',
    '{"title": "Oyun Seviye Tasarımcısı (Level Designer)", "jobType": "FullTime", "category": "CREATIVE_DESIGN", "language": "TR", "location": {"city": "Ankara"}, "positionLevel": "SPECIALIST", "modeOfOperation": "Remote", "companyShortName": "Peak Games"}'::jsonb,
    'CREATIVE_DESIGN'
);

INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
