INSERT INTO job_advertisements (id, slug, title, company_name, description, job_type, mode_of_operation, position_level, raw_data, industry) VALUES (
    'dbf1d422-68fe-5d47-887c-47d82ea0342c',
    'hareket-proje-tasimaciligi-ve-montaj-hizmetleri-agir-yuk-ve-lowbed-dorseli-cekici-soforu-600014',
    'Ağır Yük ve Lowbed Dorseli Çekici Şoförü',
    'Hareket Proje Taşımacılığı ve Montaj Hizmetleri',
    'Rüzgar türbin kanatları, trafolar, ekskavatörler ve endüstriyel kazanlar gibi gabari dışı ağır yüklerin hidrolik akslı lowbed dorselerle taşınmasında görev alacak Uzman Çekici Şoförü arıyoruz.

